// ── Types ────────────────────────────────────────────────────────────────────

/** A command extracted from the AST with wrapper commands (sudo, env, etc.) resolved */
export interface ResolvedCommand {
    name: string;               // resolved command name (e.g., "rm", "aws", "kubectl")
    args: string[];             // argument values after wrapper stripping
    raw: string;                // original text for error messages
    env?: string[];             // NAME=value assignments applied to this command (prefix or `env` wrapper)
    chdir?: string;             // working directory set by an `env -C/--chdir` wrapper
    onecliAgent?: string;       // the identity an `onecli run --agent <id> --` wrapper runs it under
    hasInputRedirect: boolean;  // true if command has << or <<< redirects
    pos?: number;               // source offset when produced by the AST parser
    stdinTexts?: string[];      // heredoc and here-string text fed to this command
    stdinExpanded?: ExpandableWord[]; // the part of stdinTexts bash expands (not a quoted heredoc or '…' here-string)
    stdinFiles?: string[];      // files redirected into this command with `<`
    stdoutFiles?: string[];     // files this command's output is redirected into
    pipedInput?: PipedInput;    // what its pipeline feeds a command inside `$(…)`, whose offset can't key pipedInto
    argsAreValues?: boolean;    // pos is not this command's own, so its args are expanded from their values, not the view's words
    expandAs?: ResolvedCommand[] | null; // inside `$(…)`: the views its words expand in; null past the cap, so they're unknown
    script?: ScriptContext;     // what the whole command line shows, shared by its commands
}

/** Facts about the whole command line that a single step's checks need. */
export interface ScriptContext {
    writes: FileWrite[];        // what echo/printf/cat/tee write to files
    pipedInto: Map<number, PipedInput>; // what the previous stage of a pipeline feeds each command, by command offset
    cds: CdStep[];              // every cd/pushd/popd, in source order
    links: Map<number, ChainLink>; // where each top-level command sits in its &&/|| chain, by command offset
    command: string;            // the whole command line, for resolving variables
    cwd?: string;               // the directory the command line starts in
    view?: ReturnType<typeof viewShell>; // the parsed variable view of `command`, built on first use
    words?: Map<string, string | null>; // provableWord results by position and text
    paths?: Map<string, string[] | null>; // sqlPathCandidates results by reader position and file
    writesByTarget?: Map<string, FileWrite[]>; // writes by the path as spelled, built once a line has too many to match pairwise
    wordBudget?: number;        // evalWord calls left for this command line before every further word is unprovable
    traceBudget?: number;       // pipe nodes and texts left to trace before a client's input counts as unknown
}

// evalWord calls one command line may spend resolving paths. Each reader re-resolves every write and cd, so without a
// line-wide budget a hostile command multiplies the work by its reader count; no real command needs a tenth of this.
const SQL_WORD_BUDGET = 256;

interface FileWrite {
    writer: ResolvedCommand;
    target: string;             // the path as the writer spells it
    input: PipedInput;
}

interface PipedInput {
    texts: string[];            // text echo/printf/cat emit into the pipe
    catFiles: string[];         // files cat reads into it
    from?: PipedInput[];        // inputs whose text and files also flow in
    textFrom?: PipedInput[];    // inputs whose text (not files) also flows in
    emitters?: ResolvedCommand[]; // emitters whose words hold a variable, expanded only when a SQL client traces them
    unknown?: boolean;          // its text can't be worked out (a substitution past the expansion cap), so a reader gates
}

/**
 * Everything an input carries, following its `from` links. Inputs link to each other instead of copying, because a
 * copy at each nesting level made deep pipelines cost the cube of their depth; each node is visited once.
 */
function flattenInput(root: PipedInput | undefined, script?: ScriptContext): FlatInput {
    if (!root) return { texts: [], catFiles: [] };
    const cached = flattened.get(root);
    if (cached) return cached;
    const texts: string[] = [];
    const catFiles: string[] = [];
    const seen = new Set<PipedInput>();
    const textSeen = new Set<PipedInput>();
    const stack: Array<[PipedInput, boolean]> = [[root, true]];
    let over = false;
    while (stack.length) {
        const [node, withFiles] = stack.pop()!;
        if (withFiles ? seen.has(node) : textSeen.has(node) || seen.has(node)) continue;
        (withFiles ? seen : textSeen).add(node);
        if (!spendTrace(script, 1 + textSize(node.texts) + node.catFiles.length)) {
            over = true;
            break;
        }
        texts.push(...node.texts);
        if (node.unknown) {
            over = true;
            break;
        }
        for (const emitter of node.emitters ?? []) {
            const expanded = expandedEmitter(emitter);
            if (expanded === null) over = true;
            else texts.push(...emittedText(expanded));
        }
        if (over) break;
        if (withFiles) catFiles.push(...node.catFiles);
        for (const next of node.from ?? []) stack.push([next, withFiles]);
        for (const next of node.textFrom ?? []) stack.push([next, false]);
    }
    const result = { texts, catFiles, ...(over ? { over } : {}) };
    flattened.set(root, result);
    return result;
}

interface FlatInput {
    texts: string[];
    catFiles: string[];
    over?: boolean;             // the line's trace budget ran out, so this is incomplete
}

const flattened = new WeakMap<PipedInput, FlatInput>();

/** Charges `n` units to the line's trace budget; false once it is spent. */
/** Shell words to expand, each beside the value it has unexpanded; a heredoc body is expanded as if double-quoted. */
type ExpandableWord = { word: string; plain: string; joinSplit?: boolean };

const heredocWord = (t: string): ExpandableWord => ({ word: `"${t.replace(/(["\\])/g, '\\$1')}"`, plain: t });

/**
 * An unquoted heredoc body as a double-quoted word: in both, a backslash quotes only `$`, a backtick, a backslash and a
 * newline. A `"` is literal in the body, and so is a backslash before one, so both are escaped for the word.
 */
const heredocBodyWord = (t: string): ExpandableWord => ({
    word: `"${t.replace(/\\[\s\S]|"/g, m => (m === '"' ? '\\"' : m === '\\"' ? '\\\\\\"' : m))}"`,
    plain: t,
});

/** Each of `cmd`'s arguments as written (quotes included), when the parsed command line has it. */
function argumentWords(cmd: ResolvedCommand, joinSplit = false): ExpandableWord[] {
    const script = cmd.script;
    if (cmd.pos === undefined || !script || !cmd.args.some(a => /[$`]/.test(a))) return [];
    if (cmd.argsAreValues) return cmd.args.map(a => ({ ...heredocWord(a), joinSplit }));
    script.view ??= viewShell(script.command);
    // Brace expansion turns one written word into several arguments, so the written words are expanded the same way.
    const texts = script.view.commandAt(cmd.pos)?.argTexts
        ?.flatMap(t => (t.includes('{') ? braceExpand(t)?.filter(w => w !== '') ?? [t] : [t]));
    if (!texts || texts.length < cmd.args.length) return [];
    return texts.slice(texts.length - cmd.args.length).map((word, i) => ({ word, plain: cmd.args[i], joinSplit }));
}

/**
 * The value of each word whose provable variables change it (a word without one, or whose variables stay unknown, is
 * left out); null once the line's word or trace budget runs out.
 */
function expandWords(words: ExpandableWord[], cmd: ResolvedCommand): string[] | null {
    const out: string[] = [];
    const script = cmd.script;
    if (cmd.pos === undefined || !script) return out;
    for (const { word, plain, joinSplit } of words) {
        if (!/[$`]/.test(word)) continue;
        script.wordBudget ??= SQL_WORD_BUDGET;
        if (script.wordBudget-- <= 0) return null;
        script.view ??= viewShell(script.command);
        const r = evalWord(word, script.view, cmd.pos, false, joinSplit);
        if (r.value === plain) continue;
        if (!spendTrace(script, r.value.length)) return null;
        out.push(r.value);
    }
    return out;
}

/** An emitter with its arguments and expanded heredoc input after variable expansion, or null over budget. */
function expandedEmitter(cmd: ResolvedCommand): ResolvedCommand | null {
    const words = argumentWords(cmd, true);
    const args = [...cmd.args];
    const values: string[] = [];
    // The argv the command actually gets, word by word: an unquoted value splits into several.
    const argv: string[] = [];
    for (let i = 0; i < words.length; i++) {
        const e = expandWords([words[i]], cmd);
        if (e === null) return null;
        if (e.length) args[i] = e[0];
        const quoted = /^"[\s\S]*"$/.test(words[i].word) || /^'[\s\S]*'$/.test(words[i].word);
        // echo reads options only before its first operand.
        const atOptions = argv.every(t => /^-[neE]+$/.test(t));
        argv.push(...(e.length && !quoted ? e[0].split(/\s+/).filter(Boolean) : [args[i]]));
        // cat and tee name files with their operands; only echo and printf write them as text.
        if (cmd.name !== 'echo' && cmd.name !== 'printf') continue;
        // Only an unquoted value splits, so only there can a leading word become an option echo drops.
        const unquoted = !/^"[\s\S]*"$/.test(words[i].word);
        // Only the options echo takes are dropped: `echo -- x` prints `-- x`, a SQL comment.
        values.push(...e.flatMap(v => (unquoted && atOptions && cmd.name === 'echo' ? [v, v.replace(/^(?:-[neE]+\s+)+/, '')] : [v])));
    }
    // A leading `printf -v NAME` (from one word or several) assigns the output instead of printing it.
    if (cmd.name === 'printf' && /^-v/.test(argv[0] ?? '')) return { ...cmd, args: [], stdinTexts: [] };
    const stdin = expandWords(cmd.stdinExpanded ?? [], cmd);
    // Each value is scanned whole and without leading option words too: an unquoted `-e DROP …` splits into an option
    // and the SQL echo prints, while emittedText would drop the joined word as an option.
    return stdin === null ? null : { ...cmd, args, stdinTexts: [...(cmd.stdinTexts ?? []), ...stdin, ...values] };
}

function spendTrace(script: ScriptContext | undefined, n: number): boolean {
    if (!script) return true;
    script.traceBudget = (script.traceBudget ?? SQL_TRACE_BUDGET) - n;
    return script.traceBudget >= 0;
}

// Characters of SQL text (plus pipe nodes walked) one command line may trace into its SQL clients, counting a text again
// for every client it reaches, since each one scans it. Past it the client's input is unknown and the command gates: no
// real command comes near it, and a crafted one must neither hang the guard nor pass.
const SQL_TRACE_BUDGET = 4_000_000;

function textSize(texts: string[]): number {
    let n = 0;
    for (const t of texts) n += t.length;
    return n;
}

/** A command's place in a top-level list: which chain, which link, and the operators joining the links. */
interface ChainLink {
    chain: number;
    index: number;
    operators: string[];
}

interface CdStep {
    pos: number;
    target: string | undefined;
}

export interface DestructiveMatch {
    pattern: string;
    statement: string;
}

export type GateDecision = 'approved' | 'denied' | 'timeout';

/** Outcome of evaluating a bash command against all guard tiers. */
export interface GateEvaluation {
    action: 'allow' | 'block' | 'gate';
    reason?: string;
}

// ── git-clone destination guard (ADVISORY workflow nudge — NOT a security boundary) ──
// The agent already has RW to every managed dir, so this does NOT prevent
// access; it nudges agents toward the create_worktree / clone_repo MCP tools
// (credential scoping, auto-commit safety, index registration) instead of an
// ad-hoc `git clone`. It blocks a `git clone` whose command text contains a
// literal managed-dir path (incl. clone-to-/tmp-then-`mv` where that path is
// literal). KNOWN, ACCEPTED RESIDUAL BYPASSES (advisory, not airtight):
//   • a bare `git clone <url>` with NO path lands in the cwd (often
//     /workspace/agent) — not caught: no literal managed path in the command;
//   • `git -C <managed> clone`, a renamed git binary, a pre-staged symlink, and
//     `cd <managed>; git clone <url> rel/dir` also evade it.
// Closing these needs cwd+relative-target resolution; deferred. The real
// enforcement is that clone_repo is the sanctioned path. (The sibling
// snowflake-connector guard labels itself the same way.)
//
// SINGLE SOURCE OF TRUTH for all provider adapters (Claude SDK hook, OpenCode
// plugin, Codex runner). The conformance suite pins these verdicts; do not fork
// the policy into a provider adapter.
export const GIT_CLONE_RE = /\bgit\s+clone\b/;
export const GIT_CLONE_MANAGED_DIR_RE = /\/workspace\/(?:agent|worktrees|workgroup|global|extra|thread|plugins)\b/;
export const GIT_CLONE_BLOCK_REASON =
    'Ad-hoc `git clone` into a managed dir (/workspace/{agent,worktrees,workgroup,...}) is blocked. Use the `create_worktree` MCP tool for an existing repo, or `clone_repo` to add a new one. If the clone is ephemeral, keep the entire command within /tmp.';

// ── Snapshot git-mutation guard (ADVISORY) ──
// Repo-store rework: the old canonical paths (/workspace/workgroup/<repo>)
// are read-only browsing snapshots of origin/HEAD, advanced by the host.
// Mutating git commands aimed there ("cd into the canonical and checkout a
// branch") are the stale-tree failure mode the topology exists to kill. The
// RO bind mount is the real enforcement (EROFS); this evaluator exists to
// give a *useful* message instead of a bare filesystem error.
//
// It decides on the git invocation's TARGET, not on the command text: a
// mutating verb blocks only when `-C`, `--git-dir`, `--work-tree`, `GIT_DIR`,
// `GIT_WORK_TREE`, a `worktree` path argument, or a preceding `cd` in the same
// command resolves into a snapshot. A snapshot path passed as a file argument
// (a patch read by `apply`) or quoted inside a heredoc or string body names no
// target. Accepted residual bypasses, as with the git-clone guard: a relative
// `cd` with no earlier absolute one, a standalone `cd` that fails, a target
// held in a variable that is not a literal assignment in the same command, a
// GIT_DIR/GIT_WORK_TREE exported by an earlier command, a shell function whose
// body runs git in the caller's directory, a wrapper nested under `exec`, and
// git run from another language's subprocess.
//
// Deliberately NOT matched: read-only git verbs (log/status/diff/show/...)
// and the shared non-repo dirs below. The .repos mirrors and .rescues archives
// ARE covered — Bash-level git mutations there are never sanctioned.
export const SNAPSHOT_GIT_MUTATION_VERBS = new Set([
    'checkout', 'switch', 'commit', 'reset', 'restore', 'clean', 'merge', 'rebase',
    'cherry-pick', 'stash', 'am', 'apply', 'update-ref', 'branch', 'worktree',
]);
export const SNAPSHOT_ROOT = '/workspace/workgroup';
export const SNAPSHOT_NON_REPO_DIRS = new Set(['.worktrees', 'memory', 'artifacts', 'claims']);
export const SNAPSHOT_GIT_MUTATION_BLOCK_REASON =
    'Git working-tree mutations under /workspace/workgroup/<repo> are blocked: that path is a read-only snapshot of origin/HEAD maintained by the host. Use `create_worktree` and work in /workspace/worktrees/<repo>; shared long-lived checkouts belong under /workspace/workgroup/.worktrees/.';

/** True when `p` resolves inside /workspace/workgroup/<repo> for a repo snapshot. */
export function isSnapshotRepoPath(p: string): boolean {
    if (!p.startsWith('/')) return false;
    // Lexical only: a realpath would follow a mount's symlinks off the root.
    const normalized = pathResolve(p);
    if (!normalized.startsWith(`${SNAPSHOT_ROOT}/`)) return false;
    const first = normalized.slice(SNAPSHOT_ROOT.length + 1).split('/')[0];
    return first !== '' && !SNAPSHOT_NON_REPO_DIRS.has(first);
}

/** What the snapshot guard knows about the shell at a point in the command:
 *  every directory it may be in, every literal value a variable may hold, and
 *  the pushd stack. An empty set means unknown. Branches that may or may not
 *  run are merged as unions, so a mutation is blocked when ANY path reaching
 *  it targets a snapshot. */
interface SnapshotShellState {
    dirs: Set<string>;
    prev: Set<string>;
    vars: Map<string, Set<string>>;
    stack: Set<string>[];
}

function freshShellState(): SnapshotShellState {
    return { dirs: new Set(), prev: new Set(), vars: new Map(), stack: [] };
}

function forkShellState(state: SnapshotShellState): SnapshotShellState {
    return {
        dirs: new Set(state.dirs),
        prev: new Set(state.prev),
        vars: new Map([...state.vars].map(([k, v]) => [k, new Set(v)])),
        stack: state.stack.map(d => new Set(d)),
    };
}

function mergeShellState(into: SnapshotShellState, other: SnapshotShellState): void {
    for (const d of other.dirs) into.dirs.add(d);
    for (const d of other.prev) into.prev.add(d);
    for (const [k, v] of other.vars) {
        const merged = into.vars.get(k) ?? new Set<string>();
        for (const value of v) merged.add(value);
        into.vars.set(k, merged);
    }
    other.stack.forEach((level, i) => {
        if (!into.stack[i]) into.stack[i] = new Set();
        for (const d of level) into.stack[i].add(d);
    });
}

function isLiteralShellValue(value: unknown): value is string {
    return typeof value === 'string' && value !== '' && !value.includes('$') && !value.includes('`');
}

/** Every absolute path `word` may resolve to, relative entries against `bases`. */
function resolveWord(word: string, bases: Set<string>, state: SnapshotShellState): Set<string> {
    const ref = word.match(EXACT_VARIABLE_REFERENCE);
    const variable = ref?.[1] || ref?.[2];
    const values = variable ? [...(state.vars.get(variable) ?? [])] : [word];
    const out = new Set<string>();
    for (const value of values) {
        if (!isLiteralShellValue(value)) continue;
        if (value.startsWith('/')) out.add(pathResolve(value));
        else for (const base of bases) out.add(pathResolve(base, value));
    }
    return out;
}

/** Every directory a git invocation may read its repository or work tree from. */
function gitTargets(cmd: ResolvedCommand, state: SnapshotShellState): Set<string> {
    const targets = new Set<string>();
    const sub = gitSubcommandIndex(cmd.args);
    let dirs = cmd.chdir !== undefined ? resolveWord(cmd.chdir, state.dirs, state) : state.dirs;
    // git resolves --git-dir/--work-tree against the final -C directory, even
    // when they precede it, so every -C is applied first.
    const pathOptions: string[] = [];
    for (let i = 0; i < sub; i++) {
        const arg = cmd.args[i];
        const eq = arg.match(/^--(?:git-dir|work-tree)=(.*)$/);
        if (eq) { pathOptions.push(eq[1]); continue; }
        if (arg === '-C') dirs = resolveWord(cmd.args[i + 1] ?? '', dirs, state);
        else if (arg === '--git-dir' || arg === '--work-tree') pathOptions.push(cmd.args[i + 1] ?? '');
        else continue;
        i += 1;
    }
    const add = (set: Set<string>) => { for (const t of set) targets.add(t); };
    for (const option of pathOptions) add(resolveWord(option, dirs, state));
    for (const assignment of cmd.env ?? []) {
        const [name, ...rest] = assignment.split('=');
        if (name === 'GIT_DIR' || name === 'GIT_WORK_TREE') add(resolveWord(rest.join('='), dirs, state));
    }
    add(dirs);
    if (cmd.args[sub] === 'worktree') {
        for (const arg of cmd.args.slice(sub + 1)) {
            if (!arg.startsWith('-')) add(resolveWord(arg, dirs, state));
        }
    }
    return targets;
}

const SHELL_DECLARATION_BUILTINS = new Set(['export', 'declare', 'typeset', 'readonly', 'local']);

function setShellVariable(state: SnapshotShellState, name: string, value: unknown): void {
    state.vars.set(name, isLiteralShellValue(value) ? new Set([value]) : new Set());
}

/** `exec [-cl] [-a name] cmd args` runs cmd in place of the shell. */
function unwrapExec(cmd: ResolvedCommand): ResolvedCommand | null {
    let i = 0;
    while (i < cmd.args.length && cmd.args[i].startsWith('-')) i += cmd.args[i] === '-a' ? 2 : 1;
    if (i >= cmd.args.length) return null;
    return { ...cmd, name: cmd.args[i].replace(/^.*\//, ''), args: cmd.args.slice(i + 1) };
}

function snapshotMutationIn(cmd: ResolvedCommand, state: SnapshotShellState): boolean {
    if (cmd.name === 'exec') {
        const inner = unwrapExec(cmd);
        return inner ? snapshotMutationIn(inner, state) : false;
    }
    if (cmd.name === 'unset') {
        for (const name of cmd.args) if (!name.startsWith('-')) state.vars.delete(name);
        return false;
    }
    if (SHELL_DECLARATION_BUILTINS.has(cmd.name)) {
        for (const arg of cmd.args) {
            const m = arg.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/s);
            if (m) setShellVariable(state, m[1], m[2]);
        }
        return false;
    }
    const operand = cmd.args.find(a => !a.startsWith('-'));
    if (cmd.name === 'cd') {
        const next = cmd.args.includes('-') ? state.prev
            : operand ? resolveWord(operand, state.dirs, state) : new Set<string>();
        state.prev = state.dirs;
        state.dirs = next;
        return false;
    }
    if (cmd.name === 'pushd') {
        state.stack.push(state.dirs);
        state.dirs = operand ? resolveWord(operand, state.dirs, state) : new Set<string>();
        return false;
    }
    if (cmd.name === 'popd') {
        state.dirs = state.stack.pop() ?? new Set<string>();
        return false;
    }
    if (cmd.name !== 'git') return false;
    const verb = cmd.args[gitSubcommandIndex(cmd.args)];
    if (!verb || !SNAPSHOT_GIT_MUTATION_VERBS.has(verb)) return false;
    return [...gitTargets(cmd, state)].some(isSnapshotRepoPath);
}

/** Scripts of the command substitutions anywhere inside an AST node. */
function commandSubstitutionScripts(node: unknown, out: any[] = []): any[] {
    if (!node || typeof node !== 'object') return out;
    if (Array.isArray(node)) {
        for (const child of node) commandSubstitutionScripts(child, out);
        return out;
    }
    const record = node as Record<string, unknown>;
    if (record.script && typeof record.script === 'object') {
        out.push(record.script);
        return out;
    }
    // unbash exposes a word's `parts` as a prototype getter, not an own key.
    commandSubstitutionScripts(record.parts, out);
    for (const value of Object.values(record)) commandSubstitutionScripts(value, out);
    return out;
}

/** Walk the AST in execution order. Subshells, command substitutions and
 *  multi-command pipeline stages run on a copy of the state; each later
 *  element of an `&&`/`||` list may or may not run, so its outcome is merged
 *  in rather than replacing the state. */
function walkSnapshotNode(node: any, state: SnapshotShellState): boolean {
    if (!node) return false;
    if (node.type === 'Command') {
        const words = [node.name, node.prefix, node.suffix, node.redirects];
        if (commandSubstitutionScripts(words).some(script => walkSnapshotNode(script, forkShellState(state)))) return true;
        if (!node.name) {
            for (const a of node.prefix || []) {
                if (a?.type === 'Assignment' && typeof a.name === 'string') setShellVariable(state, a.name, a.value?.value);
            }
            return false;
        }
        const resolved = resolveCommand(node);
        return resolved ? snapshotMutationIn(resolved, state) : false;
    }
    if (node.type === 'Subshell') return walkSnapshotNode(node.body, forkShellState(state));
    if (node.type === 'Pipeline' && (node.commands || []).length > 1) {
        return node.commands.some((c: any) => walkSnapshotNode(c, forkShellState(state)));
    }
    if (node.type === 'AndOr') {
        // An element runs after `&&` only when the one before succeeded, and
        // after `||` only when it failed (a failed command may have changed
        // nothing). The list can stop after any element.
        const elements: any[] = node.commands || [];
        const stops: SnapshotShellState[] = [];
        let input = forkShellState(state);
        for (let i = 0; i < elements.length; i++) {
            const before = forkShellState(input);
            if (walkSnapshotNode(elements[i], input)) return true;
            const failed = forkShellState(before);
            mergeShellState(failed, input);
            const op = node.operators?.[i];
            if (op === '&&') { stops.push(failed); continue; }
            if (op === '||') { stops.push(input); input = failed; continue; }
            stops.push(input, failed);
        }
        const out = freshShellState();
        for (const stop of stops) mergeShellState(out, stop);
        Object.assign(state, out);
        return false;
    }
    // Branches and loop bodies may or may not run: each runs on a copy of the
    // incoming state and every possible outcome is merged back.
    const alternatives = (branches: any[], includeSkip: boolean): boolean => {
        const out = includeSkip ? forkShellState(state) : freshShellState();
        for (const branch of branches) {
            const ran = forkShellState(state);
            if (walkSnapshotNode(branch, ran)) return true;
            mergeShellState(out, ran);
        }
        Object.assign(state, out);
        return false;
    };
    if (node.type === 'If') {
        if (walkSnapshotNode(node.clause, state)) return true;
        return alternatives([node.then, node.else], !node.else);
    }
    if (node.type === 'While') {
        if (walkSnapshotNode(node.clause, state)) return true;
        return alternatives([node.body], true);
    }
    if (node.type === 'For') return alternatives([node.body], true);
    if (node.type === 'Case') return alternatives((node.items || []).map((item: any) => item.body), true);
    if (node.type === 'Function') return walkSnapshotNode(node.body, forkShellState(state));
    for (const child of node.commands || []) if (walkSnapshotNode(child, state)) return true;
    for (const key of ['command', 'body']) {
        if (walkSnapshotNode(node[key], state)) return true;
    }
    return false;
}

export function evaluateSnapshotGitMutation(command: string): { action: 'allow' | 'block'; reason?: string } {
    if (!command) return { action: 'allow' };
    let blocked: boolean;
    try {
        blocked = walkSnapshotNode(parseShell(command), freshShellState());
    } catch {
        const state = freshShellState();
        blocked = fallbackExtract(command).some(cmd => snapshotMutationIn(cmd, state));
    }
    return blocked ? { action: 'block', reason: SNAPSHOT_GIT_MUTATION_BLOCK_REASON } : { action: 'allow' };
}

/** Verdict for the git-clone guard. Intentionally NARROWER than GateEvaluation
 *  (no `gate`) so every adapter can treat any non-`allow` as a block and never
 *  fail-open on an unexpected verdict. Pure — no I/O. */
export type GitCloneVerdict = { action: 'allow' | 'block'; reason?: string };

export function evaluateGitCloneDestination(command: string): GitCloneVerdict {
    if (!command || !GIT_CLONE_RE.test(command)) return { action: 'allow' };
    if (GIT_CLONE_MANAGED_DIR_RE.test(command)) {
        return { action: 'block', reason: GIT_CLONE_BLOCK_REASON };
    }
    return { action: 'allow' };
}

// ── Self-approval block (ADVISORY → BLOCK) ──
// Ported verbatim from nanoclaw-v2 claude.ts:462-484 (createSelfApprovalBlockHook).
// The bootstrap/plugins/workflow plugin's block-destructive hook gates
// destructive filesystem ops behind a file-based approval at
// `.claude-destructive-gate`. This evaluator prevents the agent from bypassing
// that gate by writing the approval file itself via Bash (`touch
// .claude-destructive-gate`, `echo … > .claude-destructive-gate`, etc.).
// Admin approval must come through the chat channel, not the agent's own
// filesystem writes.
//
// SINGLE SOURCE OF TRUTH for all provider adapters. Pure — no env/IO,
// deterministic on `command`. Verdict shape matches evaluateGitCloneDestination.
export const SELF_APPROVAL_RE = /\.claude-destructive-gate/;
export const SELF_APPROVAL_BLOCK_REASON =
    'Self-approval of destructive operation gates is not allowed. Approval must come from the user via the chat channel, not by writing .claude-destructive-gate yourself.';

export function evaluateSelfApproval(command: string): { action: 'allow' | 'block'; reason?: string } {
    if (!command) return { action: 'allow' };
    if (SELF_APPROVAL_RE.test(command)) {
        return { action: 'block', reason: SELF_APPROVAL_BLOCK_REASON };
    }
    return { action: 'allow' };
}

// ── Block ad-hoc Python snowflake.connector (ADVISORY → BLOCK) ──
// Ported verbatim from nanoclaw-v2 claude.ts:486-512 (createBlockSnowflakeConnectorHook).
// `snow` CLI is gated by destructive-operation controls (and scoped
// credential mounts); the Python connector bypasses those. Only blocks
// direct python execution — grep, echo, pip install, and existing
// scripts that happen to contain the string are unaffected.
//
// This is ADVISORY, not a security boundary. The regex is bypassable
// with base64-decoded source, heredocs, script files, or point-version
// binaries (python3.11). The real mitigation is only mounting Snowflake
// credentials when the snow CLI is actually invoked — a larger arch
// change. In the current model the guard nudges the agent toward `snow
// sql` for normal cases and raises the friction for unintended paths.
//
// Pure — no env/IO, deterministic on `command`.
export const SNOWFLAKE_CONNECTOR_EXEC_RE = /\bpython[23]?\b.*\bsnowflake[._]connector\b/i;
export const SNOWFLAKE_CONNECTOR_BLOCK_REASON =
    "Direct use of Python snowflake.connector is blocked. Use `snow sql` for ad-hoc queries. If `snow` isn't working, report the error rather than falling back to the Python connector.";

export function evaluateSnowflakeConnector(command: string): { action: 'allow' | 'block'; reason?: string } {
    if (!command) return { action: 'allow' };
    if (SNOWFLAKE_CONNECTOR_EXEC_RE.test(command)) {
        return { action: 'block', reason: SNOWFLAKE_CONNECTOR_BLOCK_REASON };
    }
    return { action: 'allow' };
}

// ── Constants ────────────────────────────────────────────────────────────────

const HOME = homedir();

export const SHELLS = new Set(['bash', 'sh', 'zsh', 'dash', 'ksh', 'fish']);

// Command wrappers that should be stripped to find the real command
export const WRAPPERS = new Set([
    'sudo', 'env', 'command', 'builtin', 'nohup', 'time', 'nice', 'timeout', 'gtimeout', 'stdbuf', 'setsid', 'onecli',
    // Package runners execute an arbitrary command too. Without them here,
    // `pnpm exec rm -rf <path>` resolved to name='pnpm' and every destructive
    // check passed — and since `Bash(pnpm exec *)` is commonly allow-listed,
    // that also meant no prompt. A ten-character prefix defeated both layers.
    'pnpm', 'yarn', 'npx', 'bunx',
    'exec',
]);

// Protected home subdirectories — rm targeting anything inside these is blocked
export const PROTECTED_HOME_DIRS = [
    // Personal data
    'Documents', 'Desktop', 'Downloads', 'Library',
    'Pictures', 'Music', 'Movies',
    // Security / credentials
    '.ssh', '.gnupg', '.aws', '.kube', '.docker', '.1password',
    // AI / agent tooling
    '.claude', '.codex', '.agents', '.cursor',
    // Dev environment (painful to rebuild)
    '.nvm', '.cargo', '.npm',
    // App config
    '.config',
];

// Ephemeral dirs where rm is unconditionally allowed
export const SAFE_PATH_PATTERNS = [
    /(?:^|\/)tmp(?:\/|$)/,
    /(?:^|\/)node_modules(?:\/|$)/,
    /(?:^|\/)\.next(?:\/|$)/,
    /(?:^|\/)dist(?:\/|$)/,
    /(?:^|\/)build(?:\/|$)/,
    /(?:^|\/)\.cache(?:\/|$)/,
    /(?:^|\/)out(?:\/|$)/,
    /(?:^|\/)coverage(?:\/|$)/,
    /(?:^|\/)\.turbo(?:\/|$)/,
    /(?:^|\/)__pycache__(?:\/|$)/,
    /(?:^|\/)\.pytest_cache(?:\/|$)/,
    /(?:^|\/)\.mypy_cache(?:\/|$)/,
    /(?:^|\/)storybook-static(?:\/|$)/,
];

// Destructive SQL patterns, anchored to statement-leading. Each pattern fires
// only after string literals, comments, and CTE preambles are stripped (see
// findDestructiveSqlStatement) — so substrings inside `'%DROP TABLE%'` and
// keyword-like identifiers in `"DROP TABLE archive"` do not match.
const DDL_DROP_TARGETS =
    '(?:TABLE|SCHEMA|DATABASE|VIEW|PROCEDURE|FUNCTION|OWNED|TRIGGER|INDEX|MATERIALIZED\\s+VIEW)';

export const DESTRUCTIVE_SQL_PATTERNS: Array<{ rx: RegExp; label: string }> = [
    { rx: new RegExp(`^DROP\\s+${DDL_DROP_TARGETS}\\b`, 'i'), label: 'DROP' },
    { rx: /^TRUNCATE\b/i, label: 'TRUNCATE' },
    { rx: /^DELETE\s+FROM\b/i, label: 'DELETE FROM' },
    // Replacing any object drops the one there: a database or schema with everything in it, a stage with its files, a
    // role or share with its grants.
    { rx: /^CREATE\s+OR\s+REPLACE\b/i, label: 'CREATE OR REPLACE' },
    { rx: /^INSERT\s+OVERWRITE\b/i, label: 'INSERT OVERWRITE' },
    { rx: /^MERGE\s+INTO\b/i, label: 'MERGE' },
    // After string-strip, a DROP keyword inside a string literal cannot reach
    // this check, so anywhere-in-statement matching is safe.
    { rx: /^ALTER\b[\s\S]*\bDROP\b/i, label: 'ALTER ... DROP' },
    { rx: /^ALTER\b[\s\S]*\bSWAP\s+WITH\b/i, label: 'ALTER ... SWAP WITH' },
    { rx: /^ALTER\b[\s\S]*\bRENAME\s+TO\b/i, label: 'ALTER ... RENAME TO' },
    { rx: /^GRANT\s+OWNERSHIP\b/i, label: 'GRANT OWNERSHIP' },
];

// Control-flow words that can open a statement inside a scripting block
// (Snowflake Scripting, PL/pgSQL, T-SQL). Stripped before matching, so the
// statement they lead into is checked like a top-level one.
const BLOCK_LEAD = /^(?:(?:BEGIN|ELSE|LOOP|DO|REPEAT)\b\s*|(?:EXCEPTION\s+)?(?:IF|ELSEIF|ELSIF|WHEN)\b[\s\S]*?\bTHEN\b\s*|(?:FOR|WHILE)\b[\s\S]*?\b(?:DO|LOOP)\b\s*)/i;
const BLOCK_LEAD_MAX_STRIPS = 16;

const UPDATE_LEADING = /^UPDATE\b/i;
const HAS_WHERE = /\bWHERE\b/i;

// Cheap superset prefilter — if none of these verbs appear anywhere in the
// SQL arg, no destructive pattern can match. Skips the full strip+scan
// pipeline on SELECT-only queries (the common case).
const SQL_PREFILTER = /\b(?:DROP|TRUNCATE|DELETE|MERGE|UPDATE|INSERT|CREATE|ALTER|EXECUTE|GRANT)\b/i;

// Hoisted to module scope — these regexes are matched per-segment / per-call
// inside the SQL scanner; defining them inline would recompile on every
// invocation.
const WITH_LEADING = /^WITH\b/i;
const WITH_PREFIX = /^WITH\s+(?:RECURSIVE\s+)?/i;
const CTE_NAME_AS = /^(?:"\s*"|"[^"]*"|`[^`]*`|[A-Za-z_][\w$]*)\s*(?:\([^)]*\))?\s+AS\s+/i;
const EXECUTE_IMMEDIATE = /(?:EXECUTE\s+IMMEDIATE|\bDO(?:\s+LANGUAGE\s+\w+)?)\s+/gi;
const DOLLAR_TAG = /^\$([A-Za-z0-9_]*)\$/;

const STATEMENT_PREVIEW_CHARS = 200;
const SQL_RECURSION_LIMIT = 3;

// MongoDB destructive methods
export const DESTRUCTIVE_MONGO = /(?:\bdropDatabase\b|\.drop\s*\(|\.deleteMany\s*\(|\.remove\s*\()/i;

// SQL CLI name → display label
export const SQL_CLIS: Record<string, string> = {
    psql: 'PostgreSQL', mysql: 'MySQL', duckdb: 'DuckDB',
    sqlite3: 'SQLite', sqlite: 'SQLite',
};

// ── SQL parsing helpers ──────────────────────────────────────────────────────

/**
 * Strip SQL string literals and comments out of `sql`, replacing their
 * contents with spaces of equal length. Length-preserving so the output
 * shares offsets with the input — the caller can split on `;` and trust the
 * boundaries to match the original source.
 *
 * Handles:
 *   - line comments (`-- ...`)
 *   - block comments (`/* ... *\/`, non-nested)
 *   - single-quoted strings with `''` escape
 *   - double-quoted identifiers (Postgres/Snowflake) with `""` escape
 *   - backtick identifiers (MySQL)
 *   - dollar-quoted strings (`$$...$$`, `$tag$...$tag$` — Postgres/Snowflake)
 *
 * Not a real SQL parser. Constructs that produce destructive effects from
 * inside a string literal — the most realistic being EXECUTE IMMEDIATE —
 * are handled separately by findExecuteImmediateLiterals + recursion in
 * findDestructiveSqlStatement.
 */
export function stripSqlLiteralsAndComments(sql: string): string {
    return sqlSkeleton(sql).skeleton;
}

/**
 * stripSqlLiteralsAndComments, plus where the first literal or comment that never closes starts (-1 when every one
 * closes). From there to the end the skeleton is blank, so no statement there was read.
 */
export function sqlSkeleton(sql: string): { skeleton: string; openAt: number } {
    const out: string[] = [];
    let openAt = -1;
    let i = 0;
    while (i < sql.length) {
        const c = sql[i];
        const c2 = sql.slice(i, i + 2);

        if (c2 === '--') {
            const nl = sql.indexOf('\n', i);
            const end = nl < 0 ? sql.length : nl;
            out.push(' '.repeat(end - i));
            i = end;
            continue;
        }
        if (c2 === '/*') {
            const close = sql.indexOf('*/', i + 2);
            if (close < 0) openAt = i;
            const end = close < 0 ? sql.length : close + 2;
            out.push(' '.repeat(end - i));
            i = end;
            continue;
        }
        if (c === "'" || c === '"' || c === '`') {
            const quote = c;
            const start = i;
            let closed = false;
            i += 1;
            while (i < sql.length) {
                if (sql[i] === quote && sql[i + 1] === quote) {
                    i += 2; // SQL doubled-quote escape
                    continue;
                }
                if (sql[i] === quote) {
                    i += 1;
                    closed = true;
                    break;
                }
                i += 1;
            }
            if (!closed) openAt = start;
            // Replace whole literal (quotes included) with spaces, length-preserving
            out.push(quote + ' '.repeat(Math.max(0, i - start - 2)) + quote);
            continue;
        }
        if (c === '$') {
            const m = sql.slice(i).match(DOLLAR_TAG);
            if (m) {
                const tag = m[0];
                const start = i + tag.length;
                const close = sql.indexOf(tag, start);
                if (close >= 0) {
                    const end = close + tag.length;
                    out.push(tag + ' '.repeat(close - start) + tag);
                    i = end;
                    continue;
                }
                // Unclosed dollar-quote — stop parsing as code from here, replace rest with spaces
                openAt = i;
                out.push(' '.repeat(sql.length - i));
                i = sql.length;
                continue;
            }
        }
        out.push(c);
        i += 1;
    }
    return { skeleton: out.join(''), openAt };
}

/**
 * Split a `;`-separated SQL segment (already string-stripped) into the list
 * of bodies that need to be destructiveness-checked. For non-CTE statements
 * this is `[{body: segment, isCTE: false}]`; for CTE-prefixed statements
 * (`WITH x AS (...) [, y AS (...)]* <body>`) it returns each CTE body plus
 * the trailing body, so a Postgres-style destructive CTE like `WITH d AS
 * (DELETE FROM foo RETURNING *) SELECT * FROM d` cannot hide its DELETE
 * behind a SELECT trailer.
 */
export function decomposeSqlSegment(skel: string): Array<{ body: string; isCTE: boolean }> {
    const trimmed = skel.trim();
    if (!WITH_LEADING.test(trimmed)) return [{ body: trimmed, isCTE: false }];

    const bodies: Array<{ body: string; isCTE: boolean }> = [];
    let s = trimmed.replace(WITH_PREFIX, '');

    while (s.length > 0) {
        const nameMatch = s.match(CTE_NAME_AS);
        if (!nameMatch) break;
        s = s.slice(nameMatch[0].length);

        if (s[0] !== '(') break;
        let depth = 1;
        let i = 1;
        while (i < s.length && depth > 0) {
            if (s[i] === '(') depth++;
            else if (s[i] === ')') depth--;
            if (depth > 0) i++;
        }
        if (depth !== 0) break; // unbalanced — bail rather than mis-classify
        bodies.push({ body: s.slice(1, i).trim(), isCTE: true });
        s = s.slice(i + 1).trimStart();

        if (s[0] === ',') {
            s = s.slice(1).trimStart();
            continue;
        }
        break;
    }

    if (s.length > 0) bodies.push({ body: s.trim(), isCTE: false });
    return bodies;
}

export function checkSqlBody(body: string, isCTE: boolean): DestructiveMatch | null {
    let trimmed = body.trim();
    for (let i = 0; i < BLOCK_LEAD_MAX_STRIPS && BLOCK_LEAD.test(trimmed); i++) {
        trimmed = trimmed.replace(BLOCK_LEAD, '').trim();
    }
    if (!trimmed) return null;
    const preview = trimmed.slice(0, STATEMENT_PREVIEW_CHARS);

    for (const { rx, label } of DESTRUCTIVE_SQL_PATTERNS) {
        if (rx.test(trimmed)) {
            return { pattern: isCTE ? `CTE-wrapped ${label}` : label, statement: preview };
        }
    }

    // A WHERE inside a subquery still counts as having WHERE — rare false-allow,
    // acceptable since the gate is meant to catch obvious accidents.
    if (UPDATE_LEADING.test(trimmed) && !HAS_WHERE.test(trimmed)) {
        return {
            pattern: isCTE ? 'CTE-wrapped UPDATE without WHERE' : 'UPDATE without WHERE',
            statement: preview,
        };
    }

    return null;
}

/**
 * Find every `EXECUTE IMMEDIATE '...'` literal and return its contents. The
 * keyword scan runs against `skeleton` (already stripped, offsets preserved)
 * so an EXECUTE IMMEDIATE appearing inside a string or comment doesn't
 * trigger recursion. The returned bodies come from `originalSql` so the
 * literal contents are real SQL the recursion can scan.
 */
export function findExecuteImmediateLiterals(originalSql: string, skeleton: string): string[] {
    const literals: string[] = [];
    EXECUTE_IMMEDIATE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = EXECUTE_IMMEDIATE.exec(skeleton)) !== null) {
        const litStart = m.index + m[0].length;
        if (litStart >= originalSql.length) continue;
        const c = originalSql[litStart];
        let body: string | null = null;

        if (c === "'" || c === '"' || c === '`') {
            let i = litStart + 1;
            while (i < originalSql.length) {
                if (originalSql[i] === c && originalSql[i + 1] === c) { i += 2; continue; }
                if (originalSql[i] === c) break;
                i++;
            }
            body = originalSql.slice(litStart + 1, i);
        } else if (c === '$') {
            const tagMatch = originalSql.slice(litStart).match(DOLLAR_TAG);
            if (tagMatch) {
                const tag = tagMatch[0];
                const tagStart = litStart + tag.length;
                const close = originalSql.indexOf(tag, tagStart);
                if (close >= 0) body = originalSql.slice(tagStart, close);
            }
        }

        if (body !== null) literals.push(body);
    }
    return literals;
}

/**
 * Scan `sql` for a destructive statement and return what tripped the gate,
 * or null. Coverage maps to DESTRUCTIVE_SQL_PATTERNS plus UPDATE-without-WHERE,
 * CTE-wrapped DML, and EXECUTE IMMEDIATE recursion.
 *
 * Known residual gaps (out of scope for syntactic checking):
 *   - destructive verbs inside CREATE PROCEDURE / FUNCTION bodies — creation
 *     is non-destructive; CALL is the dangerous moment, but we can't tell
 *     what a procedure does
 *   - dynamic SQL via PREPARE / EXECUTE bind vars
 *   - `UPDATE ... WHERE 1=1` — syntactically has WHERE; semantically rewrites
 *     everything
 */
export function findDestructiveSqlStatement(sql: string, depth: number = 0): DestructiveMatch | null {
    if (depth > SQL_RECURSION_LIMIT) return null;
    if (!SQL_PREFILTER.test(sql)) return null;

    const skeleton = stripSqlLiteralsAndComments(sql);
    for (const segment of skeleton.split(';')) {
        for (const { body, isCTE } of decomposeSqlSegment(segment)) {
            const match = checkSqlBody(body, isCTE);
            if (match) return match;
        }
    }

    for (const literal of findExecuteImmediateLiterals(sql, skeleton)) {
        const inner = findDestructiveSqlStatement(literal, depth + 1);
        if (inner) {
            return { pattern: `EXECUTE IMMEDIATE → ${inner.pattern}`, statement: inner.statement };
        }
    }

    return null;
}

const SQL_FILE_MAX_BYTES = 1_000_000;
const SQL_FILES_MAX = 16;
// Options whose value is a file of SQL the client runs.
const SQL_FILE_OPTIONS: Record<string, string[]> = {
    snow: ['-f', '--filename'], psql: ['-f', '--file'], duckdb: ['-f'],
};
// Options naming a file run before the client reads stdin, which it still reads after.
const SQL_PRELUDE_OPTIONS: Record<string, string[]> = { duckdb: ['-init'], sqlite3: ['-init'], sqlite: ['-init'] };
// Short options that take a value, from each client's getopt spec: in a cluster the first of them takes the rest.
const SQL_SHORT_VALUE_OPTIONS: Record<string, string> = { psql: 'cdfFhLopPRTUv', mysql: 'DehPSup', snow: 'cDfq' };

/** The value-taking short option a cluster such as `-Xc…` ends at (`-dprod` ends at `d`), or null. */
function clusterValueOption(client: string, word: string): string | null {
    const spec = SQL_SHORT_VALUE_OPTIONS[client];
    if (!spec || !/^-[A-Za-z]/.test(word)) return null;
    for (const ch of word.slice(1)) {
        if (spec.includes(ch)) return ch;
        if (!/[A-Za-z0-9?]/.test(ch)) return null;
    }
    return null;
}

// Options whose value is SQL. A client given none of them reads SQL from stdin.
const SQL_TEXT_OPTIONS: Record<string, string[]> = {
    snow: ['-q', '--query'], psql: ['-c', '--command'], mysql: ['-e', '--execute'], duckdb: ['-c', '-s'],
};
// Client commands inside SQL text that run another file: snow `!source`/`!load`,
// psql `\i`/`\ir`/`\include`, sqlite `.read`, mysql `source`.
const SQL_INCLUDE = /^\s*(!(?:source|load)|\\(?:ir|include_relative|i|include)|\.read|source)\s+('(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"|[^\s;]+)/gim;
// psql's \ir and \include_relative resolve a relative name against the including file's directory.
const SQL_INCLUDE_RELATIVE = new Set(['\\ir', '\\include_relative']);

/** Each file the SQL text includes; a relative \ir name is resolved against `includingFile`'s directory. */
function sqlIncludes(text: string, includingFile: string | null): string[] {
    const files: string[] = [];
    for (const m of text.matchAll(SQL_INCLUDE)) {
        const raw = m[2];
        const name = /^['"]/.test(raw) ? raw.slice(1, -1).replace(/\\(.)/g, '$1') : raw;
        files.push(includingFile && SQL_INCLUDE_RELATIVE.has(m[1]) && !name.startsWith('/') ? join(dirname(includingFile), name) : name);
    }
    return files;
}
const SNOW_TEMPLATE = /&\{\s*([\w.]+)\s*\}|<%\s*([\w.]+)\s*%>|&([A-Za-z_]\w*)/g;

export interface SqlInput {
    texts: string[];            // every SQL text the client could run, as far as the command line shows
    unreadable: string | null;  // a SQL file too large to check, past the include limit, or input past the trace budget
    argCounts?: Map<string, number>; // how many entries of `texts` arrived as the client's own arguments
}

/** The value `option` gives in `args[i]`: `-q X`, `--query=X`, or glued `-qX`. */
function optionValueAt(args: string[], i: number, option: string, attached = true): string | undefined {
    const a = args[i];
    if (a === option) return args[i + 1];
    if (!attached) return undefined;
    if (option.startsWith('--')) return a.startsWith(`${option}=`) ? a.slice(option.length + 1) : undefined;
    return a.startsWith(option) && a.length > option.length && !a.startsWith('--') ? a.slice(option.length) : undefined;
}

const SINGLE_DASH_CLIENTS = new Set(['duckdb', 'sqlite3', 'sqlite']);

// sqlite3 options that take a value, single- or double-dashed.
const SQLITE_VALUE_OPTIONS = new Set(['init', 'cmd', 'separator', 'newline', 'nullvalue', 'mmap', 'heap', 'maxsize', 'vfs', 'escape', 'nonce']);
const SQLITE_TWO_VALUE_OPTIONS = new Set(['lookaside', 'pagecache']);
const SQLITE_FLAGS = new Set(['append', 'ascii', 'bail', 'batch', 'box', 'column', 'csv', 'deserialize', 'echo', 'header', 'noheader', 'help', 'html', 'interactive', 'json', 'line', 'list', 'markdown', 'memtrace', 'nofollow', 'pcachetrace', 'quote', 'readonly', 'safe', 'stats', 'table', 'tabs', 'unsafe-testing', 'utf8', 'version', 'zip']);

/**
 * How many operands (FILENAME, SQL) a sqlite3 command line gives, past its options and their values; 0 when an
 * option is not one listed here, since its arity is unknown and stdin must then be assumed read.
 */
function sqlitePositionals(args: string[]): number {
    let n = 0;
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a === '--') return n + args.length - i - 1;
        const option = a.replace(/^--?/, '');
        if (!a.startsWith('-')) n++;
        else if (SQLITE_VALUE_OPTIONS.has(option)) i++;
        else if (SQLITE_TWO_VALUE_OPTIONS.has(option)) i += 2;
        else if (!SQLITE_FLAGS.has(option)) return 0;
    }
    return n;
}

/** An argument, plus the value glued to it when it is an option (`-cSQL`, `--command=SQL`), where SQL would read `--…` as a comment. */
function withOptionValue(a: string): string[] {
    if (/^-[A-Za-z]./.test(a) && !a.startsWith('--')) {
        // The value may follow other flag letters clustered before its option (`psql -XAtqcSQL`): the first letter that
        // takes SQL (psql -c, mysql -e, snow -q) consumes the rest of the word.
        const out = [a, a.slice(2)];
        const run = a.slice(1).match(/^[A-Za-z]+/)![0];
        for (const letter of 'ceq') {
            const at = run.indexOf(letter);
            if (at > 0) out.push(a.slice(at + 2));
        }
        return out;
    }
    if (a.startsWith('--') && a.includes('=')) return [a, a.slice(a.indexOf('=') + 1)];
    return [a];
}

/**
 * Every SQL text a SQL client step could run: its arguments (with a glued
 * `-qSQL` or `--query=SQL` value unglued), heredoc and here-string input,
 * `-f` and `<` files, files the SQL itself includes, and snow `-D` template
 * values rendered in. When the SQL arrives from a file or stdin, the text the
 * rest of the command writes (heredocs, echo/printf/tee, `cat`ed files) is
 * included too, since that is where such a file usually comes from.
 */
export function sqlInputOf(cmd: ResolvedCommand): SqlInput {
    const client = cmd.name === 'snow' ? 'snow' : cmd.name;
    const args = client === 'snow' ? cmd.args.slice(1) : cmd.args;
    const fileOptions = SQL_FILE_OPTIONS[client] ?? [];
    const preludeOptions = SQL_PRELUDE_OPTIONS[client] ?? [];
    const preludes: string[] = [];
    const textOptions = SQL_TEXT_OPTIONS[client] ?? [];
    const texts: string[] = [...(cmd.stdinTexts ?? [])];
    // A file option's value names a file (read below), not SQL.
    const fileValue = (i: number) => fileOptions.includes(cmd.args[i - 1] ?? '') || fileOptions.some(o => cmd.args[i].startsWith(o) && cmd.args[i] !== o);
    let expanded: string[] | null = [];
    const argCounts = new Map<string, number>();
    const asArgument = (t: string) => argCounts.set(t, (argCounts.get(t) ?? 0) + 1);
    for (const view of cmd.expandAs === undefined ? [cmd] : cmd.expandAs ?? []) {
        const stdin = expandWords(view.stdinExpanded ?? [], view);
        const words = expandWords(argumentWords(view).filter((_, i) => !fileValue(i)), view);
        if (stdin === null || words === null) {
            expanded = null;
            break;
        }
        expanded.push(...stdin, ...words);
        for (const w of words) for (const t of withOptionValue(w)) asArgument(t);
    }
    if (cmd.expandAs === null) expanded = null;
    let traceOver = expanded === null;
    for (const e of expanded ?? []) texts.push(...withOptionValue(e));
    const files: string[] = [...(cmd.stdinFiles ?? [])];
    const vars = new Map<string, string>();
    let sqlInArgs = false;
    // Expanded argument text is not stdin: only a heredoc, here-string or `<` file is.
    let readsStdin = Boolean(cmd.stdinTexts?.length) || files.length > 0;

    // duckdb and sqlite3 spell long options with one dash (`-csv`) and never glue a value on, so only an exact word counts.
    const attaches = !SINGLE_DASH_CLIENTS.has(client);
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        for (const t of withOptionValue(a)) {
            texts.push(t);
            asArgument(t);
        }
        for (const o of fileOptions) {
            const v = optionValueAt(args, i, o, attaches);
            if (v !== undefined) files.push(v);
        }
        for (const o of preludeOptions) {
            const v = optionValueAt(args, i, o, attaches);
            if (v !== undefined) preludes.push(v);
        }
        for (const o of textOptions) {
            if (optionValueAt(args, i, o, attaches) !== undefined) sqlInArgs = true;
            // `-XcSQL`: a single-letter text option clustered after flags still takes the SQL.
            if (/^-[a-z]$/i.test(o) && clusterValueOption(client, a) === o[1]) sqlInArgs = true;
        }
        if (client === 'snow') {
            for (const o of ['-D', '--variable']) {
                const v = optionValueAt(args, i, o);
                const m = v?.match(/^([\w.]+)=([\s\S]*)$/);
                if (m) vars.set(m[1], m[2]);
            }
            if (a === '--stdin' || a === '-i') readsStdin = true;
        }
    }
    const render = (t: string) => (vars.size ? t.replace(SNOW_TEMPLATE, (m, a, b, c) => vars.get(a ?? b ?? c) ?? m) : t);
    if (vars.size) texts.push(...texts.map(render), ...vars.values());
    if (client === 'psql' || client === 'mysql' || client === 'snow' || (client === 'duckdb' && sqlInArgs)) {
        if (!sqlInArgs && files.length === 0) readsStdin = true;
    } else if (!((client === 'sqlite3' || client === 'sqlite') && sqlitePositionals(args) >= 2)) {
        // sqlite3 [OPTIONS] [FILENAME [SQL]]: given SQL as an operand it runs that and never reads stdin.
        readsStdin = true;
    }
    if (files.includes('-')) readsStdin = true;
    if (readsStdin && !files.some(f => f !== '-') && !(cmd.stdinTexts?.length)) {
        const piped = flattenInput(cmd.pipedInput ?? (cmd.pos === undefined ? undefined : cmd.script?.pipedInto.get(cmd.pos)), cmd.script);
        if (piped.over || !spendTrace(cmd.script, textSize(piped.texts) + piped.catFiles.length)) traceOver = true;
        else {
            texts.push(...piped.texts);
            files.push(...piped.catFiles);
        }
    }

    // Read each file, plus any text the command writes to it first; follow
    // includes found in what is read, up to a fixed number of files.
    let unreadable: string | null = traceOver ? 'its piped input' : null;
    const pending = [...preludes, ...files];
    for (const t of texts) pending.push(...sqlIncludes(t, null));
    const seen = new Set<string>();
    while (pending.length && seen.size < SQL_FILES_MAX) {
        const f = pending.shift()!;
        if (seen.has(f)) continue;
        seen.add(f);
        if (f === '/dev/null') continue;
        // A file something may write before it is read is still read as it stands: what it holds now can block.
        if (writesOwnOutput(cmd) || texts.some(t => SQL_CLIENT_FILE_WRITE.test(t))) {
            unreadable ??= `${f}, which the client may write itself`;
        }
        if (sqlPathCandidates(f, cmd) === null) unreadable ??= `${f}, a path the command line doesn't prove`;
        const writes = writesTo(f, cmd);
        if (writes === null) {
            unreadable ??= f;
            continue;
        }
        for (const written of writes.map(w => flattenInput(w, cmd.script))) {
            if (written.over || !spendTrace(cmd.script, textSize(written.texts) + written.catFiles.length)) {
                unreadable ??= f;
                break;
            }
            for (const t of written.texts) {
                // Templates render before snow follows an include, so a rendered `!source` names a file too.
                const r = render(t);
                texts.push(...(r === t ? [t] : [t, r]));
                pending.push(...sqlIncludes(r, null));
            }
            pending.push(...written.catFiles);
        }
        for (const { path, content } of readSqlFiles(f, cmd)) {
            if (content === 'too-large') {
                unreadable ??= f;
                continue;
            }
            if (!spendTrace(cmd.script, content.length)) {
                unreadable ??= f;
                continue;
            }
            const rendered = render(content);
            if (rendered !== content && !spendTrace(cmd.script, rendered.length)) {
                unreadable ??= f;
                continue;
            }
            texts.push(...(rendered === content ? [content] : [content, rendered]));
            pending.push(...sqlIncludes(rendered, path));
        }
    }
    const movedDir = cmd.name === 'psql' ? texts.some(t => PSQL_CD.test(t))
        : (client === 'sqlite3' || client === 'sqlite' || client === 'duckdb') ? texts.some(t => SQLITE_CD.test(t))
        : false;
    if (movedDir && texts.some(t => sqlIncludes(t, null).some(f => !f.startsWith('/')))) {
        // The client ran `\cd`/`.cd`, so a relative include resolves from a directory the guard can't know.
        unreadable ??= 'a relative include after the client changed its own directory';
    }
    if (pending.length) unreadable ??= pending[0];
    return { texts, unreadable, argCounts };
}

const sqlInputs = new WeakMap<ResolvedCommand, SqlInput>();

/** sqlInputOf, once per step: a second read would spend the line's trace budget again. */
function sqlInputFor(cmd: ResolvedCommand): SqlInput {
    let input = sqlInputs.get(cmd);
    if (!input) sqlInputs.set(cmd, (input = sqlInputOf(cmd)));
    return input;
}

/**
 * A program a SQL client's input makes it run.
 * - mode 'check': `shells` holds the exact command line(s) it hands to a shell; each is judged as a command typed
 *   at the top level, from `server` false, so a tier-1 command there blocks and a gated one gates.
 * - mode 'block': what it runs is not fully on the line (a client :variable, piped query output, an editor, a loaded
 *   extension, a server-side program, a quoted form the client rebuilds itself). The guard can't read it, so the step
 *   blocks and approval can't clear it — the same rule as a shell taking its command from a variable.
 * `server`: the program runs on the database server, on its own host.
 */
interface ClientProgram { via: string; mode: 'check' | 'block'; shells: string[]; server?: boolean }

const checkProg = (via: string, shell: string): ClientProgram => ({ via, mode: 'check', shells: [shell] });
const blockProg = (via: string, server = false): ClientProgram => ({ via, mode: 'block', shells: [], server });

/** A SQL client step's programs, and whether its input moves the client's own directory before running them. */
interface ClientRuns { programs: ClientProgram[]; movesDir: boolean; relativeInclude: boolean }

// psql `\cd` and sqlite `.cd` move the client's own directory, which every later shell escape starts from.
const PSQL_CD = /\\cd(?=[\s\\]|$)/;
const SQLITE_CD = /^[ \t]*\.cd\b/m;

// A psql backslash command's name runs to whitespace or the next backslash (psqlscanslash.l). Plain file writes
// (`\o FILE`, `\copy … TO 'FILE'`) are not here: the guard does not gate a shell `>` either.
const PSQL_PROGRAM_COMMAND = /\\(!|o|out|g|gx|w|write|setenv|e|edit|ef|ev)(?=[\s\\]|$)/g;
const PSQL_PIPING_COMMANDS = new Set(['o', 'out', 'g', 'gx', 'w', 'write']);
const PSQL_BACKSLASH_COMMAND = /\\[^\s\\]/;
// psql substitutes a :variable, :'variable' or :"variable" in a backslash command's arguments and in backquotes.
const PSQL_VARIABLE = /:['"]?[\w\u0080-\uffff]/;
// mysql dispatches on the one character after a backslash, and its shell escape runs what follows the first space.
const MYSQL_SHELL_ESCAPE = /\\![^\n]*/g;
// mysql reads a long-form client command (`system`) at a statement start, so after a newline or `;`; `\P`/`\e` anywhere.
const MYSQL_SYSTEM = /(?:^|;)[ \t]*system\b[ \t]*([^\n]*)/gim;
const MYSQL_PROGRAM_COMMAND = /\\[Pe](?=\s|$)|(?:^|;)[ \t]*(?:pager|edit)\b/im;
// sqlite3 (and the duckdb shell built from it) takes a dot-command's name by prefix: `.sh` is `.shell`. Its
// `.output`/`.once` strip quotes and skip options before a `|` (shell.c.in, dotCmdOutput), so any `|` is a pipe.
const SQLITE_DOT_COMMAND = /^[ \t]*\.([A-Za-z_]+)([^\n]*)$/gm;
const SQLITE_EDIT_FUNCTION = /\bedit\s*\(/i;
const SQL_GAP = String.raw`(?:\s|/\*[\s\S]*?\*/|--[^\n]*\n)+`;
// COPY … PROGRAM followed by the program as a plain single-quoted literal; group 1 absent for any other spelling
// (an E'…' or dollar-quoted string, a concatenation, a bare word), which the guard then can't read.
const COPY_PROGRAM = new RegExp(String.raw`\b(?:TO|FROM)${SQL_GAP}PROGRAM\b(${SQL_GAP}'((?:[^']|'')*)')?`, 'gi');

const isPrefixOf = (name: string, full: string) => name.length > 0 && full.startsWith(name);

function sqliteDotPrograms(text: string, argument: boolean): ClientProgram[] {
    const out: ClientProgram[] = [];
    // An argument that is a dot-command is one command over the whole argument: sqlite splits its words on any
    // whitespace, newlines included (shell.c.in, parseDotCmdArgs). Input it reads line by line.
    const whole = argument ? /^\s*\.([A-Za-z_]+)([\s\S]*)$/.exec(text) : null;
    for (const m of whole ? [whole] : text.matchAll(SQLITE_DOT_COMMAND)) {
        const [name, rest] = [m[1], m[2].replace(/\s+/g, ' ')];
        const via = `.${name}`;
        if (name.startsWith('s') && (isPrefixOf(name, 'shell') || isPrefixOf(name, 'system'))) {
            // sqlite joins the dot-command's own tokens into the shell string, resolving quotes and backslashes itself
            // (shell.c.in, parseDotCmdArgs); only an unquoted argument reaches the shell as written.
            out.push(/['"\\]/.test(rest) || !rest.trim() ? blockProg(via) : checkProg(via, rest.trim()));
        } else if (((isPrefixOf(name, 'output') || isPrefixOf(name, 'once')) && rest.includes('|'))
            || name === 'excel' || name === 'www' || isPrefixOf(name, 'load')
            || ((isPrefixOf(name, 'import') || (name.length >= 3 && isPrefixOf(name, 'read'))) && rest.includes('|'))) {
            out.push(blockProg(via));
        }
    }
    if (SQLITE_EDIT_FUNCTION.test(text)) out.push(blockProg('edit()'));
    return out;
}

function psqlPrograms(text: string, argument: boolean): ClientProgram[] {
    const out: ClientProgram[] = [];
    // A -c value that doesn't start with a backslash goes to the server unread (startup.c, ACT_SINGLE_QUERY).
    if (argument && !text.startsWith('\\')) return out;
    // psql runs a -c value that starts with a backslash as one backslash command reading the whole value
    // (startup.c, ACT_SINGLE_SLASH); files and stdin it reads line by line.
    for (const unit of psqlSlashUnits(text, argument)) {
        for (const m of unit.matchAll(PSQL_PROGRAM_COMMAND)) {
            const name = m[1];
            const rest = unit.slice((m.index ?? 0) + m[0].length);
            if (name === '!') out.push(rest.trim() ? checkProg('\\!', rest.trim()) : blockProg('\\!'));
            else if (!PSQL_PIPING_COMMANDS.has(name)) out.push(blockProg(`\\${name}`));
            else if (rest.includes('|') || PSQL_VARIABLE.test(rest)) out.push(blockProg(`\\${name} |`));
        }
        // A backslash command's arguments run what backquotes enclose (psqlscanslash.l, xslashbackquote).
        const slash = unit.search(PSQL_BACKSLASH_COMMAND);
        if (slash < 0) continue;
        const spans = unit.slice(slash).split('`');
        // psql substitutes :variables inside backquotes, so a span naming one runs a value the line doesn't show.
        for (let i = 1; i < spans.length; i += 2) {
            out.push(i === spans.length - 1 || PSQL_VARIABLE.test(spans[i]) ? blockProg('backquote') : checkProg('backquote', spans[i]));
        }
    }
    return out;
}

function mysqlPrograms(text: string, args: string[]): ClientProgram[] {
    const out: ClientProgram[] = [];
    for (const m of text.matchAll(MYSQL_SHELL_ESCAPE)) {
        const space = m[0].search(/[ \t]/);
        const shell = space < 0 ? '' : m[0].slice(space).trim();
        out.push(shell ? checkProg('\\!', shell) : blockProg('\\!'));
    }
    for (const m of text.matchAll(MYSQL_SYSTEM)) out.push(m[1].trim() ? checkProg('system', m[1].trim()) : blockProg('system'));
    if (MYSQL_PROGRAM_COMMAND.test(text) || args.some(a => /^--pager(?:=|$)/.test(a))) out.push(blockProg('pager or editor'));
    return out;
}

// A bare :name psql substitutes and lexes again (psqlscan.l, variable_char); `::` is a cast, not a variable.
const PSQL_BARE_VAR = /(?<!:):([A-Za-z0-9_\u0080-\uffff]+)/g;

/**
 * The units psql reads backslash commands from: a -c value that starts with a backslash is one command over the whole
 * value (startup.c, ACT_SINGLE_SLASH), another -c value goes to the server unread, and files and stdin go line by line.
 * Lines are scanned whole, literals and comments included: a guard that mis-lexes psql's quoting would hide a real
 * command, so a backslash command spelled inside a SQL string blocks as well.
 */
function psqlSlashUnits(text: string, argument: boolean): string[] {
    return argument ? (text.startsWith('\\') ? [text] : []) : text.split('\n');
}

// Variables psql fills from the server or the connection, whose text the line doesn't show.
const PSQL_SERVER_VARIABLES = new Set(['LAST_ERROR_MESSAGE', 'LAST_ERROR_SQLSTATE', 'SQLSTATE', 'SERVER_VERSION_NAME', 'DBNAME', 'USER', 'HOST', 'PORT', 'ENCODING']);
const PSQL_VALUE_REF = /:['"]?([A-Za-z0-9_\u0080-\uffff]+)/g;
// psql's short options that take no value (startup.c getopt string) may precede -v in one cluster.
const PSQL_SET_CLUSTER = /^-[aAbeEHlnqsSwWxXz?01]*v([\s\S]*)$/;

/** Every `name=value` psql's arguments set: -v, --set, --variable and their unambiguous long prefixes. */
function psqlArgAssignments(args: string[]): string[] {
    const out: string[] = [];
    args.forEach((a, i) => {
        const long = /^--([a-z-]+)(=([\s\S]*))?$/.exec(a);
        if (long) {
            const name = long[1];
            if (name.length >= 2 && ('set'.startsWith(name) || 'variable'.startsWith(name))) out.push(long[2] ? long[3] : args[i + 1] ?? '');
            return;
        }
        const short = PSQL_SET_CLUSTER.exec(a);
        if (short) out.push(short[1] || (args[i + 1] ?? ''));
    });
    return out;
}

/**
 * Whether psql input could run a backslash command through a variable: a bare :name whose value can carry a
 * backslash, or whose value the line doesn't show (\gset, \getenv, \prompt, backquotes, server text), directly or
 * through another variable it names. A plain -c value goes to the server unsubstituted, so it doesn't count; file and
 * stdin text is scanned whole, so a :name inside a literal or a backslash command's arguments counts too.
 */
function psqlVariableProgram(input: SqlInput, args: string[]): boolean {
    const refs = new Set([...input.texts].filter(t => readsAsInput(input, t)).flatMap(t => [...t.matchAll(PSQL_BARE_VAR)].map(m => m[1])));
    if (!refs.size) return false;
    const values = new Map<string, string[]>();
    const unknown = new Set<string>(PSQL_SERVER_VARIABLES);
    const prefixes: string[] = [];
    const define = (name: string, value: string) => values.set(name, [...(values.get(name) ?? []), value]);
    for (const value of psqlArgAssignments(args)) {
        const eq = value.indexOf('=');
        if (eq > 0) define(value.slice(0, eq), value.slice(eq + 1));
    }
    for (const unit of input.texts.flatMap(t => readingsOf(input, t).flatMap(argument => psqlSlashUnits(t, argument)))) {
        for (const m of unit.matchAll(/\\set[ \t]+(['"]?)([^\s'"\\]+)\1([^\n]*)/g)) define(m[2], m[3]);
        // psql substitutes variables and runs backquotes in the prefix (psqlscanslash.l), so only a plain word is known.
        for (const m of unit.matchAll(/\\gset(?:[ \t]+([^\s\\]+))?/g)) prefixes.push(/^(['"]?)([A-Za-z0-9_\u0080-\uffff]*)\1$/.exec(m[1] ?? '')?.[2] ?? '');
        for (const m of unit.matchAll(/\\getenv[ \t]+(['"]?)([^\s'"\\]+)/g)) unknown.add(m[2]);
        for (const m of unit.matchAll(/\\prompt\b([^\n]*)/g)) for (const w of m[1].match(/[^\s'"\\]+/g) ?? []) unknown.add(w);
    }
    const carries = new Set<string>();
    const carriesBackslash = (name: string) => unknown.has(name) || carries.has(name) || prefixes.some(p => name.startsWith(p));
    for (let grew = true; grew;) {
        grew = false;
        for (const [name, vs] of values) {
            if (carries.has(name)) continue;
            if (vs.some(v => /[\\`]/.test(v) || [...v.matchAll(PSQL_VALUE_REF)].some(r => carriesBackslash(r[1])))) {
                carries.add(name);
                grew = true;
            }
        }
    }
    return [...refs].some(carriesBackslash);
}

/** How the client reads `text`: as its own argument, as file or stdin input, or both when it arrived both ways. */
function readingsOf(input: SqlInput, text: string): boolean[] {
    const asArgument = input.argCounts?.get(text) ?? 0;
    if (asArgument === 0) return [false];
    return input.texts.filter(t => t === text).length > asArgument ? [true, false] : [true];
}

const readsAsInput = (input: SqlInput, text: string) => readingsOf(input, text).includes(false);

const clientRuns = new WeakMap<ResolvedCommand, ClientRuns>();

/** Every program a SQL client step runs from what it reads: shell escapes, pipes, editors and COPY … PROGRAM. */
function clientRunsOf(cmd: ResolvedCommand): ClientRuns {
    const cached = clientRuns.get(cmd);
    if (cached) return cached;
    const runs: ClientRuns = { programs: [], movesDir: false, relativeInclude: false };
    if (SQL_CLIS[cmd.name]) {
        const input = sqlInputFor(cmd);
        if (cmd.name === 'psql' && psqlVariableProgram(input, cmd.args)) {
            runs.programs.push(blockProg(':variable'));
        }
        for (const text of new Set(input.texts)) {
            for (const argument of readingsOf(input, text)) {
                if (cmd.name === 'psql') runs.programs.push(...psqlPrograms(text, argument));
                else if (cmd.name === 'mysql') runs.programs.push(...mysqlPrograms(text, cmd.args));
                else runs.programs.push(...sqliteDotPrograms(text, argument));
            }
            if ((cmd.name === 'psql' && PSQL_CD.test(text)) || (cmd.name !== 'psql' && cmd.name !== 'mysql' && SQLITE_CD.test(text))) runs.movesDir = true;
            if (/\bCOPY\b/i.test(text)) {
                for (const m of text.matchAll(COPY_PROGRAM)) {
                    // psql's \copy runs its program on this host; plain COPY runs it on the server.
                    const lineStart = text.lastIndexOf('\n', m.index ?? 0) + 1;
                    const client = copyIsClientSide(text.slice(lineStart, m.index));
                    const via = client ? '\\copy … PROGRAM' : 'COPY … PROGRAM';
                    // A server-side program runs on another host; a non-plain literal (E'…', dollar-quoted) is a form
                    // the guard can't read. Either way it can't be checked, so it blocks.
                    if (!client || m[1] === undefined) runs.programs.push(blockProg(via, !client));
                    else runs.programs.push(checkProg(via, m[2].replace(/''/g, "'")));
                }
            }
        }
    }
    if (SQL_CLIS[cmd.name]) runs.relativeInclude = sqlInputFor(cmd).texts.some(t => sqlIncludes(t, null).some(f => !f.startsWith('/')));
    clientRuns.set(cmd, runs);
    return runs;
}

/**
 * Whether a `TO/FROM PROGRAM` belongs to psql's `\copy`, which runs it on this host: its line starts with `\copy`
 * and names COPY nowhere else before it. Any other shape is read as a server-side COPY, which blocks.
 */
function copyIsClientSide(before: string): boolean {
    return /^\s*\\copy\b/i.test(before) && (before.match(/copy/gi)?.length ?? 0) === 1;
}

const CLIENT_SHELL_DEPTH_MAX = 4;
let clientShellDepth = 0;
// One top-level evaluation judges the same nested line many times (each tier visits each step); this keeps the cost
// linear in the distinct lines rather than exponential in the nesting depth.
let clientShellVerdicts: Map<string, GateEvaluation> | null = null;

/**
 * The verdict for a shell command line a SQL client runs from `dir`: exactly the verdict that command would get typed
 * at the top level, so it carries every tier the top-level pass does (hard blocks, the conflict-staging block, rm,
 * and the gated tier) with no parallel copy of them here. Too-deep nesting can't be read, so it blocks.
 */
function clientShellVerdict(text: string, dir: string | undefined): GateEvaluation {
    if (clientShellDepth >= CLIENT_SHELL_DEPTH_MAX) {
        return { action: 'block', reason: 'It nests SQL clients running shell commands too deeply for the guard to read. Run the command directly.' };
    }
    const key = `${clientShellDepth}\0${dir ?? ''}\0${text}`;
    const cached = clientShellVerdicts?.get(key);
    if (cached) return cached;
    clientShellDepth++;
    try {
        const at = dir === undefined ? {} : { cwd: dir };
        // The gated tier returns before the rm tier, and the caller's approval replay can't reach this nested line,
        // so read the block tiers on their own first: a later blocked rm must not hide behind an earlier gate.
        const blocked = evaluateBashCommand(text, { ...at, skipGate: true });
        const verdict = blocked.action === 'block' ? blocked : evaluateBashCommand(text, at);
        clientShellVerdicts?.set(key, verdict);
        return verdict;
    } finally {
        clientShellDepth--;
    }
}

/**
 * Every directory a SQL client's shell escape may start from, or null when the line doesn't prove it (the escape then
 * blocks). A server-side program, or a client that moved its own directory with `\cd`/`.cd`, has no knowable
 * directory and is handled before this.
 */
function shellDirectories(cmd: ResolvedCommand): string[] | null {
    // A step find, xargs or git builds has no place on the parsed line, and `-execdir`/`submodule foreach` run it
    // elsewhere again; a step inside $(…) may follow a cd in the same substitution, which the line's cds don't place.
    if (!cmd.script || cmd.chdir === EACH_MATCH_DIR || cmd.chdir === EACH_SUBMODULE_DIR) return null;
    if (cmd.pos === undefined && cmd.script.cds.some(step => step.pos < 0)) return null;
    return sqlPathCandidates('.', cmd);
}

/**
 * The strongest verdict a SQL client step earns for the programs it runs: a block reason (which survives the approval
 * replay, since it is returned from the hard-block tier), or else a gate reason, or null. One evaluator judges each
 * readable shell command; an unreadable program blocks.
 */
// A nested program's gate can't say which of a client's programs needs it, so it takes the production gate.
const CLIENT_PROGRAM_GATE = 'runs a client program that needs approval';

function clientProgramVerdict(cmd: ResolvedCommand): { block?: string; gate?: string } {
    let gate: string | undefined;
    const runs = clientRunsOf(cmd);
    if (runs.movesDir && runs.relativeInclude) {
        return { block: `${cmd.name} reads a file by a relative path after the client changed its own directory (\cd/.cd), so the guard can't tell what that file runs. Run the command from a shell instead.` };
    }
    for (const program of runs.programs) {
        if (program.mode === 'block') {
            if (program.server) return { block: `${cmd.name}: ${program.via} runs a shell command on the database server, which the guard can't read. Run it from a shell instead.` };
            return { block: `${cmd.name}: ${program.via} runs a program the guard can't read (its command comes from a variable, piped input, an editor, or a form the client rebuilds). Run the command from a shell instead.` };
        }
        // A client that moved its own directory leaves the escape's directory unknowable, so a relative path in it
        // can't be located: the program is unreadable and blocks.
        if (runs.movesDir) return { block: `${cmd.name} ${program.via} runs after the client changed its own directory (\cd/.cd), so the guard can't tell where it runs. Run the command from a shell instead.` };
        const dirs = shellDirectories(cmd);
        if (dirs === null) return { block: `${cmd.name} ${program.via} runs after a directory change the guard can't resolve, so it can't tell where the command runs. Run the command from a shell instead.` };
        for (const shell of program.shells) {
            for (const dir of dirs) {
                const v = clientShellVerdict(shell, dir);
                if (v.action === 'block') return { block: `${cmd.name} ${program.via} runs a blocked command. ${v.reason}` };
                if (v.action === 'gate') gate ??= `${cmd.name} ${program.via} ${CLIENT_PROGRAM_GATE}. ${v.reason}`;
            }
        }
    }
    return gate === undefined ? {} : { gate };
}

/** Why a SQL client step is blocked for a program it runs that the guard can't read, or that is blocked on its own. */
function clientProgramBlock(cmd: ResolvedCommand): string | null {
    return clientProgramVerdict(cmd).block ?? null;
}

/** Why a SQL client step needs approval for a program it runs, or null. */
function clientProgramGate(cmd: ResolvedCommand): string | null {
    const v = clientProgramVerdict(cmd);
    return v.block ?? v.gate ?? null;
}

const SQL_PATH_CANDIDATES_MAX = 8;
// Past this many directory changes or file writes before a reader, a path is treated as unprovable: matching every
// write against every cd is quadratic, and no real command comes near it.
const SQL_PATH_STEPS_MAX = 64;
const PIPE_NESTING_MAX = 64;

/**
 * The text of every file a SQL client step could open for `file`: one per
 * directory it could run in. Missing files and non-regular files are skipped
 * (a missing one is usually written earlier in the same command, whose text
 * sqlInputOf scans), and so is a path the command line does not prove.
 */
function readSqlFiles(file: string, cmd: ResolvedCommand): Array<{ path: string; content: string | 'too-large' }> {
    if (!file || file === '-') return [];
    const out: Array<{ path: string; content: string | 'too-large' }> = [];
    for (const path of sqlPathCandidates(file, cmd) ?? []) {
        try {
            const st = statSync(path);
            if (!st.isFile()) continue;
            out.push({ path, content: st.size > SQL_FILE_MAX_BYTES ? 'too-large' : readFileSync(path, 'utf-8') });
        } catch {
            continue;
        }
    }
    return out;
}

/**
 * Every absolute path `file` can name when the step runs, or null when the
 * command line does not prove it (a variable without a provable value, a glob,
 * or a cd whose target or effect cannot be known). A top-level cd narrows the
 * directory only when the step follows it in an unbroken && chain, where its
 * success is implied; otherwise the step may run in either directory.
 */
function provableWord(text: string, cmd: ResolvedCommand, pos: number): string | null {
    if (!/[$`]/.test(text)) return /[*?[{]/.test(text) || text.startsWith('~') ? null : text;
    const script = cmd.script;
    if (!script || pos < 0) return null;
    const key = `${pos}\0${text}`;
    script.words ??= new Map();
    if (script.words.has(key)) return script.words.get(key)!;
    script.wordBudget ??= SQL_WORD_BUDGET;
    let value: string | null = null;
    if (script.wordBudget > 0) {
        script.wordBudget--;
        script.view ??= viewShell(script.command);
        const r = evalWord(text, script.view, pos);
        value = r.unresolved.length || /[$`*?[{]/.test(r.value) ? null : r.value;
    }
    script.words.set(key, value);
    return value;
}

/**
 * What the command line writes to the file `reader` names as `file`: a write
 * spelled the same way, or one whose possible absolute paths meet the
 * reader's (each resolved from its own command's directory and variables).
 */
/** Null when more writes to the file precede the reader than can be checked (appends all count). */
function writesTo(file: string, reader: ResolvedCommand): PipedInput[] | null {
    if (!file || file === '-') return [];
    let readerPaths: Set<string> | undefined;
    const out: PipedInput[] = [];
    const script = reader.script;
    const all = script?.writes ?? [];
    const before = (w: FileWrite) => w.writer.pos === undefined || reader.pos === undefined || w.writer.pos < reader.pos;
    if (all.length > SQL_PATH_STEPS_MAX && script) {
        if (!script.writesByTarget) {
            script.writesByTarget = new Map();
            for (const w of all) {
                const key = samePath(w.target);
                const list = script.writesByTarget.get(key);
                if (list) list.push(w);
                else script.writesByTarget.set(key, [w]);
            }
        }
        const prior = (script.writesByTarget.get(samePath(file)) ?? []).filter(before);
        return prior.length > SQL_PATH_STEPS_MAX ? null : prior.map(w => w.input);
    }
    for (const w of all) {
        if (!before(w)) continue;
        if (samePath(w.target) === samePath(file)) {
            out.push(w.input);
            continue;
        }
        readerPaths ??= new Set(sqlPathCandidates(file, reader) ?? []);
        if ((sqlPathCandidates(w.target, w.writer) ?? []).some(p => readerPaths!.has(p))) out.push(w.input);
    }
    return out;
}

function sqlPathCandidates(file: string, cmd: ResolvedCommand): string[] | null {
    const script = cmd.script;
    if (!script || cmd.pos === undefined) return resolvePathCandidates(file, cmd);
    const key = `${cmd.pos}\0${cmd.chdir ?? ''}\0${file}`;
    script.paths ??= new Map();
    if (!script.paths.has(key)) script.paths.set(key, resolvePathCandidates(file, cmd));
    return script.paths.get(key)!;
}

function resolvePathCandidates(file: string, cmd: ResolvedCommand): string[] | null {
    const script = cmd.script;
    const provable = (text: string, pos: number) => provableWord(text, cmd, pos);
    const target = provable(file, cmd.pos ?? -1);
    if (target === null) return null;
    if (target.startsWith('/')) return [target];

    if ((script?.cds.length ?? 0) > SQL_PATH_STEPS_MAX) return null;
    let dirs = [script?.cwd ?? currentWorkingDir()];
    const here = cmd.pos === undefined ? undefined : script?.links.get(cmd.pos);
    for (const step of script?.cds ?? []) {
        if (step.pos < 0) continue;
        // A reader inside $(…) carries no position, so every cd is a possible prior one and none is implied.
        if (cmd.pos !== undefined && step.pos >= cmd.pos) continue;
        const next = step.target !== undefined ? provable(step.target, step.pos) : null;
        if (next === null) return null;
        const moved = dirs.map(d => (next.startsWith('/') ? next : join(d, next)));
        const link = script?.links.get(step.pos);
        const implied = !!link && !!here && link.chain === here.chain && link.index < here.index
            && here.operators.slice(link.index, here.index).every(op => op === '&&');
        dirs = implied ? moved : [...new Set([...dirs, ...moved])];
        if (dirs.length > SQL_PATH_CANDIDATES_MAX) return null;
    }
    if (cmd.chdir !== undefined) {
        const chdir = provable(cmd.chdir, cmd.pos ?? -1);
        if (chdir === null) return null;
        dirs = dirs.map(d => (chdir.startsWith('/') ? chdir : join(d, chdir)));
    }
    return dirs.map(d => join(d, target));
}

// Platform CLIs → destructive subcommand verbs
export const PLATFORM_DESTRUCTIVE: Record<string, Set<string>> = {
    render:  new Set(['delete', 'down', 'destroy']),
    railway: new Set(['delete', 'down', 'destroy', 'remove']),
    fly:     new Set(['delete', 'destroy']),
    flyctl:  new Set(['delete', 'destroy']),
    doctl:   new Set(['delete', 'destroy']),
};

// Render's command tree, from `render <command> --help` (v2.22). Each entry lists the flags that command takes
// besides the global -o/--output, --confirm and -h/--help, with whether each takes a value. A `read` needs no
// approval; a `menu` read can open an interactive menu or form that deploys or runs an editor, so it needs an
// explicit plain output; a `proof` change may run free on a resource listed as dev or lab. Every other command, flag,
// spelling or word is a production change.
type RenderFlags = Record<string, 'value' | 'switch'>;
type RenderEntry = { kind: 'read' | 'menu' | 'proof'; flags: RenderFlags };
const LOG_FLAGS: RenderFlags = {
    '--direction': 'value', '--end': 'value', '--host': 'value', '--instance': 'value', '--level': 'value', '--limit': 'value',
    '--method': 'value', '--path': 'value', '--resources': 'value', '--start': 'value', '--status-code': 'value', '--tail': 'switch',
    '--task-id': 'value', '--task-run-id': 'value', '--text': 'value', '--type': 'value',
};
const SERVICE_LIST_FLAGS: RenderFlags = { '--environment-ids': 'value', '--include-previews': 'switch' };
const DATASTORE_LIST_FLAGS: RenderFlags = { '--environment': 'value', '--project': 'value' };
const DATASTORE_GET_FLAGS: RenderFlags = { ...DATASTORE_LIST_FLAGS, '--include-sensitive-connection-info': 'switch' };
const LOCAL_WORKFLOW_FLAGS: RenderFlags = { '--local': 'switch', '--port': 'value' };
const read = (flags: RenderFlags = {}): RenderEntry => ({ kind: 'read', flags });
const menu = (flags: RenderFlags = {}): RenderEntry => ({ kind: 'menu', flags });
const proof = (flags: RenderFlags = {}): RenderEntry => ({ kind: 'proof', flags });
const RENDER_COMMANDS = new Map<string, RenderEntry>([
    ['logs', read(LOG_FLAGS)], ['whoami', read()], ['workspaces', read()], ['workspace', read()], ['workspace set', read()],
    ['help', read()], ['docs', read()], ['login', read()], ['logout', read()], ['skills', read()], ['skills list', read({ '--scope': 'value' })],
    ['projects', menu()], ['environments', menu()],
    ['services', menu(SERVICE_LIST_FLAGS)], ['services list', menu(SERVICE_LIST_FLAGS)], ['services instances', read()],
    ['deploys', menu()], ['deploys list', menu()], ['jobs', menu()], ['jobs list', menu()],
    ['postgres', menu()], ['postgres list', read(DATASTORE_LIST_FLAGS)], ['postgres get', read(DATASTORE_GET_FLAGS)],
    ['keyvalues', menu()], ['keyvalues list', read(DATASTORE_LIST_FLAGS)], ['keyvalues get', read(DATASTORE_GET_FLAGS)],
    ['workflows', menu()], ['workflows list', menu()], ['workflows tasks', menu()], ['workflows tasks list', menu(LOCAL_WORKFLOW_FLAGS)],
    ['workflows tasks runs', menu()], ['workflows tasks runs list', read({ ...LOCAL_WORKFLOW_FLAGS, '--task': 'value' })],
    ['workflows tasks runs show', read(LOCAL_WORKFLOW_FLAGS)], ['workflows versions', menu()], ['workflows versions list', menu()],
    ['blueprints', read()], ['blueprints validate', read({ '--workspace': 'value' })],
    ['restart', proof()], ['deploys create', proof({ '--clear-cache': 'switch', '--commit': 'value', '--image': 'value', '--wait': 'switch' })],
    ['deploys cancel', proof()], ['jobs create', proof({ '--plan-id': 'value', '--start-command': 'value' })], ['jobs cancel', proof()],
    ['services delete', proof()], ['postgres delete', proof()], ['postgres suspend', proof()], ['postgres resume', proof()],
    ['keyvalues delete', proof()], ['keyvalues suspend', proof()], ['keyvalues resume', proof()],
]);
// Commands whose words after them are filters or local CLI state, never a subcommand.
const RENDER_OPEN_READS = new Set(['logs', 'whoami', 'workspaces', 'workspace', 'projects', 'environments', 'help', 'docs', 'login', 'logout', 'skills']);
const RENDER_ALIASES = new Map([['pg', 'postgres'], ['kv', 'keyvalues'], ['keyvalue', 'keyvalues'], ['service', 'services']]);
const RENDER_SHORT = new Map([['o', '--output'], ['r', '--resources'], ['e', '--environment-ids'], ['w', '--workspace']]);
const RENDER_GLOBAL: RenderFlags = { '--output': 'value', '--confirm': 'switch' };
const RENDER_PLAIN_OUTPUT = new Set(['json', 'yaml', 'text']);
const RENDER_EXPANDS = /[[\]*?{}$`~]/;
export const RENDER_RESOURCE_ID_RE = /^[a-z]{3}-[a-z0-9]{20}(?:-[a-z])?$/;
export const RENDER_CHANGE_REASON = 'Production change on Render';

interface RenderShape { command: string; entry: RenderEntry; operands: string[]; output: string | undefined; help: boolean }

/**
 * A render line read word by word against its own command's flags: the command its leading words name (aliases
 * resolved; only global flags may come before them), the words after it, and the output it asked for. Null when any
 * word is unaccounted for: a command or flag outside the table, a flag spelling it doesn't take, a word the shell
 * expands, or a `--` passthrough.
 */
function renderShape(args: string[]): RenderShape | null {
    const words: string[] = [];
    const values = new Map<string, string>();
    let help = false;
    let flagsFor: RenderFlags = RENDER_GLOBAL;
    let command: string | null = null;
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (RENDER_EXPANDS.test(a) || a === '--') return null;
        if (a === '-h' || a === '--help') {
            help = true;
            continue;
        }
        if (!a.startsWith('-') || a === '-') {
            words.push(command === null ? RENDER_ALIASES.get(a) ?? a : a);
            continue;
        }
        const at = a.startsWith('--') ? a.indexOf('=') : -1;
        const flag = a.startsWith('--') ? (at < 0 ? a : a.slice(0, at)) : RENDER_SHORT.get(a[1]);
        if (!flag) return null;
        if (command === null && !(flag in RENDER_GLOBAL)) {
            command = renderCommandOf(words);
            if (command === null) return null;
            flagsFor = { ...RENDER_GLOBAL, ...RENDER_COMMANDS.get(command)!.flags };
        }
        const arity = Object.hasOwn(flagsFor, flag) ? flagsFor[flag] : undefined;
        if (!arity) return null;
        if (arity === 'switch') {
            if (!a.startsWith('--') || (at >= 0 && !['true', 'false'].includes(a.slice(at + 1)))) return null;
            continue;
        }
        const value = a.startsWith('--') ? (at < 0 ? args[++i] : a.slice(at + 1)) : a.length > 2 ? a.slice(2).replace(/^=/, '') : args[++i];
        if (value === undefined || RENDER_EXPANDS.test(value)) return null;
        values.set(flag, value);
    }
    command ??= renderCommandOf(words);
    if (command === null) return null;
    return { command, entry: RENDER_COMMANDS.get(command)!, operands: words.slice(command.split(' ').length), output: values.get('--output'), help };
}

/** The longest known command the leading words name, with `ls` read as `list`; null when they name none. */
function renderCommandOf(words: string[]): string | null {
    const path = words.map((w, i) => (i > 0 && w === 'ls' ? 'list' : w));
    if (path[0] === 'workflows' && path[1] === 'runs') path.splice(1, 1, 'tasks', 'runs');
    for (let n = Math.min(path.length, 4); n > 0; n--) {
        const command = path.slice(0, n).join(' ');
        if (RENDER_COMMANDS.has(command)) {
            words.splice(0, words.length - (path.length - n), ...path.slice(0, n));
            return command;
        }
    }
    return null;
}

export function renderChangeReason(args: string[]): string | null {
    if (args.length === 0 || (args.length === 1 && (args[0] === '-v' || args[0] === '--version'))) return null;
    const shape = renderShape(args);
    if (shape?.help) return null;
    if (shape && shape.entry.kind !== 'proof') {
        const subcommand = !RENDER_OPEN_READS.has(shape.command.split(' ')[0]) && shape.operands.length > 0
            && [...RENDER_COMMANDS.keys()].some(c => c.startsWith(`${shape.command} `));
        if (!subcommand) {
            if (shape.entry.kind === 'read' || RENDER_PLAIN_OUTPUT.has(shape.output ?? '')) return null;
            return `${RENDER_CHANGE_REASON} possible: render ${shape.command} can open an interactive menu that deploys. Add -o json (or yaml/text) to read it without approval.`;
        }
    }
    const words = shape?.command ?? args.filter(a => !a.startsWith('-')).slice(0, 3).join(' ');
    return `${RENDER_CHANGE_REASON} (render ${words || args.join(' ')}).`;
}

const RENDER_RESOURCE_ID_IN_TEXT = new RegExp(String.raw`(?<![a-z0-9-])[a-z]{3}-[a-z0-9]{20}(?:-[a-z])?(?![a-z0-9-])`, 'g');

function renderResourceIds(args: string[]): string[] {
    return args.flatMap(a => a.match(RENDER_RESOURCE_ID_IN_TEXT) ?? []);
}

// ── Path helpers ─────────────────────────────────────────────────────────────

export function expandPath(p: string): string {
    return p
        .replace(/^~(?=\/|$)/, HOME)
        .replace(/^\$\{?HOME\}?(?=\/|$)/, HOME);
}

export function normalizePath(p: string): string {
    const expanded = expandPath(p);
    const resolved = pathResolve(expanded);
    try {
        return realpathSync(resolved);
    } catch {
        return resolved;
    }
}

export function isProtectedAbsolutePath(abs: string): boolean {
    if (/^\/+$/.test(abs)) return true;
    if (/^\/(?:usr|etc|System|private\/etc|bin|sbin|opt\/homebrew|var|Library|Applications)(?:\/|$)/.test(abs)) return true;
    if (abs === HOME || abs === HOME + '/') return true;
    for (const dir of PROTECTED_HOME_DIRS) {
        const prefix = `${HOME}/${dir}`;
        if (abs === prefix || abs.startsWith(prefix + '/')) return true;
    }
    return false;
}

export function isProtectedPath(p: string): boolean {
    if (/^~\/?$/.test(p) || /^\$\{?HOME\}?\/?$/.test(p) || /^\/+$/.test(p)) return true;
    if (/^~\/\*$/.test(p) || /^\$\{?HOME\}?\/\*$/.test(p)) return true;
    if (/^\/\*/.test(p) || /^\.\.(?:\/|$)/.test(p)) return true;
    return isProtectedAbsolutePath(normalizePath(p));
}

export function isSafePath(p: string): boolean {
    const normalized = normalizePath(p);
    return SAFE_PATH_PATTERNS.some(pat => pat.test(normalized));
}

// ── AST helpers ──────────────────────────────────────────────────────────────

/**
 * Walk an unbash AST node and collect every Command node bash could run: in a
 * list, pipeline, condition (`if`/`while`/`until`), case arm, loop, function,
 * group or coproc, and inside any `$(…)`, backticks or `<(…)` wherever a word
 * can hold one: a command name, argument, assignment value or array element,
 * redirect target, unquoted heredoc body, `${x:-…}` operand, `[[ ]]` operand,
 * `$(( ))`, `(( ))` or case subject.
 */
export function walkCommandNodes(node: any, out: any[] = []): any[] {
    if (!node || typeof node !== 'object') return out;
    switch (node.type) {
        case 'Command':
            out.push(node);
            hostCommands.push(node);
            try {
                walkPartsForSubstitutions(node.name, out);
                for (const s of (node.suffix || [])) walkPartsForSubstitutions(s, out);
                for (const p of (node.prefix || [])) {
                    walkPartsForSubstitutions(p?.value, out);
                    for (const w of (p?.array || [])) walkPartsForSubstitutions(w, out);
                }
                walkRedirectsForCommands(node.redirects, out);
            } finally {
                hostCommands.pop();
            }
            return out;
        case 'Statement':
            walkCommandNodes(node.command, out);
            walkRedirectsForCommands(node.redirects, out);
            return out;
        case 'If':
        case 'While':
            walkCommandNodes(node.clause, out);
            walkCommandNodes(node.then, out);
            walkCommandNodes(node.body, out);
            walkCommandNodes(node.else, out);
            return out;
        case 'Case':
            walkPartsForSubstitutions(node.word, out);
            for (const item of (node.items || [])) {
                for (const w of (item?.pattern || [])) walkPartsForSubstitutions(w, out);
                walkCommandNodes(item?.body, out);
            }
            return out;
        case 'TestCommand':
            walkTestExpression(node.expression, out);
            return out;
        case 'ArithmeticCommand':
            collectCommandsInText(String(node.body ?? ''), out);
            return out;
        case 'ArithmeticFor':
            for (const e of [node.initialize, node.test, node.update]) walkArithmeticExpression(e, out);
            walkCommandNodes(node.body, out);
            return out;
        default:
            for (const w of (node.wordlist || [])) walkPartsForSubstitutions(w, out);
            for (const child of (node.commands || [])) walkCommandNodes(child, out);
            walkCommandNodes(node.body, out);
            walkCommandNodes(node.command, out);
            walkRedirectsForCommands(node.redirects, out);
            return out;
    }
}

// Command nodes found inside a substitution. unbash gives them offsets relative
// to the substitution, so they must not be matched against top-level offsets.
const NESTED_COMMAND_NODES = new WeakSet<object>();
// The substitution script each nested command node sits directly in.
const SUBSTITUTION_OF = new WeakMap<object, object>();
// The outermost command whose words hold each substitution script; its offset is where the substitution runs.
const SUBSTITUTION_HOST = new WeakMap<object, any>();
// Each substitution script's own text, which its nested offsets index.
const SUBSTITUTION_TEXT = new WeakMap<object, string>();
// Substitutions per command line whose variables are expanded against their own text; past it only the host's apply.
const SUBSTITUTION_VIEWS_MAX = 16;
const hostCommands: any[] = [];

function addNestedCommands(script: any, commands: any[]): void {
    if (script && typeof script === 'object' && hostCommands.length && !SUBSTITUTION_HOST.has(script)) SUBSTITUTION_HOST.set(script, hostCommands[0]);
    for (const inner of walkCommandNodes(script)) {
        // A node a deeper substitution already claimed sits directly in that one, not in this script.
        if (!NESTED_COMMAND_NODES.has(inner)) {
            NESTED_COMMAND_NODES.add(inner);
            if (script && typeof script === 'object') SUBSTITUTION_OF.set(inner, script);
        }
        commands.push(inner);
    }
}

/**
 * Give each SQL client inside a `$(…)` what the pipeline it heads in that substitution feeds it, then drop every nested
 * command's offset: offsets there are relative to the substitution, so the top-level map can neither hold nor be
 * matched against them. Only the substitution's own pipelines are read (by node, not offset), so each is visited once.
 */
function traceSubstitutionPipes(nested: Array<[any, ResolvedCommand]>, command: string): void {
    const byNode = new Map<any, ResolvedCommand>(nested);
    let views = 0;
    const inSub = new Map<object, ResolvedCommand[]>();
    for (const [n, c] of nested) {
        const owner = SUBSTITUTION_OF.get(n);
        if (!owner) continue;
        const list = inSub.get(owner);
        if (list) list.push(c);
        else inSub.set(owner, [c]);
    }
    const done = new Set<object>();
    for (const [node, cmd] of nested) {
        if (!SQL_CLIS[cmd.name] && cmd.name !== 'snow') continue;
        const sub: any = SUBSTITUTION_OF.get(node);
        if (!sub || done.has(sub)) continue;
        done.add(sub);
        const hostPos = SUBSTITUTION_HOST.get(sub)?.pos;
        const text = SUBSTITUTION_TEXT.get(sub);
        // Variables set inside the substitution expand against its own text, at the emitter's own offset.
        const withinCap = ++views <= SUBSTITUTION_VIEWS_MAX;
        const local = text && withinCap
            ? ({ writes: [], pipedInto: new Map(), cds: [], links: new Map(), command: text } as ScriptContext)
            : null;
        const hostView = typeof hostPos === 'number' && withinCap
            ? ({ writes: [], pipedInto: new Map(), cds: [], links: new Map(), command: command.slice(0, hostPos) } as ScriptContext)
            : null;
        // A client's own words expand like an emitter's: against the substitution's text, and against the line before it
        // unless the substitution assigns the variable first.
        for (const c of inSub.get(sub) ?? []) {
            if ((!SQL_CLIS[c.name] && c.name !== 'snow') || !holdsVariable(c)) continue;
            if (!withinCap) {
                c.expandAs = null;
                continue;
            }
            c.expandAs = [];
            if (local && c.pos !== undefined) c.expandAs.push({ ...c, script: local });
            if (hostView && typeof hostPos === 'number' && !assignsInside(text?.slice(0, c.pos ?? 0), c)) {
                c.expandAs.push({ ...c, pos: hostPos, argsAreValues: true, script: hostView });
            }
        }
        // A relative `cd`/`pushd` earlier in the substitution moves where its `cat` files are read from.
        const catDir = new Map<ResolvedCommand, string>();
        let dir: string | null | undefined;
        for (const c of inSub.get(sub) ?? []) {
            if (typeof dir === 'string') catDir.set(c, dir);
            if (c.name !== 'cd' && c.name !== 'pushd') continue;
            const target = c.args.length === 1 && !/[$`*?]|^[+-]/.test(c.args[0]) ? c.args[0] : null;
            dir = target === null || dir === null ? null : target.startsWith('/') ? target : join(dir ?? '', target);
        }
        // A `cd` may fail and the shell runs on, so a relative file may be read from either directory.
        const catFilesOf = (up: ResolvedCommand) => {
            const at = catDir.get(up);
            return catOperands(up).flatMap(f => (at && !f.startsWith('/') ? [join(at, f), f] : [f]));
        };
        const pipelines: any[] = [];
        pipelinesIn(sub, pipelines, 0);
        for (const pipeline of pipelines) {
            const stages = pipeline.commands || [];
            for (let i = 1; i < stages.length; i++) {
                const input: PipedInput = { texts: [], catFiles: [], from: [], textFrom: [], emitters: [] };
                for (const up of commandsIn(stages[i - 1], 0).map(n => byNode.get(n)).filter((c): c is ResolvedCommand => !!c)) {
                    if (!TEXT_EMITTERS.has(up.name) || up.stdoutFiles?.length) continue;
                    input.texts.push(...emittedText(up));
                    if (up.name === 'cat') input.catFiles.push(...catFilesOf(up));
                    if (up.pipedInput) (up.name === 'cat' || up.name === 'tee' ? input.from! : input.textFrom!).push(up.pipedInput);
                    if (!holdsVariable(up)) continue;
                    // Past the view cap its variables can't be expanded, so what it prints is unknown.
                    if (!withinCap) input.unknown = true;
                    // Variables set before the substitution expand where the command holding it starts, read from the
                    // line up to there (the full line's view counts any assignment inside a substitution as unknown),
                    // unless the substitution assigns them itself first, which shadows the outer value.
                    if (hostView && typeof hostPos === 'number' && !assignsInside(text?.slice(0, up.pos ?? 0), up)) {
                        input.emitters!.push({ ...up, pos: hostPos, argsAreValues: true, script: hostView });
                    }
                    if (local && up.pos !== undefined) input.emitters!.push({ ...up, script: local });
                }
                for (const down of commandsIn(stages[i], 0).map(n => byNode.get(n)).filter((c): c is ResolvedCommand => !!c)) {
                    down.pipedInput = down.pipedInput ? { texts: [], catFiles: [], from: [down.pipedInput, input] } : input;
                }
            }
        }
    }
    for (const [, cmd] of nested) delete cmd.pos;
}

/** The substitution text before `cmd` assigns a variable its words reference. */
function assignsInside(text: string | undefined, cmd: ResolvedCommand): boolean {
    if (!text) return false;
    const names = [...cmd.args, ...(cmd.stdinExpanded ?? []).map(w => w.plain)].flatMap(t => [...t.matchAll(/\$\{?([A-Za-z_]\w*)/g)].map(m => m[1]));
    return names.some(name => new RegExp(`(?:^|[\\s;&|(])(?:export\\s+|local\\s+|declare\\s+)?${name}=`).test(text));
}

/** The command nodes a pipeline stage runs: itself, or those inside a group, subshell or compound stage. */
function commandsIn(node: any, depth: number, out: any[] = []): any[] {
    if (!node || typeof node !== 'object' || depth > PIPE_NESTING_MAX) return out;
    if (Array.isArray(node)) {
        for (const child of node) commandsIn(child, depth, out);
        return out;
    }
    if (node.type === 'Command') {
        out.push(node);
        return out;
    }
    for (const child of [node.commands, node.command, node.clause, node.then, node.else, node.body]) commandsIn(child, depth + 1, out);
    for (const item of node.items || []) commandsIn(item?.body, depth + 1, out);
    return out;
}

/** Every pipeline in a substitution's own command lists, including those inside if/loop/case bodies and groups. */
function pipelinesIn(node: any, out: any[], depth: number): void {
    if (!node || typeof node !== 'object' || depth > PIPE_NESTING_MAX) return;
    if (Array.isArray(node)) {
        for (const child of node) pipelinesIn(child, out, depth);
        return;
    }
    // A pipeline's compound stages can hold pipelines of their own (`… | { cat f | psql; }`), so keep descending.
    if (node.type === 'Pipeline') out.push(node);
    if (node.type === 'Command') return;
    for (const child of [node.commands, node.command, node.clause, node.then, node.else, node.body]) pipelinesIn(child, out, depth + 1);
    for (const item of node.items || []) pipelinesIn(item?.body, out, depth + 1);
}

/** Walk a word's parts (computed lazily by unbash) to find the commands inside `$(…)`, backticks and `<(…)` */
export function walkPartsForSubstitutions(node: any, commands: any[]): void {
    if (!node || typeof node !== 'object') return;
    if (['CommandExpansion', 'ProcessSubstitution', 'CommandSubstitution', 'Backtick'].includes(node.type)) {
        const sub = node.script ?? node.body ?? node.command;
        const text = typeof node.text === 'string' ? node.text : '';
        if (sub && typeof sub === 'object' && text) SUBSTITUTION_TEXT.set(sub, text.startsWith('`') ? text.slice(1, -1) : text.slice(2, -1));
        addNestedCommands(sub, commands);
    }
    if (node.type === 'ArithmeticExpansion') collectCommandsInText(String(node.text ?? ''), commands);
    if (node.type === 'ParameterExpansion') {
        walkPartsForSubstitutions(node.operand, commands);
        walkPartsForSubstitutions(node.slice?.offset, commands);
        walkPartsForSubstitutions(node.slice?.length, commands);
        walkPartsForSubstitutions(node.replace?.pattern, commands);
        walkPartsForSubstitutions(node.replace?.replacement, commands);
    }
    for (const part of (node.parts || [])) {
        walkPartsForSubstitutions(part, commands);
    }
}

function walkRedirectsForCommands(redirects: any, commands: any[]): void {
    for (const r of (redirects || [])) {
        walkPartsForSubstitutions(r?.target, commands);
        // An unquoted heredoc body is expanded like a double-quoted word.
        if ((r?.operator === '<<' || r?.operator === '<<-') && !r.heredocQuoted) {
            collectCommandsInText(String(r.content ?? ''), commands);
        }
    }
}

function walkTestExpression(expr: any, commands: any[]): void {
    if (!expr || typeof expr !== 'object') return;
    walkPartsForSubstitutions(expr.operand?.type ? null : expr.operand, commands);
    walkPartsForSubstitutions(expr.left?.type ? null : expr.left, commands);
    walkPartsForSubstitutions(expr.right?.type ? null : expr.right, commands);
    for (const sub of [expr.operand, expr.left, expr.right, expr.expression]) {
        if (sub?.type) walkTestExpression(sub, commands);
    }
}

function walkArithmeticExpression(expr: any, commands: any[]): void {
    if (!expr || typeof expr !== 'object') return;
    if (expr.type === 'ArithmeticWord') collectCommandsInText(String(expr.value ?? ''), commands);
    for (const sub of [expr.left, expr.right, expr.operand, expr.test, expr.consequent, expr.alternate, expr.expression]) {
        walkArithmeticExpression(sub, commands);
    }
}

/**
 * Commands inside every `$(…)` and backtick span of raw text that bash expands
 * but unbash leaves unparsed: an unquoted heredoc body, `$(( ))`, `(( ))`.
 * Each span is parsed as its own script.
 */
function collectCommandsInText(text: string, commands: any[]): void {
    if (!text.includes('$(') && !text.includes('`')) return;
    for (const inner of substitutionSpans(text)) {
        try {
            addNestedCommands(parseShell(inner), commands);
        } catch {
            // An unparsable span cannot be inspected; its text still reaches the regex fallback below.
            commands.push(...fallbackExtract(inner).map(c => ({ __resolved: c })));
        }
    }
}

/** The inner text of each `$(…)` (not `$((`) and backtick span in `text`, outermost first. */
function substitutionSpans(text: string): string[] {
    const spans: string[] = [];
    for (let i = 0; i < text.length; i++) {
        if (text[i] === '\\') { i++; continue; }
        if (text[i] === '`') {
            const close = text.indexOf('`', i + 1);
            if (close === -1) break;
            spans.push(text.slice(i + 1, close));
            i = close;
            continue;
        }
        if (text[i] === '$' && text[i + 1] === '(') {
            if (text[i + 2] === '(') { i += 2; continue; }
            let depth = 1;
            let j = i + 2;
            let quote: string | null = null;
            for (; j < text.length && depth > 0; j++) {
                const c = text[j];
                if (c === '\\') { j++; continue; }
                if (quote) { if (c === quote) quote = null; continue; }
                if (c === "'" || c === '"') quote = c;
                else if (c === '(') depth++;
                else if (c === ')') depth--;
            }
            if (depth !== 0) break;
            spans.push(text.slice(i + 2, j - 1));
            i = j - 1;
        }
    }
    return spans;
}

/** Split an `env -S` string into words the way GNU env does: whitespace and
 *  `\_` separate, quotes group, `\c` and a word-initial `#` end the string.
 *  Null for what cannot be resolved statically (`$` expansion, an unknown
 *  escape): the caller must then refuse rather than guess. */
function splitEnvString(text: string): string[] | null {
    const words: string[] = [];
    let word = '';
    let inWord = false;
    let quote: '"' | "'" | null = null;
    const ESCAPED: Record<string, string> = { t: '\t', n: '\n', v: '\v', f: '\f', r: '\r' };
    for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        if (ch === '\\') {
            const next = text[++i];
            if (next === undefined) return null;
            if (quote === "'") {
                if (next === '\\' || next === "'") word += next; else word += ch + next;
                continue;
            }
            if (next === 'c') break;
            if (next === '_') {
                if (quote === '"') { word += ' '; continue; }
                if (inWord) { words.push(word); word = ''; inWord = false; }
                continue;
            }
            if (next in ESCAPED) word += ESCAPED[next];
            else if ('\\"\'#$ '.includes(next)) word += next;
            else return null;
            inWord = true;
            continue;
        }
        if (quote === "'") {
            if (ch === "'") quote = null; else word += ch;
            continue;
        }
        if (ch === '$') return null;
        if (quote === '"') {
            if (ch === '"') quote = null; else word += ch;
            continue;
        }
        if (ch === '"' || ch === "'") { quote = ch; inWord = true; continue; }
        if (ch === '#' && !inWord) break;
        if (/\s/.test(ch)) {
            if (inWord) { words.push(word); word = ''; inWord = false; }
            continue;
        }
        word += ch;
        inWord = true;
    }
    if (quote) return null;
    if (inWord) words.push(word);
    return words;
}

/**
 * The command a wrapper chain finally runs (sudo, env, nice, timeout, exec, npx, pnpm exec, …), with the env
 * assignments and `env -C` directory picked up on the way. Shared by the top-level resolver and by the commands
 * xargs and find -exec run, so a wrapper is unwrapped the same way wherever it appears.
 */
export function stripWrappers(word: string, rest: string[]): { name: string; args: string[]; env: string[]; chdir?: string; onecliAgent?: string } {
    let name = commandName(word);
    let args = rest;
    let chdir: string | undefined;
    let onecliAgent: string | undefined;
    const env: string[] = [];
    // Resolve through wrapper commands
    while (WRAPPERS.has(name) && args.length > 0) {
        let skip = 0;

        if (name === 'sudo') {
            // Skip flags. A short option (or cluster such as `-nu`) ending in a value-taking letter consumes the next
            // word; `--opt=value` forms are one word.
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                const dir = sudoChdir(args[skip], args[skip + 1]);
                if (dir !== undefined) chdir = chdir === undefined || dir.startsWith('/') ? dir : `${chdir}/${dir}`;
                skip += optionWords(args[skip], 'aCcDghpRrTtUu', SUDO_LONG_VALUE_OPTIONS, SUDO_LONG_FLAGS);
            }
            if (args[skip] === '--') skip += 1;
            // `sudo [options] [VAR=value]... command`, like env.
            while (skip < args.length && /^\w+=/.test(args[skip])) env.push(args[skip++]);
        } else if (name === 'env') {
            // Skip flags and VAR=val assignments, keeping the assignments.
            // `-u NAME` and `-C DIR` take the next argument; `-S STRING` IS the
            // command line, split on whitespace.
            while (skip < args.length && (args[skip].startsWith('-') || /^\w+=/.test(args[skip]))) {
                const a = args[skip];
                if (/^\w+=/.test(a)) env.push(a);
                if (a === '-S' || a === '--split-string' || /^(?:-S.|--split-string=)/.test(a)) {
                    const inline = a.startsWith('--split-string=') ? a.slice('--split-string='.length)
                        : a.length > 2 && a.startsWith('-S') ? a.slice(2) : null;
                    const words = splitEnvString(inline ?? args[skip + 1] ?? '');
                    if (words === null) {
                        // Unresolvable: refuse it the way eval is refused.
                        name = 'eval';
                        args = [];
                        break;
                    }
                    args = [...args.slice(0, skip), ...words, ...args.slice(skip + (inline === null ? 2 : 1))];
                    continue;
                }
                const dir = a === '-C' || a === '--chdir' ? args[skip + 1]
                    : a.startsWith('--chdir=') ? a.slice('--chdir='.length)
                    : /^-C./.test(a) ? a.slice(2) : undefined;
                if (dir !== undefined) chdir = chdir === undefined || dir.startsWith('/') ? dir : `${chdir}/${dir}`;
                skip += a === '-u' || a === '--unset' || a === '-C' || a === '--chdir' ? 2 : 1;
            }
        } else if (name === 'nice') {
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                skip += args[skip] === '-n' || args[skip] === '--adjustment' ? 2 : 1;
            }
            if (args[skip] === '--') skip += 1;
        } else if (name === 'timeout' || name === 'gtimeout') {
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                skip += optionWords(args[skip], 'ks', TIMEOUT_LONG_VALUE_OPTIONS, TIMEOUT_LONG_FLAGS);
            }
            if (args[skip] === '--') skip += 1;
            skip += 1;
        } else if (name === 'command' || name === 'builtin') {
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') skip += 1;
            if (args[skip] === '--') skip += 1;
        } else if (name === 'pnpm' || name === 'yarn') {
            // Only `exec`/`dlx` run an arbitrary command. `pnpm run <script>`
            // executes a package.json script whose body is not on this command
            // line, so there is nothing here to resolve — leave it alone.
            while (skip < args.length && args[skip].startsWith('-')) skip += 1;
            if (!(skip < args.length && (args[skip] === 'exec' || args[skip] === 'dlx'))) break;
            skip += 1;
        } else if (name === 'exec') {
            // `exec -a NAME` sets argv[0]; -c and -l take nothing, and the three cluster (`-ca NAME`).
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                skip += optionWords(args[skip], 'a');
            }
            if (args[skip] === '--') skip += 1;
        } else if (name === 'onecli') {
            // `onecli run [options] -- <command>` runs the command with credentials injected; nothing else does.
            const split = args.indexOf('--');
            if (args[0] !== 'run' || split < 0) break;
            const own = args.slice(1, split);
            const at = own.findIndex(a => a === '--agent' || a.startsWith('--agent='));
            if (at >= 0) onecliAgent = own[at].startsWith('--agent=') ? own[at].slice('--agent='.length) : own[at + 1];
            skip = split + 1;
        } else if (name === 'npx' || name === 'bunx') {
            // The command follows the flags; -p/--package takes a value.
            while (skip < args.length && args[skip].startsWith('-')) {
                skip += args[skip] === '-p' || args[skip] === '--package' ? 2 : 1;
            }
        } else if (name === 'stdbuf') {
            // -i/-o/-e MODE (and --input/--output/--error) take a value.
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                skip += optionWords(args[skip], 'ioe', new Set(['--input', '--output', '--error']));
            }
            if (args[skip] === '--') skip += 1;
        } else if (name === 'setsid') {
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') skip += 1;
            if (args[skip] === '--') skip += 1;
        } else if (name === 'nohup' || name === 'time') {
            // GNU time's -o FILE and -f FORMAT (and --output/--format) take the next word.
            while (skip < args.length && args[skip].startsWith('-') && args[skip] !== '--') {
                skip += name === 'time' ? optionWords(args[skip], 'of', new Set(['--output', '--format']), new Set(['--append', '--verbose', '--portability', '--quiet'])) : 1;
            }
            if (args[skip] === '--') skip += 1;
        }

        if (skip >= args.length) break;

        name = commandName(args[skip]);
        args = args.slice(skip + 1);
    }
    return { name, args, env, ...(chdir !== undefined ? { chdir } : {}), ...(onecliAgent !== undefined ? { onecliAgent } : {}) };
}

const BRACE_EXPANSION_MAX = 1024;

/**
 * The words bash makes of `text` by brace expansion (`{a,b}`, `{1..3}`, `x{a,b}y`, nested), still quoted; null when
 * it would make more than BRACE_EXPANSION_MAX. Quoted, escaped and `${` braces are left alone, as bash leaves them.
 */
function braceExpand(text: string): string[] | null {
    const out: string[] = [];
    const walk = (s: string): boolean => {
        for (let i = 0; i < s.length; i++) {
            const c = s[i];
            if (c === '\\') { i++; continue; }
            if (c === "'") { i = s.indexOf("'", i + 1); if (i < 0) break; continue; }
            if (c === '"') { for (i++; i < s.length && s[i] !== '"'; i++) if (s[i] === '\\') i++; continue; }
            if (c !== '{' || s[i - 1] === '$') continue;
            const commas: number[] = [];
            let depth = 0, end = -1;
            for (let j = i + 1; j < s.length && end < 0; j++) {
                const d = s[j];
                if (d === '\\') { j++; continue; }
                if (d === "'") { j = s.indexOf("'", j + 1); if (j < 0) break; continue; }
                if (d === '"') { for (j++; j < s.length && s[j] !== '"'; j++) if (s[j] === '\\') j++; continue; }
                if (d === '{' && s[j - 1] !== '$') depth++;
                else if (d === '}') { if (depth === 0) end = j; else depth--; }
                else if (d === ',' && depth === 0) commas.push(j);
            }
            if (end < 0) break;
            const inner = s.slice(i + 1, end);
            let alts: string[] | null = null;
            if (commas.length) {
                alts = [];
                let from = i + 1;
                for (const k of [...commas, end]) { alts.push(s.slice(from, k)); from = k + 1; }
            } else {
                const m = inner.match(/^(-?\d+|[A-Za-z])\.\.(-?\d+|[A-Za-z])(?:\.\.(-?\d+))?$/);
                const numeric = m && /\d/.test(m[1]) && /\d/.test(m[2]);
                if (m && (numeric || (/^[A-Za-z]$/.test(m[1]) && /^[A-Za-z]$/.test(m[2])))) {
                    const a = numeric ? Number(m[1]) : m[1].charCodeAt(0), b = numeric ? Number(m[2]) : m[2].charCodeAt(0);
                    if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b) || !Number.isSafeInteger(Number(m[3] ?? 1))) return false;
                    const step = Math.abs(Number(m[3] ?? 1)) || 1;
                    if (Math.abs(b - a) / step >= BRACE_EXPANSION_MAX) return false;
                    const width = numeric && /^-?0\d/.test(m[1] + ' ' + m[2]) ? Math.max(m[1].length, m[2].length) : 0;
                    alts = [];
                    for (let v = a; a <= b ? v <= b : v >= b; v += a <= b ? step : -step) {
                        alts.push(numeric ? (v < 0 ? '-' + String(-v).padStart(width - 1, '0') : String(v).padStart(width, '0')) : String.fromCharCode(v));
                    }
                }
            }
            if (!alts) continue;
            const pre = s.slice(0, i), post = s.slice(end + 1);
            for (const alt of alts) if (!walk(pre + alt + post)) return false;
            return true;
        }
        out.push(s);
        return out.length <= BRACE_EXPANSION_MAX;
    };
    return walk(text) ? out : null;
}

/** A word as the arguments bash passes for it: brace-expanded, then unquoted. Null when expansion is too large to follow. */
function wordArgs(word: any): string[] | null {
    // The parser marks only some brace expansions (not one holding quotes), so every word with a `{` is tried.
    const text = String(word?.text ?? '');
    if (!text.includes('{')) return [wordValue(word)];
    const words = braceExpand(text);
    if (words && words.length === 1 && words[0] === text) return [wordValue(word)];
    // An unquoted empty alternative makes no word, as in bash; a quoted one (`''`) still does.
    return words && words.filter(w => w !== '').map(w => shellUnquote(w));
}

/** Resolve a Command AST node: strip wrapper commands, extract name + args */
export function resolveCommand(node: any): ResolvedCommand | null {
    if (!node.name) return null;

    const env: string[] = (node.prefix || [])
        .filter((p: any) => p?.type === 'Assignment' && typeof p.name === 'string')
        .map((p: any) => `${p.name}=${p.value?.value ?? p.value?.text ?? ''}`);
    const expanded = [node.name, ...(node.suffix || [])].map(wordArgs);
    // Bash runs what brace expansion makes, the command name included; past the cap it is refused the way eval is.
    const blocked = expanded.some(w => w === null);
    const words = blocked ? ['eval'] : (expanded as string[][]).flat();
    const first = blocked || expanded[0]!.length !== 1 || expanded[0]![0] !== wordValue(node.name) ? words[0] ?? '' : node.name.value || '';
    const stripped = stripWrappers(first, words.slice(1));
    const { name, args, chdir, onecliAgent } = stripped;
    env.push(...stripped.env);

    // Check for input redirects (<<, <<<) on the original Command node
    const hasInputRedirect = (node.redirects || []).some((r: any) =>
        ['<<', '<<<', '<<-'].includes(r.operator)
    );
    const stdinTexts: string[] = [];
    const stdinExpanded: ExpandableWord[] = [];
    const stdinFiles: string[] = [];
    const stdoutFiles: string[] = [];
    for (const r of (node.redirects || [])) {
        if (['>', '>>', '>|', '&>', '&>>'].includes(r?.operator) && (r.fileDescriptor === undefined || r.fileDescriptor === 1)) {
            stdoutFiles.push(wordValue(r.target));
        }
        if (r?.operator === '<<' || r?.operator === '<<-') {
            stdinTexts.push(String(r.content ?? ''));
            if (!r.heredocQuoted) stdinExpanded.push(heredocBodyWord(String(r.content ?? '')));
        } else if (r?.operator === '<<<') {
            stdinTexts.push(wordValue(r.target));
            if (!String(r.target?.text ?? '').startsWith("'")) stdinExpanded.push(heredocWord(wordValue(r.target)));
        }
        else if (r?.operator === '<' || r?.operator === '<>') stdinFiles.push(wordValue(r.target));
    }

    // Reconstruct raw text for error messages
    const rawParts = [node.name.text || node.name.value, ...(node.suffix || []).map((s: any) => s.text || s.value)];

    return {
        name,
        args,
        raw: rawParts.join(' '),
        env,
        ...(chdir !== undefined ? { chdir } : {}),
        ...(onecliAgent !== undefined ? { onecliAgent } : {}),
        hasInputRedirect,
        pos: typeof node.pos === 'number' ? node.pos : undefined,
        ...(stdinTexts.length ? { stdinTexts } : {}),
        ...(stdinExpanded.length ? { stdinExpanded } : {}),
        ...(stdinFiles.length ? { stdinFiles } : {}),
        ...(stdoutFiles.length ? { stdoutFiles } : {}),
    };
}

/**
 * A word's value with its quotes removed. unbash leaves a multi-line quoted word
 * unsplit, quotes included, so `"select 1;\ndrop table t"` would otherwise reach
 * the SQL scanner as one quoted identifier and hide the DROP.
 */
function wordValue(word: any): string {
    const value = String(word?.value ?? word?.text ?? '');
    return typeof word?.text === 'string' && word.text === value && /['"\\]/.test(value) ? shellUnquote(value) : value;
}

/**
 * A command name as bash runs it. Bash drops an unquoted backslash before looking the name up, so `\rm` (the usual way
 * to skip an `rm -i` alias) and `r\m` both run `rm`; the parser leaves the backslash in.
 */
function unescapeCommandWord(word: string): string {
    return word.replace(/\\(.)/gs, '$1');
}

/** A command word as the rules match it: unescaped, and by basename, so `/bin/rm`, `/opt/homebrew/bin/rm` and `\rm` are all `rm`. */
export function commandName(word: string): string {
    return unescapeCommandWord(word).replace(/^.*\//, '');
}

/** The directory a sudo option word sets with `-D DIR`, `-DDIR`, a cluster ending in D, or `--chdir[=DIR]`. */
function sudoChdir(arg: string, next: string | undefined): string | undefined {
    if (arg.startsWith('--')) {
        const [name, value] = arg.includes('=') ? [arg.slice(0, arg.indexOf('=')), arg.slice(arg.indexOf('=') + 1)] : [arg, next];
        return name.length > 4 && '--chdir'.startsWith(name) ? value : undefined;
    }
    const at = [...arg.slice(1)].findIndex(c => 'aCcDghpRrTtUu'.includes(c)) + 1;
    if (at === 0 || arg[at] !== 'D') return undefined;
    return at === arg.length - 1 ? next : arg.slice(at + 1);
}

const TIMEOUT_LONG_VALUE_OPTIONS = new Set(['--signal', '--kill-after']);
const TIMEOUT_LONG_FLAGS = new Set(['--preserve-status', '--foreground', '--verbose']);
const SUDO_LONG_FLAGS = new Set(['--login', '--preserve-env', '--non-interactive', '--background', '--shell', '--stdin',
    '--set-home', '--edit', '--list', '--validate', '--remove-timestamp', '--reset-timestamp', '--askpass', '--bell',
    '--help', '--version']);
const SUDO_LONG_VALUE_OPTIONS = new Set(['--user', '--group', '--close-from', '--chdir', '--host', '--prompt', '--chroot',
    '--role', '--type', '--command-timeout', '--other-user', '--auth-type', '--login-class']);

// `--eof[=END]` takes its value only attached, so a bare `--eof` is a flag.
// `--max-lines[=N]`, `--eof[=END]` and `--replace[=R]` take a value only when attached.
const XARGS_LONG_VALUE_OPTIONS = new Set(['--arg-file', '--delimiter', '--max-args', '--max-procs', '--max-chars',
    '--process-slot-var']);
const XARGS_LONG_FLAGS = new Set(['--null', '--interactive', '--no-run-if-empty', '--verbose', '--exit', '--open-tty',
    '--show-limits', '--max-lines', '--eof', '--replace', '--help', '--version']);

/**
 * How many words a command's option takes, read the way getopt does: in a short cluster such as `-0a` or `-nu`, the
 * first letter in `valueLetters` takes the rest of the word as its value (`-uroot`), or the next word when it is last.
 */
function optionWords(arg: string, valueLetters: string, longValueOptions?: Set<string>, longFlags?: Set<string>): 1 | 2 {
    if (arg.startsWith('--')) {
        // getopt_long takes an exact name first (`--login` is not `--login-class`), then any unambiguous abbreviation
        // (`--arg-f`); a prefix of a value-taking option takes one.
        if (arg.includes('=') || !longValueOptions || longFlags?.has(arg)) return 1;
        if (longValueOptions.has(arg)) return 2;
        return [...longValueOptions].some(o => o.startsWith(arg) && arg.length > 2) ? 2 : 1;
    }
    for (let i = 1; i < arg.length; i++) {
        if (valueLetters.includes(arg[i])) return i === arg.length - 1 ? 2 : 1;
    }
    return 1;
}

/** The command xargs runs and its arguments, past xargs's own options (`-0`, `-I{}`, `-n 1`, `--max-procs=4`, …). */
function xargsCommand(args: string[]): string[] {
    let i = 0;
    while (i < args.length && args[i].startsWith('-')) {
        const a = args[i];
        if (a === '--') return args.slice(i + 1);
        i += optionWords(a, 'adEIJLnPRsS', XARGS_LONG_VALUE_OPTIONS, XARGS_LONG_FLAGS);
    }
    return args.slice(i);
}

const RUNS_RM = 'runs rm';

/**
 * Why the command xargs or find -exec runs is blocked, or null. A shell it runs with `-c` is judged by the commands
 * in its script, not refused outright as a top-level `sh -c` is: `xargs -I{} sh -c 'grep … {}'` is routine, while
 * `xargs sh -c 'rm "$@"'` still deletes.
 */
function innerHardBlock(inner: ResolvedCommand | null): string | null {
    const steps = innerSteps(inner);
    if (steps === RUNS_VARIABLE) return RUNS_VARIABLE;
    for (const cmd of steps) {
        const reason = cmd.name === 'rm' ? RUNS_RM : checkHardBlock(cmd);
        if (reason) return reason;
    }
    return null;
}

/**
 * The commands `inner` runs: itself, or the commands of the script it runs as a shell with `-c`. With `appended`,
 * xargs adds the words it reads after the written ones, so a positional parameter past them reads as `{}`.
 */
function innerSteps(inner: ResolvedCommand | null, appended = false): ResolvedCommand[] | typeof RUNS_VARIABLE {
    if (!inner) return [];
    const script = SHELLS.has(inner.name) ? shellScript(inner.name, inner.args) : null;
    if (!script) return [inner];
    const steps: ResolvedCommand[] = [];
    for (const nested of extractCommands(script.text)) {
        // A command taken from a parameter is whatever xargs reads from input or find matches, which cannot be known.
        if (nested.name.includes('$')) return RUNS_VARIABLE;
        const args = expandPositional(inner.name, nested.args, inner.args.slice(script.rest), appended);
        const step = args ? { ...nested, args } : nested;
        // A command the script runs starts in the shell's own directory (an `env -C` wrapper on the shell).
        steps.push(inner.chdir !== undefined && step.chdir === undefined ? { ...step, chdir: inner.chdir } : step);
    }
    return steps;
}

// The word that stands for what xargs reads or find matches, wherever it lands in the command they run: xargs's
// replace string, find's `{}`, and the words xargs appends all become it.
const FILLED = '{}';
// xargs appends any number of words, so its tail is several: enough for the values a wrapper's written options still
// take (`timeout -s`, `env -C`, `sudo -u`) and then the command, which the first marker left over names.
const FILLED_TAIL = [FILLED, FILLED, FILLED, FILLED];
// Where -execdir and -okdir run the command: only the matches decide it.
const EACH_MATCH_DIR = 'the directory of each match';
const EACH_SUBMODULE_DIR = 'each submodule';

/**
 * What xargs, or each find -exec/-execdir/-ok/-okdir, runs: the option that runs it and the command it runs, with
 * FILLED where its input or a match goes. `tail`: xargs appends what it reads, so more words may follow the last.
 */
function execRuns(cmd: ResolvedCommand): Array<{ via: string; inner: ResolvedCommand | null; tail?: boolean }> {
    if (cmd.name === 'xargs') {
        const words = xargsCommand(cmd.args);
        const replace = xargsReplaceString(cmd.args);
        const filled = replace !== null ? words.map(w => w.split(replace).join(FILLED)) : words.length ? [...words, ...FILLED_TAIL] : [];
        return [{ via: 'xargs', inner: innerCommand(filled, cmd), tail: replace === null }];
    }
    if (cmd.name === 'git') return submoduleForeach(cmd);
    if (cmd.name !== 'find') return [];
    const runs: Array<{ via: string; inner: ResolvedCommand | null }> = [];
    for (let i = 0; i < cmd.args.length; i++) {
        if (!['-exec', '-execdir', '-ok', '-okdir'].includes(cmd.args[i])) continue;
        // The command runs up to its `;`, or a `+` right after `{}`; what follows is find's own expression.
        const end = cmd.args.findIndex((a, j) => j > i && (a === ';' || (a === '+' && cmd.args[j - 1] === '{}')));
        const inner = innerCommand(cmd.args.slice(i + 1, end < 0 ? undefined : end), cmd);
        if (inner && cmd.args[i].endsWith('dir') && inner.chdir === undefined) inner.chdir = EACH_MATCH_DIR;
        runs.push({ via: `find ${cmd.args[i]}`, inner });
        if (end > i) i = end;
    }
    return runs;
}

/** `git submodule [opts] foreach [--recursive] CMD…`: git joins CMD's words and runs them with `sh -c` in each submodule. */
function submoduleForeach(cmd: ResolvedCommand): Array<{ via: string; inner: ResolvedCommand | null }> {
    let i = gitSubcommandIndex(cmd.args);
    if (cmd.args[i] !== 'submodule') return [];
    for (i++; cmd.args[i]?.startsWith('-'); i++);
    if (cmd.args[i] !== 'foreach') return [];
    for (i++; ['--recursive', '--quiet', '-q', '--'].includes(cmd.args[i]); i++);
    const words = cmd.args.slice(i);
    if (!words.length) return [];
    return [{ via: 'git submodule foreach', inner: { name: 'sh', args: ['-c', words.join(' ')], raw: cmd.raw, env: [], chdir: EACH_SUBMODULE_DIR, hasInputRedirect: false } }];
}

/** The string xargs replaces with its input (`-I R`, `-J R`, `-i`/`--replace` → `{}`), or null when it appends instead. */
function xargsReplaceString(args: string[]): string | null {
    for (let i = 0; i < args.length && args[i].startsWith('-') && args[i] !== '--'; i += optionWords(args[i], 'adEIJLnPRsS', XARGS_LONG_VALUE_OPTIONS, XARGS_LONG_FLAGS)) {
        const a = args[i];
        if (a.startsWith('--')) {
            const [name, value] = [a.slice(2).split('=')[0], a.includes('=') ? a.slice(a.indexOf('=') + 1) : ''];
            if (name.length > 1 && 'replace'.startsWith(name)) return value || '{}';
            continue;
        }
        // In a cluster, a letter that takes a value swallows the rest: `-dI` sets the delimiter to `I`.
        for (let k = 1; k < a.length; k++) {
            if (a[k] === 'i') return a.slice(k + 1) || '{}';
            if (a[k] === 'I' || a[k] === 'J') return a.slice(k + 1) || args[i + 1] || '{}';
            if ('adELnPRsS'.includes(a[k])) break;
        }
    }
    return null;
}

// Words that make a command need approval under checkGatedCommand's rules: an operation (with the words that lead to
// it), a modifier, or text a client runs. A word filled in at run time is tried as each, so a rule whose words are
// missing here lets xargs input or a find match choose them unseen; runtime-words.test.ts holds every rule to it.
const RUNTIME_PROBES: string[][] = [
    ['push', '--force'], ['clean'], ['--no-dry-run'], ['--force'], ['-f'], ['--delete'], ['-d'], ['--mirror'], ['--prune'],
    ['+main'], [':main'],
    ['destroy'], ['delete'], ['apply', '-auto-approve'], ['-auto-approve'], ['uninstall'], ['remove'], ['drain'], ['cordon'],
    ['rm'], ['rb'], ['rmi'], ['system', 'prune'], ['volume', 'rm'], ['s3', 'rm'], ['ec2', 'terminate-instances'],
    ['repo', 'delete'], ['db', 'reset'], ['pg:reset'], ['sites:delete'], ['projects:delete'], ['firestore:delete'],
    ['hosting:disable'], ['run', '--full-refresh'], ['--full-refresh'], ['if=/dev/zero'], ['FLUSHALL'], ['db.x.drop()'],
    ['x; DROP TABLE x'], ['-c', 'x; DROP TABLE x'], ['sql', '-q', 'DROP TABLE x'],
    ...[...new Set(Object.values(PLATFORM_DESTRUCTIVE).flatMap(verbs => [...verbs]))].map(verb => [verb]),
];
// A filled word may complete an operation another word starts (`system {}`), so every run of words in a probe is one.
const RUNTIME_FILLS = [...new Map(RUNTIME_PROBES.flatMap(probe => probe.flatMap((_, i) => probe.slice(i).map((__, j) => probe.slice(i, i + j + 1))))
    .map(words => [words.join('\0'), words])).values()];
const RUNTIME_PROBE_WORDS = [...new Set(RUNTIME_PROBES.flat())];

/** Each way to fill `args`' FILLED words from RUNTIME_PROBES, with the words it put there. */
function* runtimeFills(args: string[]): Generator<{ args: string[]; words: string }> {
    for (let i = 0; i < args.length; i++) {
        if (args[i] === FILLED) {
            for (const fill of RUNTIME_FILLS) yield { args: [...args.slice(0, i), ...fill, ...args.slice(i + 1)], words: fill.join(' ') };
        } else if (args[i].includes(FILLED)) {
            // Part of a word (`FLUSH{}`, `select … {}`) can complete a probe word around the written text, or hold one.
            const [before, after] = [args[i].slice(0, args[i].indexOf(FILLED)), args[i].slice(args[i].lastIndexOf(FILLED) + FILLED.length)];
            for (const word of RUNTIME_PROBE_WORDS) {
                const around = word.length >= before.length + after.length && word.toLowerCase().startsWith(before.toLowerCase())
                    && word.toLowerCase().endsWith(after.toLowerCase());
                for (const filled of around ? [word, args[i].split(FILLED).join(word)] : [args[i].split(FILLED).join(word)]) {
                    yield { args: [...args.slice(0, i), filled, ...args.slice(i + 1)], words: filled };
                }
            }
        }
    }
}

const holdsFilled = (cmd: ResolvedCommand): boolean =>
    cmd.chdir === EACH_MATCH_DIR || [cmd.name, ...cmd.args, ...(cmd.env ?? []), cmd.chdir ?? ''].some(w => w.includes(FILLED));

/** A shell without `-c`: its options and the operand naming the script file it runs, not that script's arguments. */
function shellFileWords(shell: ResolvedCommand): string[] {
    const spec = SHELL_VALUE_OPTIONS[shell.name] ?? SHELL_VALUE_OPTIONS.bash;
    for (let i = 0; i < shell.args.length; i++) {
        const a = shell.args[i];
        if (a === '--') return shell.args.slice(0, i + 2);
        if (!/^[-+]/.test(a)) return shell.args.slice(0, i + 1);
        if (a.startsWith('--') ? spec.long.has(a) : spec.short.includes(a[a.length - 1])) i++;
    }
    return shell.args;
}

/**
 * What a word filled in at run time decides in `step` that makes what it runs unknowable, or null: the command it
 * runs (its name, its environment, or find's expression), the script a shell runs, or arguments that make it need
 * approval when it doesn't otherwise.
 */
function runtimeReach(step: ResolvedCommand): string | null {
    if (!holdsFilled(step)) return null;
    if (step.name.includes(FILLED) || step.env?.some(e => e.includes(FILLED))) return 'takes the command it runs';
    if (step.name === 'find' && step.args.some(a => a.includes(FILLED))) return "takes find's expression";
    if (SHELLS.has(step.name) && !shellScript(step.name, step.args) && shellFileWords(step).some(a => a.includes(FILLED))) {
        return `supplies ${step.name}'s script`;
    }
    if (checkGatedCommand(step)) return null;
    for (const fill of runtimeFills(step.args)) {
        if (checkGatedCommand({ ...step, args: fill.args })) return `can fill in "${fill.words}" for ${step.name}`;
    }
    return null;
}

// xargs or find nested inside each other past this depth are not followed; no real command nests them twice.
const EXEC_NESTING_MAX = 4;

/** Every command xargs or find -exec runs that needs approval, with why; each gets its own exemption check. */
// `runtime`: xargs input or a find match decides the step or where it acts, so no static exemption can apply to it.
// `moves`: the directory changes the script makes before the step, which decide where it runs.
type InnerGate = { step: ResolvedCommand; reason: string; runtime?: boolean; moves?: ResolvedCommand[] };

function innerGatedSteps(cmd: ResolvedCommand, depth = 0): InnerGate[] {
    const gated: InnerGate[] = [];
    for (const { via, inner, tail } of execRuns(cmd)) {
        const steps = innerSteps(inner, tail);
        if (steps === RUNS_VARIABLE) continue;
        const moves: ResolvedCommand[] = [];
        for (const step of steps) {
            if (DIRECTORY_CHANGERS.has(step.name)) {
                moves.push(step);
                continue;
            }
            const at = moves.length ? [...moves] : undefined;
            const reach = via === 'git submodule foreach' ? null : runtimeReach(step);
            if (reach) {
                gated.push({ step: { ...step, pos: undefined }, reason: `${via} ${reach} from ${via === 'xargs' ? 'its input' : 'the files it matches'}, so what it runs can't be checked. Write it in the command.`, runtime: true });
                continue;
            }
            if (step.name === 'xargs' || step.name === 'find') {
                if (depth >= EXEC_NESTING_MAX) {
                    gated.push({ step: { ...step, pos: undefined }, reason: `${via} nests xargs or find too deeply for the guard to follow. Run the inner command directly.` });
                    continue;
                }
                gated.push(...innerGatedSteps(step, depth + 1).map(g => ({ ...g, reason: `${via} runs ${g.reason}`, moves: [...moves, ...(g.moves ?? [])] })));
            }
            const reason = checkGatedCommand(step);
            // The step's offset, if any, is into the inner script, not the command line the card reads from.
            if (reason) gated.push({ step: { ...step, pos: undefined }, reason: `${via} runs a command that needs approval. ${reason}`, moves: at, runtime: holdsFilled(step) || at?.some(holdsFilled) });
        }
    }
    return gated;
}

const RUNS_VARIABLE = 'Its shell script takes the command to run from a variable, so what it runs cannot be checked. Name the command in the script.';

/**
 * `words` with the script's positional parameters filled in from the words written after the script, or null when
 * none is used. Bourne shells number them from `$0`; fish passes every one as `$argv`.
 */
function expandPositional(shell: string, words: string[], positional: string[], appended: boolean): string[] | null {
    const fish = shell === 'fish';
    const all = fish ? positional : positional.slice(1);
    const one = fish ? /\$argv\[(\d+)\]/g : /\$(\d)|\$\{(\d+)\}/g;
    let used = false;
    const out = words.flatMap(word => {
        if (fish ? /^\$argv$/.test(word) : /^\$\{?[@*]\}?$/.test(word)) {
            used = true;
            return all;
        }
        return [word.replace(one, (_m, a: string | undefined, b: string | undefined) => {
            used = true;
            const n = Number(a ?? b);
            return positional[fish ? n - 1 : n] ?? (appended ? FILLED : '');
        })];
    });
    return used ? out : null;
}

/** Options that take a value in each shell's own argument parsing; bash's `-C` (noclobber) takes none, fish's does. */
const SHELL_VALUE_OPTIONS: Record<string, { short: string; long: Set<string>; flags?: Set<string> }> = {
    bash: { short: 'oO', long: new Set(['--rcfile', '--init-file']) },
    fish: {
        short: 'CdDofp',
        long: new Set(['--init-command', '--debug', '--debug-output', '--debug-stack-frames', '--features', '--profile',
            '--profile-startup']),
        flags: new Set(['--interactive', '--login', '--no-config', '--no-execute', '--print-rusage-self', '--private',
            '--help', '--version']),
    },
};

/**
 * A shell's inline script (`-c SCRIPT`, fish's `--command=SCRIPT`) and the index where its positional words start,
 * or null. Only the shell's leading options count: a script file operand (or `--`) ends them, and what follows is
 * the script's arguments (`bash deploy.sh -xc v` runs deploy.sh). A Bourne shell's `-c` is a flag, and the script is
 * its first operand after any further options (`bash -c -x SCRIPT`); fish's `-c` takes the next word.
 */
export function shellScript(shell: string, args: string[]): { text: string; rest: number } | null {
    const values = SHELL_VALUE_OPTIONS[shell] ?? { short: 'o', long: new Set<string>() };
    const atScript = (i: number) => {
        const at = args[i] === '--' ? i + 1 : i;
        return at < args.length ? { text: args[at], rest: at + 1 } : null;
    };
    let inline = false;
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a === '--' || !/^[-+]/.test(a)) return inline ? atScript(i) : null;
        if (a.startsWith('--')) {
            const [name, value] = a.split(/=(.*)/s);
            if (shell === 'fish' && name.length > 2 && '--command'.startsWith(name)) {
                return value !== undefined ? { text: value, rest: i + 1 } : atScript(i + 1);
            }
            i += optionWords(a, '', values.long, values.flags) - 1;
            continue;
        }
        // fish reads a cluster getopt-style: a value option takes the rest of it, or the next word. A Bourne shell
        // takes each value option's value from the next unread word and goes on reading the cluster (`bash -Oc x S`).
        const option = i;
        for (let k = 1; k < a.length; k++) {
            if (a[k] === 'c' && a[0] === '-') {
                if (shell === 'fish') return k < a.length - 1 ? { text: a.slice(k + 1), rest: i + 1 } : atScript(i + 1);
                inline = true;
                continue;
            }
            if (!values.short.includes(a[k])) continue;
            if (shell !== 'fish') i++;
            else {
                if (k === a.length - 1) i = option + 1;
                break;
            }
        }
    }
    return null;
}

/** The command `words` (a command word and its arguments, as xargs or find -exec take them) runs, past any wrapper. */
function innerCommand(words: string[], outer: ResolvedCommand): ResolvedCommand | null {
    const [first, ...rest] = words;
    if (first === undefined) return null;
    const { name, args, env, chdir } = stripWrappers(first, rest);
    return { name, args, raw: outer.raw, env, ...(chdir !== undefined ? { chdir } : {}), hasInputRedirect: false };
}

/**
 * Parse command string into resolved commands. Falls back to regex splitting if parser fails. A line parseShell can't
 * read as bash will gets unbash's own reading as well as the regex split, so the hard blocks that name a command
 * on it keep their own reason rather than the generic unreadable-line one.
 */
export function extractCommands(command: string): ResolvedCommand[] {
    try {
        return commandsOf(parseShell(command), command);
    } catch (e) {
        if (!(e instanceof ShellParseError)) return fallbackExtract(command);
        let unchecked: ResolvedCommand[] = [];
        try {
            unchecked = commandsOf(parse(command), command);
        } catch {
            // unbash can't parse it either; the regex split below is all there is.
        }
        return [...unchecked, ...fallbackExtract(command)];
    }
}

function commandsOf(ast: any, command: string): ResolvedCommand[] {
    const nodes = walkCommandNodes(ast);
    const nested: Array<[any, ResolvedCommand]> = [];
    const commands = nodes.map(node => {
        if (node.__resolved) return node.__resolved as ResolvedCommand;
        const cmd = resolveCommand(node);
        if (cmd && NESTED_COMMAND_NODES.has(node)) nested.push([node, cmd]);
        return cmd;
    }).filter((c): c is ResolvedCommand => c !== null);
    traceSubstitutionPipes(nested, command);
    const script = scriptContextOf(ast, commands, command);
    for (const cmd of commands) cmd.script = script;
    return commands;
}

const TEXT_EMITTERS = new Set(['echo', 'printf', 'cat', 'tee']);

/** The files cat reads, a relative one resolved against the directory an `env -C` wrapper ran it in. */
function catOperands(cmd: ResolvedCommand): string[] {
    const files = cmd.args.filter(a => !a.startsWith('-'));
    return cmd.chdir ? files.map(f => (f.startsWith('/') ? f : join(cmd.chdir!, f))) : files;
}

function samePath(path: string): string {
    return path.replace(/^(?:\.\/)+/, '');
}

/** An emitter's words or heredoc input hold a variable or command substitution, so its text may change when expanded. */
function holdsVariable(cmd: ResolvedCommand): boolean {
    return [...cmd.args, ...(cmd.stdinExpanded ?? []).map(w => w.plain)].some(t => /[$`]/.test(t));
}

/** The text an emitter writes to stdout or its files (not counting what a pipe feeds it). */
function emittedText(cmd: ResolvedCommand): string[] {
    const operands = cmd.args.filter(a => !a.startsWith('-'));
    if (cmd.name === 'cat' || cmd.name === 'tee') return [...(cmd.stdinTexts ?? [])];
    if (cmd.name === 'echo') {
        const text = operands.join(' ');
        return [...(cmd.stdinTexts ?? []), text, ...(text.includes('\\') ? [renderEscapes(text)] : [])];
    }
    if (cmd.name !== 'printf') return [...(cmd.stdinTexts ?? []), operands.join(' ')];
    return [...(cmd.stdinTexts ?? []), operands.join(' '), ...operands, renderPrintf(operands)];
}

const PRINTF_DIRECTIVE = /%(?:%|[-+ #0]*(?:\d+|\*)?(?:\.(?:\d+|\*))?[sbqdiouxXcfFeEgGaA])/g;

/** printf's output for a format and its arguments, reusing the format until the arguments run out. */
function renderPrintf(operands: string[]): string {
    const [format = '', ...values] = operands;
    let out = '';
    let next = 0;
    do {
        out += format.replace(PRINTF_DIRECTIVE, d => (d === '%%' ? '%' : values[next++] ?? ''));
    } while (next > 0 && next < values.length && out.length < 100_000);
    return renderEscapes(out);
}

/** The newline and tab escapes `echo -e` and printf render; scanned beside the raw text, so it can only add a match. */
function renderEscapes(text: string): string {
    return text.replace(/\\n/g, '\n').replace(/\\t/g, '\t');
}

/**
 * What the whole command line shows about where text and directories go: the
 * text each file is written with, what each pipeline stage feeds the next,
 * each command's place in its &&/|| chain, and the cds.
 */
function scriptContextOf(ast: any, commands: ResolvedCommand[], command: string): ScriptContext {
    const byPos = new Map<number, ResolvedCommand>();
    for (const c of commands) if (c.pos !== undefined) byPos.set(c.pos, c);
    const pipedInto = new Map<number, PipedInput>();
    const links = new Map<number, ChainLink>();
    let chains = 0;

    const pipeline = (node: any): any[] => (node?.type === 'Pipeline' ? node.commands || [] : [node]);
    const stageCommands = (node: any): ResolvedCommand[] =>
        walkCommandNodes(node).map(n => (typeof n.pos === 'number' ? byPos.get(n.pos) : undefined)).filter((c): c is ResolvedCommand => !!c);
    const visitLink = (node: any, chain: number, index: number, operators: string[], depth: number) => {
        const stages = pipeline(node?.type === 'Statement' ? node.command : node);
        stages.forEach((stage: any, i: number) => {
            if (stage?.type === 'Command' && typeof stage.pos === 'number') {
                links.set(stage.pos, { chain, index, operators });
            } else {
                visitCompound(stage, depth);
            }
            if (i === 0) return;
            const input: PipedInput = { texts: [], catFiles: [], from: [], textFrom: [], emitters: [] };
            for (const up of stageCommands(stages[i - 1])) {
                if (!TEXT_EMITTERS.has(up.name) || up.stdoutFiles?.length) continue;
                const fed = up.pos === undefined ? undefined : pipedInto.get(up.pos);
                input.texts.push(...emittedText(up));
                if (holdsVariable(up)) input.emitters!.push(up);
                if (up.name === 'cat') input.catFiles.push(...catOperands(up));
                if (fed) (up.name === 'cat' || up.name === 'tee' ? input.from! : input.textFrom!).push(fed);
            }
            for (const down of stageCommands(stage)) {
                if (down.pos === undefined) continue;
                const inner = pipedInto.get(down.pos);
                pipedInto.set(down.pos, inner ? { texts: [], catFiles: [], from: [inner, input] } : input);
            }
        });
    };
    const visit = (node: any, depth: number) => {
        if (!node) return;
        if (node.type === 'Statement') return visit(node.command, depth);
        if (node.type === 'Script' || node.type === 'CompoundList') return (node.commands || []).forEach((c: any) => visit(c, depth));
        const chain = chains++;
        if (node.type === 'AndOr') {
            (node.commands || []).forEach((link: any, i: number) => visitLink(link, chain, i, node.operators || [], depth));
        } else {
            visitLink(node, chain, 0, [], depth);
        }
    };
    // Lists inside if/while/for/case bodies, groups, subshells and functions: their pipelines feed text like top-level ones.
    // Past PIPE_NESTING_MAX levels the pipes inside are left untraced: each level re-walks its subtree, and no real
    // command nests anywhere near that deep.
    const visitCompound = (node: any, depth: number) => {
        if (!node || node.type === 'Command' || depth >= PIPE_NESTING_MAX) return;
        for (const child of [node.clause, node.then, node.else, node.body, node.command]) visit(child, depth + 1);
        for (const item of node.items || []) visit(item?.body, depth + 1);
    };
    visit(ast, 0);

    const writes: FileWrite[] = [];
    for (const cmd of commands) {
        if (!TEXT_EMITTERS.has(cmd.name)) continue;
        const operands = cmd.name === 'cat' ? catOperands(cmd) : cmd.args.filter(a => !a.startsWith('-'));
        const fed = (cmd.name === 'tee' || cmd.name === 'cat') && cmd.pos !== undefined ? pipedInto.get(cmd.pos) : undefined;
        const input: PipedInput = {
            texts: emittedText(cmd),
            ...(holdsVariable(cmd) ? { emitters: [cmd] } : {}),
            catFiles: cmd.name === 'cat' ? operands : [],
            ...(fed ? { from: [fed] } : {}),
        };
        for (const target of [...(cmd.stdoutFiles ?? []), ...(cmd.name === 'tee' ? operands : [])]) {
            writes.push({ writer: cmd, target, input });
        }
    }
    const cds = commands
        .filter(c => c.name === 'cd' || c.name === 'pushd' || c.name === 'popd')
        .map(c => ({
            pos: c.pos ?? -1,
            // `pushd DIR` changes directory like `cd DIR`; `pushd +N`/`-N` rotates the stack to a directory unknown here.
            target: (c.name === 'cd' || c.name === 'pushd') && c.args.length === 1 && !/^(?:-|[+-]\d+)$/.test(c.args[0]) ? c.args[0] : undefined,
        }));
    return { writes, pipedInto, cds, links, command };
}

// A SQL client's own ways of writing a file: psql's \o, \w, \g, \copy, \lo_export and a \! shell command; snow's GET; COPY … TO and INTO OUTFILE,
// which a database on this host writes where the client can read; sqlite3's .output, .once, .save and .backup.
const SQL_CLIENT_FILE_WRITE = /\\(?:(?:o|out|w|write|g|gx|copy|lo_export)\b|!)|\bGET\b|\bCOPY\b[\s\S]*?\bTO\b|\bINTO\s+(?:OUT|DUMP)FILE\b|^\s*\.(?:output|once|save|backup)\b/im;
const SQL_CLIENT_OUTPUT_OPTION = /^(?:-o|--output|-L|--log-file|--tee)(?:=|$)/;

/** True when a SQL client's options name a file it writes its output or a log to. */
function writesOwnOutput(cmd: ResolvedCommand): boolean {
    return cmd.args.some(a => SQL_CLIENT_OUTPUT_OPTION.test(a) || cmd.name === 'psql' && /^-[a-zA-Z]*[oL]/.test(a));
}

/** Regex-based fallback for when the AST parser fails */
export function fallbackExtract(command: string): ResolvedCommand[] {
    return command
        .split(/(?:;|&&|\|\||\||\n)\s*/)
        .map(s => s.trim())
        .filter(Boolean)
        .map(seg => {
            const env: string[] = [];
            let rest = seg;
            let assignment: RegExpMatchArray | null;
            while ((assignment = rest.match(/^(\w+=\S*)\s+/))) {
                env.push(assignment[1]);
                rest = rest.slice(assignment[0].length);
            }
            const normalized = normalizeCommandFallback(rest);
            const parts = normalized.split(/\s+/);
            return {
                name: commandName(parts[0] || ''),
                args: parts.slice(1),
                raw: seg,
                env,
                hasInputRedirect: /<<<?\s/.test(seg),
            };
        });
}

/** Fallback wrapper stripping (regex-based, used only when parser fails) */
export function normalizeCommandFallback(s: string): string {
    let prev = '';
    let curr = s;
    while (prev !== curr) {
        prev = curr;
        curr = curr
            .replace(/^sudo\s+/, '')
            .replace(/^env(?:\s+(?:-\S+|\w+=\S+))*\s+/, '')
            .replace(/^(?:command|builtin)\s+/, '')
            .replace(/^\/(?:usr\/(?:local\/)?)?bin\//, '')
            .replace(/^(?:nohup|time)\s+/, '')
            .replace(/^nice(?:\s+-n\s+\S+)?\s+/, '')
            .replace(/^(?:timeout|gtimeout)\s+\S+\s+/, '');
    }
    return curr;
}

// ── Provenance for rm of mktemp variables ───────────────────────────────────

const EXACT_VARIABLE_REFERENCE = /^\$(?:([A-Za-z_][A-Za-z0-9_]*)|\{([A-Za-z_][A-Za-z0-9_]*)\})$/;
const SAFE_MKTEMP_SENTINEL = '/tmp/.bootstrap-mktemp-provenance';

/** Collect Assignment nodes without assuming a particular unbash container shape. */
function collectAssignmentNodes(node: unknown, out: any[], seen = new WeakSet<object>()): void {
    if (!node || typeof node !== 'object') return;
    if (seen.has(node as object)) return;
    seen.add(node as object);

    if (Array.isArray(node)) {
        for (const child of node) collectAssignmentNodes(child, out, seen);
        return;
    }

    const record = node as Record<string, unknown>;
    if (record.type === 'Assignment') out.push(node);
    for (const child of Object.values(record)) {
        collectAssignmentNodes(child, out, seen);
    }
}

/** True only for the narrow, known-safe assignment form: name=$(mktemp). */
function isZeroArgumentMktempAssignment(assignment: any): boolean {
    let parts = assignment?.value?.parts;
    if (!Array.isArray(parts) || parts.length !== 1) return false;

    // Quoting the substitution does not change its provenance.
    if (parts[0]?.type === 'DoubleQuoted') parts = parts[0].parts;
    if (!Array.isArray(parts) || parts.length !== 1) return false;

    const expansion = parts[0];
    if (expansion?.type !== 'CommandExpansion') return false;

    const nodes = walkCommandNodes(expansion.script);
    if (nodes.length !== 1 || (nodes[0].prefix || []).length !== 0) return false;
    const resolved = resolveCommand(nodes[0]);
    return resolved?.name === 'mktemp' && resolved.args.length === 0;
}

/**
 * Shell builtins can mutate a variable without producing an Assignment AST
 * node. Fail closed for the common mutation forms and for sourced scripts,
 * whose effects cannot be known statically.
 */
function hasPotentialVariableMutation(fragment: string, variable: string): boolean {
    const escaped = variable.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return [
        new RegExp(`\\b(?:export|declare|typeset|local|readonly)\\b[^\\n;]*\\b${escaped}\\s*=`),
        new RegExp(`\\b(?:unset|read|readarray|mapfile)\\b[^\\n;]*\\b${escaped}\\b`),
        new RegExp(`\\bprintf\\b[^\\n;]*\\s-v\\s+${escaped}\\b`),
        new RegExp(`\\bfor\\s+${escaped}\\b`),
        new RegExp(`\\$\\{${escaped}(?::?=)`),
        /(?:^|[;&|]\s*|\n\s*)(?:source|\.)\s+/m,
    ].some(rx => rx.test(fragment));
}

/**
 * Map each top-level rm command's source offset to variables that are proven
 * to still contain a path created by zero-argument mktemp.
 *
 * This is deliberately narrow. The assignment and rm must both be top-level,
 * the assignment must be exactly `name=$(mktemp)` (optionally quoted), the
 * default mktemp directory must be ephemeral, and no intervening mutation may
 * occur. Anything the static analysis cannot prove remains blocked.
 */
function findEphemeralMktempVariables(command: string): Map<number, Set<string>> {
    const result = new Map<number, Set<string>>();

    try {
        const ast: any = parseShell(command);
        const tmpDir = process.env.TMPDIR || '/tmp';
        if (!isSafePath(tmpDir)) return result;

        const topLevelCommands = (ast.commands || [])
            .map((entry: any) => entry?.type === 'Statement' ? entry.command : entry)
            .filter((node: any) => node?.type === 'Command');

        const safeAssignments = new Set<any>();
        for (const node of topLevelCommands) {
            const prefix = node.prefix || [];
            if (!node.name && prefix.length === 1 &&
                (node.suffix || []).length === 0 && (node.redirects || []).length === 0 &&
                prefix[0]?.type === 'Assignment' && isZeroArgumentMktempAssignment(prefix[0])) {
                safeAssignments.add(prefix[0]);
            }
        }

        const assignments: any[] = [];
        collectAssignmentNodes(ast, assignments);
        assignments.sort((a, b) => (a.pos ?? -1) - (b.pos ?? -1));

        for (const node of topLevelCommands) {
            const resolved = resolveCommand(node);
            if (resolved?.name !== 'rm' || typeof resolved.pos !== 'number') continue;

            const proven = new Set<string>();
            for (const arg of resolved.args) {
                const match = arg.match(EXACT_VARIABLE_REFERENCE);
                const variable = match?.[1] || match?.[2];
                if (!variable) continue;

                const latest = assignments
                    .filter(a => a.name === variable && typeof a.pos === 'number' && a.pos < resolved.pos!)
                    .at(-1);
                if (!latest || !safeAssignments.has(latest)) continue;

                // A command-local TMPDIR override changes where zero-argument
                // mktemp writes; fail closed rather than trying to execute the
                // shell's environment semantics statically.
                if (/\bTMPDIR\s*=/.test(command.slice(0, latest.pos))) continue;

                const between = command.slice(latest.end ?? latest.pos, resolved.pos);
                if (hasPotentialVariableMutation(between, variable)) continue;
                proven.add(variable);
            }

            if (proven.size > 0) result.set(resolved.pos, proven);
        }
    } catch {
        // Parser failure already falls back conservatively for command
        // extraction; variable provenance must fail closed as well.
    }

    return result;
}

function resolveEphemeralRmArgs(cmd: ResolvedCommand, proven: ReadonlySet<string>): ResolvedCommand {
    if (proven.size === 0) return cmd;
    return {
        ...cmd,
        args: cmd.args.map(arg => {
            const match = arg.match(EXACT_VARIABLE_REFERENCE);
            const variable = match?.[1] || match?.[2];
            return variable && proven.has(variable) ? SAFE_MKTEMP_SENTINEL : arg;
        }),
    };
}

// ── Lab-scoped exemption ─────────────────────────────────────────────────────
// In a Lab session — a wiring whose channel instructions profile is `lab`, which
// the host projects into the container as NANOCLAW_INSTRUCTIONS_PROFILE
// (nanoclaw-v2 src/container-runner.ts) — a destructive action aimed at a LAB
// TARGET must neither hold for approval nor be denied. A lab exists to be torn
// down and rebuilt; an approval card on every `DROP SCHEMA` defeats the point.
//
// TWO predicates must BOTH hold. The session predicate alone is never enough:
// being in a lab room does not exempt a command aimed at production. The
// target predicate reads the RESOLVED command (post wrapper-stripping) and fails
// CLOSED — an unrecognized family, or a target constructed at runtime
// (`psql "$URL"`, a variable-built repo path), is NOT a lab target and stays
// gated.
//
// Deliberately NOT exempted:
//   • tier-1 hard blocks (eval, shell -c, find -exec rm, xargs rm, shred, dd,
//     truncate). A `sh -c` wrapper hides the real target from the target
//     predicate, so exempting tier 1 would dismantle the target matching itself.
//   • `snow sql` — Snowflake has no lab tenant, so every Snowflake statement
//     stays gated even in a lab session.
//   • non-LAB repos, non-`lab-` Render services, and prod/dev databases, in the
//     lab room or anywhere else.

/** The instructions-profile name that marks a Lab session. */
export const LAB_INSTRUCTIONS_PROFILE = 'lab';

// WHICH GitHub org owns lab repos, and which non-`LAB-*` repos are
// lab-writable, is deployment data, not source. It lives in an untracked
// `lab-scope.local.json` — `{"org": "<github-org>", "extraRepos": ["<REPO>"]}` —
// read from BOOTSTRAP_LAB_SCOPE_FILE when that is set (and then ONLY from there),
// else from the plugin repo root this module sits under (a runtime running the
// repo in place), else from the NanoClaw container mount of that repo (a runtime
// running a cached copy of the plugin, which has no repo root above it).
//
// No readable, valid file means no lab org: no repo reference is then a lab
// target, and every such command stays gated. A missing or malformed file can
// only make the guard stricter, never looser.
export interface LabScope {
    org: string;
    extraRepos: string[];
}

export const LAB_SCOPE_FILE_ENV = 'BOOTSTRAP_LAB_SCOPE_FILE';
const LAB_SCOPE_FILE = 'lab-scope.local.json';
const GITHUB_OWNER_RE = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$/;
const GITHUB_REPO_RE = /^[A-Za-z0-9._-]{1,100}$/;
// `https://[user[:token]@]github.com[:port]/`, `ssh://git@github.com/`,
// `git://github.com/`, scp-style `git@github.com:`, and GitHub's SSH-over-443
// host `ssh.github.com`.
const GITHUB_REMOTE_PREFIX =
    '(?:(?:https?|ssh|git|git\\+ssh):\\/\\/(?:[^\\s/@]+@)?(?:ssh\\.)?github\\.com(?::\\d+)?\\/|[A-Za-z0-9_.-]+@(?:ssh\\.)?github\\.com:)';

/** Parse a lab-scope file's text. Null when anything about it is unusable. */
export function parseLabScope(text: string): LabScope | null {
    let raw: unknown;
    try {
        raw = JSON.parse(text);
    } catch {
        return null;
    }
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
    const { org, extraRepos = [] } = raw as { org?: unknown; extraRepos?: unknown };
    if (typeof org !== 'string' || !GITHUB_OWNER_RE.test(org)) return null;
    if (!Array.isArray(extraRepos)) return null;
    if (!extraRepos.every((r) => typeof r === 'string' && GITHUB_REPO_RE.test(r))) return null;
    return { org, extraRepos: extraRepos as string[] };
}

/**
 * Where an untracked deployment file lives: the path in `envVar` when that is set
 * (and then only there), else the plugin repo root above this module, else the
 * NanoClaw container mount of that repo.
 */
function deploymentFilePath(fileName: string, envVar: string): string | null {
    const explicit = process.env[envVar];
    if (explicit !== undefined) return explicit || null;
    let repoRoot: string | null = null;
    try {
        repoRoot = fileURLToPath(new URL(`../../../../${fileName}`, import.meta.url));
    } catch {
        repoRoot = null;
    }
    for (const candidate of [repoRoot, `/workspace/plugins/bootstrap/${fileName}`]) {
        if (candidate && existsSync(candidate)) return candidate;
    }
    return null;
}

function labScopePath(): string | null {
    return deploymentFilePath(LAB_SCOPE_FILE, LAB_SCOPE_FILE_ENV);
}

function escapeRegexLiteral(value: string): string {
    return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

interface CompiledLabScope {
    /** A whole value naming `<org>/<lab repo>` on GitHub; null without a lab org. */
    repoRef: RegExp | null;
    /** `worktrees/<lab repo>` path segment. */
    worktreeSegment: RegExp;
    /** Exactly `<org>/LAB-*` — the only repos `gh repo delete` may skip approval for. */
    ghDeletable: RegExp | null;
}

let labScopeCache: { key: string; compiled: CompiledLabScope } | null = null;

/**
 * Lab scope in force right now. Re-read on every call and keyed on the file's
 * CONTENT, never frozen at module scope and never keyed on metadata: a narrowed
 * file must take effect even when its size and mtime happen to match.
 */
function currentLabScope(): CompiledLabScope {
    const file = labScopePath();
    let key = 'none';
    let text: string | null = null;
    if (file) {
        try {
            text = readFileSync(file, 'utf-8');
            key = `${file}\0${text}`;
        } catch {
            key = `${file}\0unreadable`;
            text = null;
        }
    }
    if (labScopeCache?.key === key) return labScopeCache.compiled;

    const scope = text === null ? null : parseLabScope(text);
    // The OWNER half is pinned to that lab org inside the pattern itself, not only
    // in a follow-up comparison, so `other-org/LAB-APP` cannot match at all.
    //
    // Every pattern is case-INSENSITIVE. GitHub repo names are case-insensitive
    // and lab repos get renamed between casings, so agents still hold older URLs
    // that redirect to the current names. Refusing those spellings would gate the
    // exact commands the exemption exists to free.
    const extra = scope ? scope.extraRepos.map((r) => `|${escapeRegexLiteral(r)}`).join('') : '';
    const repoName = `(?:LAB-[A-Z0-9-]+${extra})`;
    const org = scope ? escapeRegexLiteral(scope.org) : null;
    const compiled: CompiledLabScope = {
        repoRef: org
            ? new RegExp(`^(?:${GITHUB_REMOTE_PREFIX})?(${org})\\/(${repoName})(?:\\.git)?\\/?$`, 'i')
            : null,
        worktreeSegment: new RegExp(`(?:^|\\/)worktrees\\/${repoName}(?:\\/|$)`, 'i'),
        ghDeletable: org ? new RegExp(`^(${org})\\/(LAB-[A-Z0-9-]+)$`, 'i') : null,
    };
    labScopeCache = { key, compiled };
    return compiled;
}

/**
 * PREDICATE 1 — lab session.
 *
 * Read at call time, never cached at module scope: the core is imported once per
 * adapter process and the tests flip this env between cases.
 */
export function isLabSession(): boolean {
    return process.env.NANOCLAW_INSTRUCTIONS_PROFILE === LAB_INSTRUCTIONS_PROFILE;
}

/** Name of a lab repo `value` references (`<org>/<repo>`), or null. Accepts a
 *  bare `org/repo` or a github.com URL (https, ssh, git, scp-style) whose path
 *  is exactly that repo — the same path on any other host is not a lab repo.
 *  Always null without a lab org. */
export function labRepoRefName(value: string): string | null {
    if (!value) return null;
    const { repoRef } = currentLabScope();
    const m = repoRef?.exec(value);
    return m ? `${m[1]}/${m[2]}` : null;
}

/** True when `value` references a LAB-* or configured extra repo under that lab org. */
export function isLabRepoRef(value: string): boolean {
    return labRepoRefName(value) !== null;
}

// A worktree checkout dir is named for its repo (`<worktrees>/APP`), and the host
// bind-mounts the same directory twice — at /workspace/worktrees and at its own
// host path (nanoclaw-v2 src/container-runner.ts). Matching the `worktrees/<repo>`
// SEGMENT rather than a /workspace-anchored prefix covers both mounts with one
// pattern. Case-insensitive for the same reason as the repo-reference pattern: a
// clone taken before a rename keeps its old casing on disk.

/**
 * True when `p` sits inside a LAB-* or configured extra repo worktree checkout,
 * under either the /workspace mount or the host-path alias mount.
 *
 * Tested against the NORMALIZED path only. Matching the raw string would let
 * `/workspace/worktrees/LAB-APP/../APP` read as a lab path and delete the prod
 * checkout next door.
 */
export function isLabWorktreePath(p: string): boolean {
    if (!p) return false;
    return currentLabScope().worktreeSegment.test(normalizePath(p));
}

/** process.cwd() throws when the cwd has been unlinked; a guard must not die on it. */
function currentWorkingDir(): string {
    try {
        return process.cwd();
    } catch {
        return '';
    }
}

// ── git target resolution ────────────────────────────────────────────────────

const GIT_GLOBAL_VALUE_OPTS = new Set(['-C', '-c', '--config-env', '--git-dir', '--work-tree', '--namespace', '--exec-path', '--attr-source', '--super-prefix', '--shallow-file']);
// URL and scp-style (`git@github.com:org/repo`) remotes.
const REPO_URL_RE = /^(?:(?:https?|ssh|git|git\+ssh|file):\/\/|[A-Za-z0-9_.-]+@[A-Za-z0-9_.-]+:)/;
// A bare `org/repo` positional. Only consulted in the REMOTE position, so a
// branch named `feature/x` in a refspec position is never mistaken for a repo.
const ORG_REPO_RE = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+(?:\.git)?$/;

/** Index of the git subcommand in `args`, skipping git's global options. */
function gitSubcommandIndex(args: string[]): number {
    let i = 0;
    while (i < args.length) {
        if (GIT_GLOBAL_VALUE_OPTS.has(args[i])) { i += 2; continue; }
        if (args[i].startsWith('-')) { i += 1; continue; }
        break;
    }
    return i;
}

/** Value of `git -C <path>` / `--work-tree <path>`, which relocates the
 *  effective working directory. */
function gitRelocatedDir(args: string[]): string | null {
    for (let i = 0; i < args.length - 1; i++) {
        if (args[i] === '-C' || args[i] === '--work-tree') return args[i + 1];
    }
    return null;
}

/** First positional after the subcommand — the remote for push/fetch/pull. */
function gitRemoteArg(args: string[]): string | null {
    for (let j = gitSubcommandIndex(args) + 1; j < args.length; j++) {
        if (args[j].startsWith('-')) continue;
        return args[j];
    }
    return null;
}

function labGitTarget(cmd: ResolvedCommand, cwd: string): string | null {
    // git clean touches only its work tree; its words (an `-e` pattern, a pathspec) name no repository.
    if (cmd.args[gitSubcommandIndex(cmd.args)] === 'clean') {
        // An exported GIT_WORK_TREE or GIT_DIR elsewhere on the line can move the work tree; only the command's own
        // prefix (which overrides an export) is known.
        const own = (cmd.env ?? []).some(e => e.startsWith('GIT_WORK_TREE='));
        if (!own && /\bGIT_(?:WORK_TREE|DIR)\b/.test(cmd.script?.command ?? cmd.raw)) return null;
        const tree = gitEffectiveDir(cmd.args, cmd.env);
        const dir = tree === undefined ? cwd : pathResolve(cwd, tree);
        return isLabWorktreePath(dir) ? dir : null;
    }
    // An explicit repo URL anywhere in the command decides on its own, and ALL
    // of them must be lab repos — a lab cwd does not launder a push to a prod URL.
    const urls = cmd.args.filter(a => REPO_URL_RE.test(a));
    if (urls.length > 0) {
        return urls.every(isLabRepoRef) ? labRepoRefName(urls[0]) : null;
    }

    // A bare `org/repo` in the remote position decides the same way.
    const remote = gitRemoteArg(cmd.args);
    if (remote && ORG_REPO_RE.test(remote)) {
        return isLabRepoRef(remote) ? labRepoRefName(remote) : null;
    }

    // Bare remote name (`origin`, `upstream`) or none: the checkout decides.
    const effectiveCwd = gitRelocatedDir(cmd.args) ?? cwd;
    return isLabWorktreePath(effectiveCwd) ? effectiveCwd : null;
}

// ── SQL target resolution ────────────────────────────────────────────────────

// `snow` is absent on purpose: Snowflake has no lab tenant.
const LAB_SQL_CLIS = new Set(['psql', 'pg_dump', 'pg_restore', 'pg_dumpall', 'mysql', 'mysqldump']);
const LAB_DB_NAME_RE = /^lab[-_]/i;
// Render Postgres hostnames look like `dpg-xxxx-a.virginia-postgres.render.com`,
// so the reliable lab signals are the DATABASE and USER names, not the host.
const CONNECTION_URI_RE =
    /\b(?:postgres(?:ql)?|mysql|mysqlx|mariadb):\/\/(?:([^:@/\s]*)(?::[^@/\s]*)?@)?([^/?#:\s]*)(?::\d+)?(?:\/([^?#\s]*))?/i;
// libpq keyword/value form: `psql "host=... dbname=lab_app user=lab_app_admin"`.
const CONNECTION_KV_RE = /\b(?:host|user|dbname|database)=([^\s'"]+)/gi;
const SQL_HOST_FLAGS = new Set(['-h', '--host']);
const SQL_USER_FLAGS = new Set(['-U', '--username']);
const SQL_DB_FLAGS = new Set(['-d', '--dbname']);

function labSqlSignal(value: string): string | null {
    if (!value) return null;

    const uri = CONNECTION_URI_RE.exec(value);
    if (uri) {
        for (const part of [uri[1], uri[2], uri[3]]) {
            if (part && LAB_DB_NAME_RE.test(part)) return part;
        }
    }

    CONNECTION_KV_RE.lastIndex = 0;
    let kv: RegExpExecArray | null;
    while ((kv = CONNECTION_KV_RE.exec(value)) !== null) {
        if (LAB_DB_NAME_RE.test(kv[1])) return kv[1];
    }

    return null;
}

function labSqlTarget(cmd: ResolvedCommand): string | null {
    const { args } = cmd;
    for (let i = 0; i < args.length; i++) {
        const a = args[i];

        // --host=lab-x / --username=lab_x / --dbname=lab_app
        const eq = a.match(/^(?:--host|--username|--dbname)=(.+)$/);
        if (eq && LAB_DB_NAME_RE.test(eq[1])) return eq[1];

        // -h lab-x / -U lab_app_admin / -d lab_app
        if (SQL_HOST_FLAGS.has(a) || SQL_USER_FLAGS.has(a) || SQL_DB_FLAGS.has(a)) {
            const v = args[i + 1];
            if (v && !v.startsWith('-') && LAB_DB_NAME_RE.test(v)) return v;
            continue;
        }

        // A connection string, given bare or as some other flag's value.
        const signal = labSqlSignal(a);
        if (signal) return signal;
    }
    return null;
}

// ── Platform / service target resolution ─────────────────────────────────────

const LAB_RESOURCE_RE = /^lab-/;

/**
 * The one resource a render command acts on, when `accepts` vouches for it and for every resource id the line names.
 * Only a `proof` command qualifies (one that acts on the resource it names and runs no other program), read word by
 * word against its own flags, with exactly one operand.
 */
function renderProvenTarget(cmd: ResolvedCommand, accepts: (resource: string) => boolean): string | null {
    const shape = renderShape(cmd.args);
    if (shape?.entry.kind !== 'proof' || shape.output === 'interactive' || shape.help) return null;
    if (shape.operands.length !== 1 || !accepts(shape.operands[0])) return null;
    return renderResourceIds(cmd.args).every(accepts) ? shape.operands[0] : null;
}

function labRenderTarget(cmd: ResolvedCommand): string | null {
    return renderProvenTarget(cmd, r => LAB_RESOURCE_RE.test(r) && !RENDER_RESOURCE_ID_RE.test(r));
}

// `gh repo delete` is exempt for LAB-* under that lab org ONLY. A configured
// extra repo is deliberately not deletable without approval: it is lab-writable,
// not lab-disposable — its name does not start with `LAB-`, so the
// case-insensitive `ghDeletable` pattern still refuses it.
function labGhTarget(cmd: ResolvedCommand): string | null {
    const target = cmd.args[2];
    if (!target) return null;
    const { ghDeletable } = currentLabScope();
    return ghDeletable?.test(target) ? target : null;
}

/**
 * PREDICATE 2 — lab target.
 *
 * Returns the matched target's name (used in the stderr log line) or null.
 * Fails CLOSED: every family it does not recognize, and every target it cannot
 * read literally out of the resolved command, returns null and stays gated.
 */
export function labTargetOf(cmd: ResolvedCommand, cwd: string = currentWorkingDir()): string | null {
    switch (cmd.name) {
        case 'git':
            return labGitTarget(cmd, cwd);
        case 'render':
            return labRenderTarget(cmd);
        case 'gh':
            return cmd.args[0] === 'repo' && cmd.args[1] === 'delete' ? labGhTarget(cmd) : null;
        default:
            return LAB_SQL_CLIS.has(cmd.name) ? labSqlTarget(cmd) : null;
    }
}

/** Boolean form of labTargetOf. */
export function isLabTarget(cmd: ResolvedCommand, cwd: string = currentWorkingDir()): boolean {
    return labTargetOf(cmd, cwd) !== null;
}

function logLabScope(message: string): void {
    console.error(`lab-scope: ${message}`);
}

// ── Dev-scope exemption ──────────────────────────────────────────────────────
// Destructive SQL aimed only at databases the operator lists as dev runs without
// approval, in every session: an approval prompt for every scratch-table DROP
// teaches the approver to click yes on the ones that matter. Which databases, on
// which Snowflake connection, is deployment data in an untracked
// `dev-scope.local.json`, found like lab-scope.local.json:
//   {"snowflake": [{"connection": "<name>", "databases": ["<dev db>", …]}]}
// No readable, valid file exempts nothing.
//
// The exemption is by database, never by whole connection: a "dev" connection
// commonly shares its account and role with prod, so only the target's database
// says what a statement can reach. It fails closed: the command must be a bare
// `snow sql` with a literal `-c`/`--connection` and only flags known not to change
// account, identity, role or config; nothing in the command may assign, export
// or source anything; and every destructive statement must name its target fully
// qualified inside a listed database, with no variables, templating, scripting
// blocks, IDENTIFIER() or EXECUTE IMMEDIATE.

export const DEV_SCOPE_FILE_ENV = 'BOOTSTRAP_DEV_SCOPE_FILE';
const DEV_SCOPE_FILE = 'dev-scope.local.json';
const SNOWFLAKE_NAME_RE = /^[A-Za-z0-9_.-]{1,128}$/;

export interface DevLogin {
    user: string;
    account: string;
    verifiedUntil?: string;
}

export interface DevScope {
    snowflake: Array<{ connection: string; databases: string[]; login?: DevLogin }>;
    render?: { resources: string[] };
}

/** Parse a dev-scope file's text. Null when anything about it is unusable. */
export function parseDevScope(text: string): DevScope | null {
    let raw: unknown;
    try {
        raw = JSON.parse(text);
    } catch {
        return null;
    }
    const entries = (raw as { snowflake?: unknown } | null)?.snowflake;
    if (!Array.isArray(entries)) return null;
    for (const e of entries) {
        if (!e || typeof e !== 'object' || typeof e.connection !== 'string' || !SNOWFLAKE_NAME_RE.test(e.connection)) return null;
        if (!Array.isArray(e.databases) || e.databases.length === 0
            || !e.databases.every((d: unknown) => typeof d === 'string' && /^[A-Za-z_][A-Za-z0-9_$]{0,254}$/.test(d))) {
            return null;
        }
        if (e.login !== undefined) {
            const l = e.login;
            if (!l || typeof l !== 'object' || typeof l.user !== 'string' || !SNOWFLAKE_NAME_RE.test(l.user)
                || typeof l.account !== 'string' || !SNOWFLAKE_NAME_RE.test(l.account)
                || (l.verifiedUntil !== undefined && typeof l.verifiedUntil !== 'string')) {
                return null;
            }
        }
    }
    const render = (raw as { render?: unknown }).render;
    if (render === undefined) return { snowflake: entries as DevScope['snowflake'] };
    const resources = (render as { resources?: unknown } | null)?.resources;
    if (!Array.isArray(resources) || resources.length === 0
        || !resources.every((r: unknown) => typeof r === 'string' && RENDER_RESOURCE_ID_RE.test(r))) {
        return null;
    }
    return { snowflake: entries as DevScope['snowflake'], render: { resources: resources as string[] } };
}

function renderDevTarget(cmd: ResolvedCommand): string | null {
    const listed = new Set(currentDevScope()?.render?.resources ?? []);
    const target = renderProvenTarget(cmd, r => listed.has(r));
    return target ? `render resource ${target}` : null;
}

function currentDevScope(): DevScope | null {
    const file = deploymentFilePath(DEV_SCOPE_FILE, DEV_SCOPE_FILE_ENV);
    if (!file) return null;
    try {
        return parseDevScope(readFileSync(file, 'utf-8'));
    } catch {
        return null;
    }
}

// The only `snow sql` options an exempt command may carry: none of them changes
// the account, user, role, credentials, config or the SQL that runs.
const SNOW_SQL_VALUE_FLAGS = new Set(['-c', '--connection', '-q', '--query', '--format', '--warehouse', '--enable-templating']);
const SNOW_SQL_BARE_FLAGS = new Set(['--silent', '--verbose', '--debug', '--enhanced-exit-codes']);
// Wrappers that leave the command's user and environment alone (`sudo` and `env` do not, so they never qualify).
const SAFE_WRAPPERS_PREFIX = String.raw`^(?:(?:g?timeout\s+\d+(?:\.\d+)?[smhd]?|nohup|time)\s+)*`;
const SNOW_UNDER_SAFE_WRAPPERS_RE = new RegExp(`${SAFE_WRAPPERS_PREFIX}snow\\s`);
// Commands that change what a later command sees: its environment, or code it sources.
const ENVIRONMENT_CHANGERS = new Set(['export', 'set', 'source', '.', 'declare', 'typeset', 'env', 'eval', 'readonly', 'local', 'alias', 'unset', 'read', 'mapfile', 'readarray', 'getopts', 'let', 'trap']);

/** `printf -v NAME` and `wait -p NAME` assign the variable they name. */
function setsVariableByOption(cmd: ResolvedCommand): boolean {
    return (cmd.name === 'printf' && cmd.args.some(a => /^-v/.test(a))) || (cmd.name === 'wait' && cmd.args.some(a => /^-[a-z]*p/.test(a)));
}

/**
 * True when the command line assigns a variable (by assignment word, loop, arithmetic or a `${name:=value}` default),
 * defines a function, or can't be parsed to tell. A function can take the name of the command an exemption reads, and
 * run something else under it.
 */
function changesShellState(command: string): boolean {
    const found = (node: unknown): boolean => {
        if (!node || typeof node !== 'object') return false;
        if (Array.isArray(node)) return node.some(found);
        const type = (node as { type?: unknown }).type;
        if (type === 'Assignment' || type === 'For' || type === 'Select' || type === 'Function' || type === 'ArithmeticCommand' || type === 'ArithmeticFor') return true;
        return Object.values(node).some(found);
    };
    // A word's parts are not walked here, so an expansion that assigns is found in the text.
    if (/\$\{[^}]*?=|\$\(\(/.test(command)) return true;
    try {
        return found(parseShell(command));
    } catch {
        return true;
    }
}

/** Snowflake folds an unquoted identifier to upper case and keeps a quoted one as written. */
function snowflakeIdentifier(part: string): string | null {
    const quoted = part.match(/^"((?:[^"]|"")+)"$/);
    if (quoted) return quoted[1].replace(/""/g, '"');
    return /^[A-Za-z_][A-Za-z0-9_$]*$/.test(part) ? part.toUpperCase() : null;
}

/** True when `text` holds a template (`<% %>`, `&{ }` or bare `&name`; `&&` escapes, but `&&{` reopens as `&{`) that no -D/--variable on the command fills. */
function unfilledSnowTemplate(text: string, cmd: ResolvedCommand): boolean {
    const given = new Set<string>();
    for (let i = 0; i < cmd.args.length; i++) {
        for (const o of ['-D', '--variable']) {
            const m = optionValueAt(cmd.args, i, o)?.match(/^([\w.]+)=/);
            if (m) given.add(m[1]);
        }
    }
    const rest = text.replace(/&&/g, '').replace(SNOW_TEMPLATE, (m, a, b, c) => (given.has(a ?? b ?? c) ? '' : m));
    return /&&\{/.test(text) || /<%|&\{|&[A-Za-z_]/.test(rest);
}

/** The values given to every `--enable-templating` option, upper-cased. */
function snowTemplating(cmd: ResolvedCommand): string[] {
    const values: string[] = [];
    for (let i = 0; i < cmd.args.length; i++) {
        const v = optionValueAt(cmd.args, i, '--enable-templating');
        if (v !== undefined) values.push(...v.toUpperCase().split(','));
    }
    return values;
}

/** The fully qualified object a destructive statement acts on, as Snowflake identifiers. */
function statementTarget(pattern: string, statement: string): { kind: string; parts: string[] } | null {
    const s = oneLine(statement.slice(0, STATEMENT_MAX_CHARS));
    const name = String.raw`((?:"(?:[^"]|"")+"|[A-Za-z0-9_$]+)(?:\.(?:"(?:[^"]|"")+"|[A-Za-z0-9_$]+))*)`;
    const m =
        pattern === 'DROP' ? s.match(new RegExp(String.raw`^DROP\s+(MATERIALIZED\s+VIEW|\w+)\s+(?:IF\s+EXISTS\s+)?` + name + String.raw`\s*(?:CASCADE|RESTRICT)?\s*$`, 'i'))
        : pattern === 'TRUNCATE' ? s.match(new RegExp(String.raw`^TRUNCATE\s+(?:(TABLE)\s+)?(?:IF\s+EXISTS\s+)?` + name + String.raw`\s*$`, 'i'))
        : pattern === 'DELETE FROM' ? s.match(new RegExp(String.raw`^DELETE\s+FROM()\s+` + name + String.raw`(?:\s|$)`, 'i'))
        : pattern === 'CREATE OR REPLACE' ? s.match(new RegExp(String.raw`^CREATE\s+OR\s+REPLACE\s+((?:(?:TEMP|TEMPORARY|EXTERNAL|MATERIALIZED|TRANSIENT|SECURE)\s+)*\w+)\s+(?:IF\s+NOT\s+EXISTS\s+)?` + name + String.raw`(?:\s|\(|$)`, 'i'))
        : pattern === 'INSERT OVERWRITE' ? s.match(new RegExp(String.raw`^INSERT\s+OVERWRITE\s+(?:INTO\s+)?(?:(TABLE)\s+)?` + name + String.raw`(?:\s|\(|$)`, 'i'))
        : pattern === 'MERGE' ? s.match(new RegExp(String.raw`^MERGE\s+INTO()\s+` + name + String.raw`(?:\s|$)`, 'i'))
        : pattern === 'ALTER ... DROP' ? s.match(new RegExp(String.raw`^ALTER\s+(\w+)\s+(?:IF\s+EXISTS\s+)?` + name + String.raw`\s`, 'i'))
        : pattern === 'UPDATE without WHERE' ? s.match(new RegExp(String.raw`^UPDATE()\s+` + name + String.raw`\s`, 'i'))
        : null;
    if (!m) return null;
    const parts = m[2].match(/"(?:[^"]|"")+"|[^.]+/g)?.map(snowflakeIdentifier) ?? [];
    if (parts.some(p => p === null)) return null;
    return { kind: (m[1] || 'table').toLowerCase().replace(/\s+/g, ' '), parts: parts as string[] };
}

// Options a trusted dev login may carry: they choose the SQL, its defaults and output, never the account, user,
// credentials or config.
const TRUSTED_LOGIN_VALUE_FLAGS = new Set(['-c', '--connection', '-q', '--query', '-f', '--filename', '-D', '--variable', '--env', '--enable-templating', '--database', '--dbname', '--schema', '--schemaname', '--role', '--rolename', '--warehouse', '--format']);
const TRUSTED_LOGIN_BARE_FLAGS = new Set(['-i', '--stdin', '--silent', '-v', '--verbose', '--debug', '--enhanced-exit-codes', '--retain-comments', '--single-transaction']);
// A verification older than this is not trusted, whatever date it names.
const DEV_LOGIN_MAX_HORIZON_MS = 3 * 24 * 60 * 60 * 1000;

const TRUSTED_CONNECTION_KEYS = new Set(['account', 'user', 'role', 'warehouse', 'database', 'schema', 'authenticator', 'private_key_path', 'private_key_file']);

/**
 * True when the file can't change between this check and snow reading it: it sits on a read-only mount, as the
 * container's staged Snowflake config does. A file the agent's user owns could be rewritten, or made writable, first.
 */
function configLocked(file: string): boolean {
    try {
        accessSync(file, fsConstants.W_OK);
        return false;
    } catch (err) {
        return (err as { code?: unknown }).code === 'EROFS';
    }
}

export const devLoginTestHooks = { configLocked };

/**
 * True when connection `name` in the Snowflake CLI's locked config signs in as `login` with a key pair, and a check
 * of that login's grants vouched for it recently. Snowflake then refuses every statement this guard gates outside the
 * dev databases, so no SQL needs reading.
 */
function trustedDevLogin(name: string, login: DevLogin | undefined): boolean {
    if (!login?.verifiedUntil || name.includes('.')) return false;
    const until = Date.parse(login.verifiedUntil);
    if (!Number.isFinite(until) || until <= Date.now() || until > Date.now() + DEV_LOGIN_MAX_HORIZON_MS) return false;
    // snow finds its config through HOME, as Python's expanduser does.
    const dir = join(process.env.HOME || homedir(), '.snowflake');
    const file = join(dir, 'connections.toml');
    const toml = (globalThis as { Bun?: { TOML?: { parse(text: string): unknown } } }).Bun?.TOML;
    try {
        // A link is checked where it points, but could be repointed before snow follows it.
        if (!toml || lstatSync(dir).isSymbolicLink() || lstatSync(file).isSymbolicLink() || !devLoginTestHooks.configLocked(file)) return false;
        const section = (toml.parse(readFileSync(file, 'utf-8')) as Record<string, unknown>)[name];
        if (!section || typeof section !== 'object' || Array.isArray(section)) return false;
        const entries = Object.entries(section as Record<string, unknown>);
        if (entries.some(([k, v]) => !TRUSTED_CONNECTION_KEYS.has(k) || typeof v !== 'string')) return false;
        const get = (k: string) => (section as Record<string, string>)[k];
        return get('user')?.toUpperCase() === login.user.toUpperCase()
            && get('account')?.toUpperCase() === login.account.toUpperCase()
            && get('authenticator')?.toUpperCase() === 'SNOWFLAKE_JWT'
            && Boolean(get('private_key_path') ?? get('private_key_file'));
    } catch {
        return false;
    }
}

// Environment names that decide which config, binary or code snow runs with.
const SNOW_ENVIRONMENT_NAME = /^(?:HOME|PATH|SNOWFLAKE_\w*|PYTHON\w*|LD_\w+)$/;
// bash 5.2's builtins (`compgen -b`). Only a builtin runs inside the shell and can change what a later command inherits;
// any other command is a child process.
const BASH_BUILTINS = new Set(['.', ':', '[', 'alias', 'bg', 'bind', 'break', 'builtin', 'caller', 'cd', 'command', 'compgen', 'complete', 'compopt', 'continue', 'declare', 'dirs', 'disown', 'echo', 'enable', 'eval', 'exec', 'exit', 'export', 'false', 'fc', 'fg', 'getopts', 'hash', 'help', 'history', 'jobs', 'kill', 'let', 'local', 'logout', 'mapfile', 'popd', 'printf', 'pushd', 'pwd', 'read', 'readarray', 'readonly', 'return', 'set', 'shift', 'shopt', 'source', 'suspend', 'test', 'times', 'trap', 'true', 'type', 'typeset', 'ulimit', 'umask', 'unalias', 'unset', 'wait']);
// The builtins that assign no variable and change no lookup (`hash -p` repoints a command, so it is not here).
const NEUTRAL_BUILTINS = new Set(['cd', 'true', ':']);

/**
 * True when a word expands nothing that can assign: only `$NAME`, `${NAME}`, command substitutions (a subshell) and
 * literal text. `$(( ))`, `$[ ]` and any other `${…}` form evaluate arithmetic or assign in the current shell.
 */
function assignsNothing(word: string): boolean {
    return !/\$\(\(|\$\[/.test(word) && ![...word.matchAll(/\$\{/g)].some(m => !/^\$\{[A-Za-z_]\w*\}/.test(word.slice(m.index)));
}

/**
 * True when a word stays one argument: nothing outside quotes word-splits or globs, so a value can't smuggle in an
 * option of its own. `"$@"` splits even inside double quotes.
 */
function staysOneWord(word: string): boolean {
    let quote: string | null = null;
    for (let i = 0; i < word.length; i++) {
        const c = word[i];
        if (quote === "'") {
            if (c === "'") quote = null;
        } else if (c === '\\') {
            i++;
        } else if (quote === '"') {
            if (c === '"') quote = null;
            else if (c === '$' && word[i + 1] === '@') return false;
        } else if (c === "'" || c === '"') {
            quote = c;
        } else if ('$`*?['.includes(c)) {
            return false;
        }
    }
    return true;
}

/**
 * True when nothing on the line can change the environment `step` (a top-level `snow sql`) inherits. It is decided by
 * what is allowed rather than by listing bash's ways to assign: before the step, in the same shell, only plain
 * assignments to names the environment doesn't hold and a few commands that change no environment; the step's own
 * words expand nothing that assigns. A pipeline's other stages and anything after the step can't reach it.
 */
function snowEnvironmentProven(command: string, step: ResolvedCommand): boolean {
    type Node = { type?: string; name?: unknown; prefix?: Node[]; suffix?: Node[]; commands?: Node[]; command?: Node; text?: string; index?: unknown; pos?: number; end?: number };
    let script: Node;
    try {
        script = parseShell(command) as Node;
    } catch {
        return false;
    }
    type Redirect = { target?: { text?: string }; content?: string };
    // Redirect targets and here-document bodies are expanded by this shell too.
    const words = (n: Node) => [...(n.prefix ?? []), ...(n.suffix ?? [])].map(w => String(w?.text ?? ''))
        .concat(((n as { redirects?: Redirect[] }).redirects ?? []).flatMap(r => [String(r.target?.text ?? ''), String(r.content ?? '')]));
    const assignmentSafe = (a: Node) => a.type === 'Assignment' && typeof a.name === 'string' && a.index === undefined && (a as { array?: unknown }).array === undefined
        && !(a.name in process.env) && !SNOW_ENVIRONMENT_NAME.test(a.name) && assignsNothing(String(a.text ?? ''));
    const neutral = (n: Node): boolean => {
        if (n.type === 'Pipeline') return (n.commands?.length ?? 0) > 1;
        if (n.type === 'AndOr') return (n.commands ?? []).every(neutral);
        if (n.type !== 'Command') return false;
        const name = (n.name as { text?: string } | undefined)?.text;
        if (!(n.prefix ?? []).every(assignmentSafe)) return false;
        const neutralName = name === undefined
            || (/^[A-Za-z0-9_./+@%:,-]+$/.test(name) && (!BASH_BUILTINS.has(name) || NEUTRAL_BUILTINS.has(name)));
        return neutralName && words(n).every(assignsNothing);
    };
    const holds = (n: Node) => typeof n.pos === 'number' && typeof n.end === 'number' && n.pos <= step.pos! && step.pos! < n.end;
    // The step itself, or a stage of a pipeline, reached through `&&`/`||` lists whose earlier members are neutral.
    const reaches = (n: Node): boolean => {
        if (n.type === 'Command') {
            return n.pos === step.pos && words(n).every(assignsNothing)
                && (n.suffix ?? []).every(w => staysOneWord(String(w?.text ?? '')));
        }
        if (n.type === 'Pipeline') return (n.commands ?? []).some(c => c.type === 'Command' && holds(c) && reaches(c));
        if (n.type !== 'AndOr') return false;
        const members = n.commands ?? [];
        const at = members.findIndex(holds);
        return at >= 0 && members.slice(0, at).every(neutral) && reaches(members[at]);
    };
    if (step.pos === undefined) return false;
    const statements = (script.commands ?? []).map(st => st.command ?? st);
    const at = statements.findIndex(holds);
    return at >= 0 && statements.slice(0, at).every(neutral) && reaches(statements[at]);
}

/** The connection a `snow sql` step names, when every option it carries is one a trusted dev login may take. */
function trustedLoginConnection(cmd: ResolvedCommand): string | null {
    let connection: string | null = null;
    for (let i = 1; i < cmd.args.length; i++) {
        const a = cmd.args[i];
        const [flag, inline] = a.startsWith('--') && a.includes('=') ? [a.slice(0, a.indexOf('=')), a.slice(a.indexOf('=') + 1)] : [a, undefined];
        if (TRUSTED_LOGIN_BARE_FLAGS.has(flag) && inline === undefined) continue;
        if (!TRUSTED_LOGIN_VALUE_FLAGS.has(flag)) return null;
        const value = inline ?? cmd.args[++i];
        if (value === undefined) return null;
        if (flag === '-c' || flag === '--connection') {
            if (connection !== null || !SNOWFLAKE_NAME_RE.test(value)) return null;
            connection = value;
        }
    }
    return connection;
}

/**
 * The dev database a `snow sql` command is exempt under, or null. `commands` and
 * `command` are the whole command line, so anything set up around the call counts.
 */
export function devScopeTargetOf(cmd: ResolvedCommand, commands: ResolvedCommand[], command: string, topLevel = true): string | null {
    if (cmd.name === 'render') return topLevel ? renderDevTarget(cmd) : null;
    if (cmd.name !== 'snow' || cmd.args[0] !== 'sql') return null;
    const scope = currentDevScope();
    if (!scope) return null;
    if ((cmd.env ?? []).length || cmd.chdir !== undefined || !SNOW_UNDER_SAFE_WRAPPERS_RE.test(cmd.raw)) return null;
    // snow inherits this process's environment, where SNOWFLAKE_* can repoint a named connection.
    if (Object.keys(process.env).some(k => k.toUpperCase().startsWith('SNOWFLAKE_'))) return null;
    if (commands.some(c => ENVIRONMENT_CHANGERS.has(c.name) || setsVariableByOption(c))) return null;

    // An xargs or find step's words are not the ones read here.
    const trusted = topLevel ? trustedLoginConnection(cmd) : null;
    const trustedEntry = trusted === null ? undefined : scope.snowflake.find(e => e.connection === trusted);
    if (trustedEntry && snowEnvironmentProven(command, cmd) && trustedDevLogin(trustedEntry.connection, trustedEntry.login)) {
        return `snowflake connection ${trustedEntry.connection}, dev-only login ${trustedEntry.login!.user}`;
    }
    if (changesShellState(command)) return null;

    let connection: string | undefined;
    for (let i = 1; i < cmd.args.length; i++) {
        const a = cmd.args[i];
        const [flag, inline] = a.startsWith('--') && a.includes('=') ? [a.slice(0, a.indexOf('=')), a.slice(a.indexOf('=') + 1)] : [a, undefined];
        if (SNOW_SQL_BARE_FLAGS.has(flag) && inline === undefined) continue;
        if (!SNOW_SQL_VALUE_FLAGS.has(flag)) return null;
        const value = inline ?? cmd.args[++i];
        if (value === undefined) return null;
        if (flag === '-c' || flag === '--connection') {
            if (connection !== undefined || !SNOWFLAKE_NAME_RE.test(value)) return null;
            connection = value;
        }
    }
    const entry = scope.snowflake.find(e => e.connection === connection);
    if (!entry) return null;
    if (snowTemplating(cmd).some(t => t !== 'NONE')) return null;

    const allowed = new Set(entry.databases.map(d => d.toUpperCase()));
    let matched = false;
    if (cmd.stdinTexts?.length || cmd.stdinFiles?.length) return null;
    const input = sqlInputOf(cmd);
    if (input.unreadable) return null;
    for (const arg of input.texts) {
        if (!splitsLikeSnow(arg)) return null;
        if (/[$&]|<%|\bIDENTIFIER\s*\(|\bEXECUTE\b|\bBEGIN\b|\bDECLARE\b|\bCALL\b|^\s*DO\b|[!\\]\w/im.test(arg)) return null;
        if (!findDestructiveSqlStatement(arg)) continue;
        for (const st of destructiveStatements(arg)) {
            const target = statementTarget(st.pattern, st.statement);
            if (!target) return null;
            const needed = target.kind === 'schema' ? 2 : target.kind === 'database' ? 0 : 3;
            if (needed === 0 || target.parts.length !== needed || !allowed.has(target.parts[0])) return null;
            matched = true;
        }
    }
    return matched ? `snowflake connection ${entry.connection}, database ${entry.databases.join('/')}` : null;
}

// ── Local scratch Postgres exemption ─────────────────────────────────────────
// Destructive psql against a throwaway Postgres the session started in its own
// container runs without approval. A loopback address or a /tmp socket proves
// nothing on its own: an `ssh -L`, socat, `render psql`, kubectl port-forward or a
// forwarded unix socket each put a remote database behind one, and libpq, psql and
// the shell each have ways to connect somewhere other than the -h a command shows.
// So the exemption accepts only a command whose connection needs no emulation of
// them, and procfs must show every listener it reaches held only by postgres
// running from a data directory under /tmp: a postgres on loopback can as well be a
// volume-backed database with real data. Anything else, or anything unreadable, holds.
// `localhost`, an omitted port, connection strings and psqlrc files are refused
// rather than resolved: NSS, the client build, libpq's own parser and psql's
// binary-relative startup files decide them, not anything the guard can read.
// A change made by another process between this check and psql connecting is not
// ruled out. Tier-1 hard blocks are never exempted.

/**
 * What the local-Postgres exemption reads from the host it runs on; tests supply fixtures. Each read is null when
 * the path can't be read. A directory or link that no longer exists reads as empty instead: a process that exited, or
 * a descriptor closed while its directory was listed (the listing's own, for one), holds no socket.
 */
export interface LocalPgHost {
    platform: string;
    env: Record<string, string | undefined>;
    readFile(path: string): string | null;
    readDir(path: string): string[] | null;
    readLink(path: string): string | null;
}

function readOr<T>(read: () => T, gone: T | null): T | null {
    try {
        return read();
    } catch (e) {
        return (e as NodeJS.ErrnoException).code === 'ENOENT' ? gone : null;
    }
}

const LIVE_LOCAL_PG_HOST: LocalPgHost = {
    platform: process.platform,
    env: process.env,
    readFile: (p) => readOr(() => readFileSync(p, 'utf-8'), null),
    readDir: (p) => readOr(() => readdirSync(p), []),
    readLink: (p) => readOr(() => readlinkSync(p), ''),
};

const PSQL_UNDER_SAFE_WRAPPERS_RE = new RegExp(`${SAFE_WRAPPERS_PREFIX}(?:/[^\\s'"$\`\\\\]*/)?psql\\s`);
// What else the line may run. Not printf (`-v` assigns), sort (`-o`) or tee, which write; and not a second psql, whose
// `\!` could stop the checked postgres and start a forwarder before this one connects.
const LOCAL_PG_LINE_COMMANDS = new Set(['cd', 'pushd', 'popd', 'echo', 'cat', 'head', 'tail', 'grep', 'wc', 'true']);
// POSIXLY_CORRECT stops psql's getopt at the first operand, so options after it are not read the way psqlTarget reads them.
const LIBPQ_REDIRECT_ENV = ['PGHOSTADDR', 'PGSERVICE', 'PGSERVICEFILE', 'PGSYSCONFDIR', 'POSIXLY_CORRECT'];
const FILE_WRITE_REDIRECTS = new Set(['>', '>>', '>|', '&>', '&>>', '<>']);
// Any expansion on the line holds, heredoc bodies included: `${v:=…}` and `$((v=…))` assign, and the parser exposes a
// substitution's script only through a getter that a walk of the tree never reaches, so a write inside one is unseen.
const LINE_EXPANSION_RE = /[$`]|[<>]\(/;
// Node types of a line of plain commands joined by pipes, `&&`, `||` or `;`. Loops, conditionals, subshells, groups,
// functions and assignments are anything else, and hold.
const PLAIN_LINE_NODES = new Set(['Script', 'Statement', 'Command', 'Pipeline', 'AndOr']);

const PSQL_SHORT_FLAGS = 'XqtA1eabEnwWx';
const PSQL_SHORT_VALUES: Record<string, string> = { c: '--command', d: '--dbname', h: '--host', p: '--port', U: '--username', v: '--set' };
const PSQL_LONG_FLAGS = new Set(['--no-psqlrc', '--quiet', '--tuples-only', '--no-align', '--single-transaction', '--echo-queries', '--echo-all', '--echo-errors', '--echo-hidden', '--no-readline', '--no-password', '--password', '--expanded', '--csv']);
const PSQL_LONG_VALUES = new Set(['--command', '--dbname', '--host', '--port', '--username', '--set', '--variable']);

/** True when the shell passes `text` (one argument as written) through unchanged: no expansion, glob or escape. */
function isLiteralShellWord(text: string): boolean {
    for (let i = 0; i < text.length; i++) {
        if (text[i] === "'") {
            i = text.indexOf("'", i + 1);
            if (i < 0) return false;
        } else if (text[i] === '"') {
            const end = text.indexOf('"', i + 1);
            if (end < 0 || /[$`\\]/.test(text.slice(i + 1, end))) return false;
            i = end;
        } else if ('$`\\*?[{~()'.includes(text[i])) {
            return false;
        }
    }
    return true;
}

/** `cmd`'s arguments as the command line writes them, or null when the parse doesn't have them. */
function writtenArgs(cmd: ResolvedCommand): string[] | null {
    const script = cmd.script;
    if (cmd.pos === undefined || !script || cmd.argsAreValues) return null;
    script.view ??= viewShell(script.command);
    const texts = script.view.commandAt(cmd.pos)?.argTexts;
    return texts && texts.length >= cmd.args.length ? texts.slice(texts.length - cmd.args.length) : null;
}

/** True when every node of the parsed line is a plain command or what joins them; false when it can't be parsed. */
function isPlainLine(command: string): boolean {
    const plain = (node: unknown): boolean => {
        if (!node || typeof node !== 'object') return true;
        if (Array.isArray(node)) return node.every(plain);
        const type = (node as { type?: unknown }).type;
        return (typeof type !== 'string' || PLAIN_LINE_NODES.has(type)) && Object.values(node).every(plain);
    };
    try {
        return plain(parseShell(command));
    } catch {
        return false;
    }
}

/** True when the command line redirects any output into a file other than /dev/null, or can't be parsed to tell. */
function mayWriteFiles(command: string): boolean {
    const writes = (node: unknown): boolean => {
        if (!node || typeof node !== 'object') return false;
        if (Array.isArray(node)) return node.some(writes);
        const r = node as { operator?: unknown; target?: { value?: unknown } };
        if (typeof r.operator === 'string' && r.target) {
            const target = r.target.value;
            if (FILE_WRITE_REDIRECTS.has(r.operator) && target !== '/dev/null') return true;
            if (r.operator === '>&' && !(typeof target === 'string' && /^\d+$/.test(target))) return true;
        }
        return Object.values(node).some(writes);
    };
    try {
        return writes(parseShell(command));
    } catch {
        return true;
    }
}

/**
 * The host and port psql connects to, read the way psql reads its options: the last of a repeated option wins, and
 * whether -X skips the startup files. Null when an option is one the guard doesn't place, no -c gives the SQL, or the
 * dbname is a connection string libpq would expand.
 */
function psqlTarget(args: string[]): { host?: string; port?: string; noPsqlrc: boolean } | null {
    const last = new Map<string, string>();
    const positionals: string[] = [];
    let commands = 0;
    let noPsqlrc = false;
    const take = (option: string, value: string) => {
        if (option === '--command') commands++;
        else last.set(option, value);
    };
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a === '--') {
            positionals.push(...args.slice(i + 1));
            break;
        }
        if (a.startsWith('--')) {
            const eq = a.indexOf('=');
            const option = eq < 0 ? a : a.slice(0, eq);
            if (eq < 0 && PSQL_LONG_FLAGS.has(option)) {
                if (option === '--no-psqlrc') noPsqlrc = true;
                continue;
            }
            const value = eq < 0 ? args[++i] : a.slice(eq + 1);
            if (!PSQL_LONG_VALUES.has(option) || value === undefined) return null;
            take(option, value);
            continue;
        }
        if (a.length > 1 && a.startsWith('-')) {
            for (let j = 1; j < a.length; j++) {
                if (PSQL_SHORT_FLAGS.includes(a[j])) {
                    if (a[j] === 'X') noPsqlrc = true;
                    continue;
                }
                const option = PSQL_SHORT_VALUES[a[j]];
                const value = j + 1 < a.length ? a.slice(j + 1) : args[++i];
                if (!option || value === undefined) return null;
                take(option, value);
                break;
            }
            continue;
        }
        positionals.push(a);
    }
    if (commands === 0) return null;
    // Without -d, psql takes the first operand as the dbname (later ones as the username, or ignored). libpq expands a
    // dbname holding `=` or a URI prefix, and what that holds overrides -h and -p.
    const dbname = last.get('--dbname') ?? positionals[0];
    if (dbname !== undefined && (dbname.includes('=') || /^postgres(?:ql)?:\/\//.test(dbname))) return null;
    return { host: last.get('--host'), port: last.get('--port'), noPsqlrc };
}

/** A /proc/net/tcp{,6} address in network byte order as hex; the kernel prints each 32-bit word in host order. */
function procNetAddress(hex: string): string {
    if (endianness() === 'BE') return hex.toLowerCase();
    return (hex.match(/.{8}/g) ?? []).map(w => w.match(/../g)!.reverse().join('')).join('').toLowerCase();
}

// Listening addresses a connection to each loopback address can reach, per /proc/net file, in network byte order.
const LOOPBACK_LISTENERS: Record<string, Array<[string, Set<string>]>> = {
    '127.0.0.1': [
        ['/proc/net/tcp', new Set(['7f000001', '00000000'])],
        ['/proc/net/tcp6', new Set(['0'.repeat(32), '00000000000000000000ffff00000000', '00000000000000000000ffff7f000001'])],
    ],
    '::1': [['/proc/net/tcp6', new Set(['0'.repeat(31) + '1', '0'.repeat(32)])]],
};

/** Inodes of the TCP sockets listening where `address`:`port` connects; null when a table can't be read. */
function tcpListenerInodes(host: LocalPgHost, address: string, port: number): string[] | null {
    const inodes: string[] = [];
    for (const [file, accepts] of LOOPBACK_LISTENERS[address]) {
        const table = host.readFile(file);
        if (table === null) return null;
        for (const line of table.split('\n').slice(1)) {
            const f = line.trim().split(/\s+/);
            const local = f[1]?.match(/^([0-9A-Fa-f]+):([0-9A-Fa-f]{4})$/);
            if (!local || f[3] !== '0A' || parseInt(local[2], 16) !== port) continue;
            if (accepts.has(procNetAddress(local[1]))) inodes.push(f[9]);
        }
    }
    return inodes;
}

/** Inodes of the unix sockets listening at `path`; null when the table can't be read. */
function unixListenerInodes(host: LocalPgHost, path: string): string[] | null {
    const table = host.readFile('/proc/net/unix');
    if (table === null) return null;
    const inodes: string[] = [];
    for (const line of table.split('\n').slice(1)) {
        const m = line.match(/^\s*[0-9A-Fa-f]+:\s+\S+\s+\S+\s+([0-9A-Fa-f]+)\s+\S+\s+\S+\s+(\d+)\s(.*)$/);
        // __SO_ACCEPTCON: a listening socket, not a connection accepted from it, which shows the same path.
        if (m && m[3] === path && (parseInt(m[1], 16) & 0x10000) !== 0) inodes.push(m[2]);
    }
    return inodes;
}

/** The pids holding each socket inode; null unless every process's descriptors could be read. */
function socketHolders(host: LocalPgHost, inodes: Set<string>): Map<string, string[]> | null {
    const pids = host.readDir('/proc');
    if (pids === null) return null;
    const holders = new Map<string, string[]>();
    for (const pid of pids.filter(p => /^\d+$/.test(p))) {
        const fds = host.readDir(`/proc/${pid}/fd`);
        if (fds === null) return null;
        for (const fd of fds) {
            const link = host.readLink(`/proc/${pid}/fd/${fd}`);
            if (link === null) return null;
            const inode = link.match(/^socket:\[(\d+)\]$/)?.[1];
            if (inode && inodes.has(inode)) holders.set(inode, [...(holders.get(inode) ?? []), pid]);
        }
    }
    return holders;
}

function isPostgresProcess(host: LocalPgHost, pid: string): boolean {
    if (host.readFile(`/proc/${pid}/comm`)?.trim() === 'postgres') return true;
    const exe = host.readLink(`/proc/${pid}/exe`);
    return exe !== null && basename(exe.replace(/ \(deleted\)$/, '')) === 'postgres';
}

/**
 * The data directory of a postgres process when it is under /tmp, else null. The postmaster changes into its data
 * directory at start and its children inherit that, so the cwd names it; under /tmp it is scratch that goes with the
 * container, where a volume-backed or system database lives anywhere else.
 */
function scratchDataDir(host: LocalPgHost, pid: string): string | null {
    const cwd = host.readLink(`/proc/${pid}/cwd`);
    return cwd?.startsWith('/tmp/') ? cwd : null;
}

/** "<endpoint> (postgres pid N, data <dir>)" when only scratch postgres holds every listener in `inodes`, else null. */
function postgresListening(host: LocalPgHost, endpoint: string, inodes: string[] | null): string | null {
    if (!inodes?.length || inodes.some(i => !/^[1-9]\d*$/.test(i))) return null;
    const holders = socketHolders(host, new Set(inodes));
    if (!holders) return null;
    const pids = new Set<string>();
    const dataDirs = new Set<string>();
    for (const inode of inodes) {
        const held = holders.get(inode);
        if (!held?.length) return null;
        for (const pid of held) {
            const dataDir = isPostgresProcess(host, pid) ? scratchDataDir(host, pid) : null;
            if (!dataDir) return null;
            pids.add(pid);
            dataDirs.add(dataDir);
        }
    }
    return `${endpoint} (postgres pid ${[...pids].join(', ')}, data ${[...dataDirs].join(', ')})`;
}

/**
 * The local scratch Postgres a top-level psql command is exempt against, or null. `commands` and `command` are the
 * whole command line, so anything set up around the call counts. `assumeNoPsqlrc` asks whether the command would be
 * exempt with -X added, which is all that tells the agent how to rerun it without approval.
 */
export function localPgTargetOf(
    cmd: ResolvedCommand,
    commands: ResolvedCommand[],
    command: string,
    host: LocalPgHost = LIVE_LOCAL_PG_HOST,
    assumeNoPsqlrc = false,
): string | null {
    if (cmd.name !== 'psql' || host.platform !== 'linux') return null;
    if ((cmd.env ?? []).length || cmd.chdir !== undefined || !PSQL_UNDER_SAFE_WRAPPERS_RE.test(cmd.raw)) return null;
    // Each neighbour by its own name with no wrapper: `npx cat` resolves to cat but runs a package.
    const plain = (c: ResolvedCommand) => LOCAL_PG_LINE_COMMANDS.has(c.name) && (c.raw === c.name || c.raw.startsWith(`${c.name} `));
    if (!commands.every(c => c === cmd || plain(c)) || LINE_EXPANSION_RE.test(command)) return null;
    if (!isPlainLine(command) || mayWriteFiles(command)) return null;
    if (LIBPQ_REDIRECT_ENV.some(k => host.env[k] !== undefined)) return null;
    const written = writtenArgs(cmd);
    if (!written || !written.every(isLiteralShellWord) || cmd.args.some(a => a.includes('\\'))) return null;

    const target = psqlTarget(cmd.args);
    if (!target || (!target.noPsqlrc && !assumeNoPsqlrc)) return null;
    if (!target.host || !target.port || !/^\d{1,5}$/.test(target.port)) return null;
    const port = Number(target.port);
    if (port < 1 || port > 65535) return null;

    if (target.host.startsWith('/')) {
        const dir = target.host.replace(/(.)\/+$/, '$1');
        // libpq splits a host list on commas and tries each entry.
        if ((dir !== '/tmp' && !dir.startsWith('/tmp/')) || dir.includes(',') || pathNormalize(dir) !== dir) return null;
        const socket = `${dir}/.s.PGSQL.${port}`;
        return postgresListening(host, socket, unixListenerInodes(host, socket));
    }
    if (target.host !== '127.0.0.1' && target.host !== '::1') return null;
    return postgresListening(host, `${target.host}:${port}`, tcpListenerInodes(host, target.host, port));
}

// ── Git hook bypass ──────────────────────────────────────────────────────────
// A repo's commit and push hooks are where its own gates run — the public
// boundary scan, formatting, parity. An agent that trips one fixes the finding;
// it never switches the hook off. Every way of switching hooks off is refused:
// `--no-verify` (and `git commit -n`), a `core.hooksPath` override on the
// command line or through the environment, a `core.hooksPath` write, and the
// husky skip variables. Reading `core.hooksPath` stays allowed.
export const GIT_HOOK_BYPASS_REASON =
    'Skipping or disabling git hooks is not allowed: a hook is the repo\'s own gate. Fix what it reports, then commit or push normally.';
const GIT_NO_VERIFY_LONG_RE = /^--no-veri(?:f|fy)?$/;
const GIT_NO_VERIFY_SUBCOMMANDS = new Set(['commit', 'push', 'merge', 'am', 'rebase', 'cherry-pick', 'revert', 'pull']);
// core.hooksPath switches every hook off; bootstrap.boundaryChecker points this
// repo's hooks at the public-boundary checker (empty or unset skips the scan).
const GIT_HOOK_CONFIG_KEY_RE = /^(?:core\.hookspath|bootstrap\.boundarychecker)$/i;
const GIT_HOOK_CONFIG_SECTION_RE = /^(?:core|bootstrap)$/i;
// `git commit` short options that take a value: the rest of a cluster (or the
// next argument) is that value, never another flag.
const GIT_COMMIT_VALUE_SHORT = new Set(['m', 'F', 'C', 'c', 't', 'u', 'S']);
const GIT_COMMIT_VALUE_LONG = new Set([
    '--message', '--file', '--author', '--date', '--reuse-message', '--reedit-message',
    '--template', '--fixup', '--squash', '--cleanup', '--trailer', '--pathspec-from-file',
]);
const GIT_CONFIG_VALUE_OPTS = new Set(['-f', '--file', '--blob', '--type', '--default', '--comment', '--value']);
const GIT_CONFIG_WRITE_OPTS = new Set(['--unset', '--unset-all', '--replace-all', '--add']);
const GIT_CONFIG_SECTION_OPTS = new Set(['--rename-section', '--remove-section']);
const GIT_CONFIG_READ_OPTS = new Set(['--get', '--get-all', '--get-regexp', '--get-urlmatch', '--list', '-l']);
const GIT_CONFIG_ACTION_OPTS = new Set([...GIT_CONFIG_WRITE_OPTS, ...GIT_CONFIG_SECTION_OPTS, ...GIT_CONFIG_READ_OPTS]);

function envDisablesHooks(env: string[]): boolean {
    return env.some((entry) =>
        /^HUSKY=0$/.test(entry) ||
        /^HUSKY_SKIP_HOOKS=/.test(entry) ||
        /^GIT_CONFIG_PARAMETERS=.*(?:core\.hookspath|bootstrap\.boundarychecker)/i.test(entry) ||
        /^GIT_CONFIG_KEY_\d+=(?:core\.hookspath|bootstrap\.boundarychecker)$/i.test(entry),
    );
}

function gitCommitSkipsHooks(args: string[]): boolean {
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === '--') return false;
        if (GIT_NO_VERIFY_LONG_RE.test(arg)) return true;
        if (arg.startsWith('--')) {
            if (GIT_COMMIT_VALUE_LONG.has(arg)) i += 1;
            continue;
        }
        if (arg.startsWith('-') && arg.length > 1) {
            const letters = arg.slice(1);
            for (let j = 0; j < letters.length; j++) {
                const letter = letters[j];
                if (letter === 'n') return true;
                if (GIT_COMMIT_VALUE_SHORT.has(letter)) {
                    // A value-taking letter ends the cluster; a bare one takes the next arg.
                    if (j === letters.length - 1 && letter !== 'u' && letter !== 'S') i += 1;
                    break;
                }
            }
        }
    }
    return false;
}

function gitConfigWritesHookConfig(args: string[]): boolean {
    const positionals: string[] = [];
    // git config takes ONE action option; a later one replaces an earlier one and
    // `--no-<action>` clears it, leaving the positional form to decide.
    let mode: 'read' | 'write' | 'section' | null = null;
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (GIT_CONFIG_VALUE_OPTS.has(arg)) { i += 1; continue; }
        // An editor session can rewrite any key unseen.
        if (arg === '-e' || arg === '--edit') return true;
        if (GIT_CONFIG_WRITE_OPTS.has(arg)) { mode = 'write'; continue; }
        if (GIT_CONFIG_SECTION_OPTS.has(arg)) { mode = 'section'; continue; }
        if (GIT_CONFIG_READ_OPTS.has(arg)) { mode = 'read'; continue; }
        if (arg.startsWith('--no-') && GIT_CONFIG_ACTION_OPTS.has(`--${arg.slice('--no-'.length)}`)) { mode = null; continue; }
        if (arg.startsWith('-')) continue;
        positionals.push(arg);
    }
    const [verb, ...rest] = positionals;
    if (verb === 'edit') return true;
    // Removing or renaming the whole section drops the key with it.
    if (verb === 'remove-section' || verb === 'rename-section') {
        return GIT_HOOK_CONFIG_SECTION_RE.test(rest[0] ?? '');
    }
    if (mode === 'section') return GIT_HOOK_CONFIG_SECTION_RE.test(verb ?? '');
    if (verb === 'set' || verb === 'unset') return rest.some((p) => GIT_HOOK_CONFIG_KEY_RE.test(p));
    if (verb === 'get' || verb === 'list') return false;
    const keyIndex = positionals.findIndex((p) => GIT_HOOK_CONFIG_KEY_RE.test(p));
    if (keyIndex === -1) return false;
    if (mode === 'write') return true;
    // `git config --get <key> <value-pattern>` is a read with a filter.
    if (mode === 'read') return false;
    return positionals.length > keyIndex + 1;
}

/** Reason to refuse `cmd` because it skips or disables git hooks, or null. */
export function gitHookBypassReason(cmd: ResolvedCommand): string | null {
    if (cmd.name === 'export' && envDisablesHooks(cmd.args)) return GIT_HOOK_BYPASS_REASON;
    if (cmd.name !== 'git') return null;
    if (envDisablesHooks(cmd.env ?? [])) return GIT_HOOK_BYPASS_REASON;

    const sub = gitSubcommandIndex(cmd.args);
    const overridesHookConfig = (assignment: string) =>
        GIT_HOOK_CONFIG_KEY_RE.test(assignment.split('=')[0] ?? '');
    for (let i = 0; i < sub; i++) {
        const arg = cmd.args[i];
        if ((arg === '-c' || arg === '--config-env') && overridesHookConfig(cmd.args[i + 1] ?? '')) {
            return GIT_HOOK_BYPASS_REASON;
        }
        if (arg.startsWith('-c') && arg.length > 2 && overridesHookConfig(arg.slice(2))) return GIT_HOOK_BYPASS_REASON;
        if (arg.startsWith('--config-env=') && overridesHookConfig(arg.slice('--config-env='.length))) {
            return GIT_HOOK_BYPASS_REASON;
        }
    }

    const subcommand = cmd.args[sub];
    const rest = cmd.args.slice(sub + 1);
    // `commit` is parsed with its argument roles (`-m --no-verify` is a message).
    if (subcommand === 'commit') return gitCommitSkipsHooks(rest) ? GIT_HOOK_BYPASS_REASON : null;
    if (subcommand && GIT_NO_VERIFY_SUBCOMMANDS.has(subcommand) && rest.some((a) => GIT_NO_VERIFY_LONG_RE.test(a))) {
        return GIT_HOOK_BYPASS_REASON;
    }
    if (subcommand === 'config' && gitConfigWritesHookConfig(rest)) return GIT_HOOK_BYPASS_REASON;
    return null;
}

// ── Hard block checks ────────────────────────────────────────────────────────

/** Returns block reason if the command is unconditionally blocked, null otherwise */
export function checkHardBlock(cmd: ResolvedCommand): string | null {
    // find -exec rm (and any other blocked command it runs) / find -delete
    // find -exec rm and xargs rm, and anything else they run that is blocked on its own
    for (const { via, inner } of execRuns(cmd)) {
        const reason = innerHardBlock(inner);
        if (reason === RUNS_RM) return `${via === 'xargs' ? 'xargs' : 'find -exec'} rm is not allowed. Use trash for file deletion.`;
        if (reason) return `${via} runs a blocked command. ${reason}`;
    }
    const client = clientProgramBlock(cmd);
    if (client) return client;
    if (cmd.name === 'find' && cmd.args.includes('-delete')) {
        return 'find -delete permanently deletes files. Use trash instead.';
    }

    // Shell -c / here-string wrappers — bypass vectors for all other checks
    if (SHELLS.has(cmd.name)) {
        if (shellScript(cmd.name, cmd.args) || cmd.hasInputRedirect) {
            return 'Shell inline execution (shell -c, here-strings) is not allowed. Run commands directly.';
        }
    }

    const hookBypass = gitHookBypassReason(cmd);
    if (hookBypass) return hookBypass;

    // Simple dangerous commands
    if (cmd.name === 'eval') return 'eval is not allowed. Run commands directly.';
    if (cmd.name === 'unlink') return 'unlink permanently deletes files. Use: trash <path>';
    if (cmd.name === 'shred') return 'shred permanently destroys file content. Use: trash <path>';
    if (cmd.name === 'truncate') return 'truncate destroys file content.';

    return null;
}

// ── Self-matching kills ──────────────────────────────────────────────────────

/** pgrep/pkill options that take a value, either as the next argument or attached to the short flag. */
const PGREP_VALUE_SHORT = new Set(['d', 'g', 'G', 'P', 's', 't', 'u', 'U', 'F', 'r', 'O', 'q']);
const PGREP_VALUE_LONG = new Set([
    '--delimiter', '--pgroup', '--group', '--parent', '--session', '--terminal', '--euid', '--uid',
    '--pidfile', '--signal', '--ns', '--nslist', '--cgroup', '--env', '--runstates', '--older', '--queue',
]);
/** pkill's `-9`, `-KILL`, `-SIGTERM`: a signal, not a cluster of short options. */
const PKILL_SIGNAL_ARG = /^-(?:\d+|SIG[A-Z0-9+-]+|[A-Z][A-Z0-9+-]+)$/;

interface PgrepArgs {
    /** `-f`/`--full`: match the whole command line, including the shell that runs this command. */
    full: boolean;
    ignoreCase: boolean;
    /** `-A`/`--ignore-ancestors` (procps-ng 4): the calling shell is excluded, so the pattern may match it. */
    ignoreAncestors: boolean;
    pattern: string | undefined;
}

function parsePgrepArgs(args: string[]): PgrepArgs {
    const parsed: PgrepArgs = { full: false, ignoreCase: false, ignoreAncestors: false, pattern: undefined };
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a === '--') {
            parsed.pattern ??= args[i + 1];
            break;
        }
        if (a.startsWith('--')) {
            const name = a.split('=')[0];
            if (name === '--full') parsed.full = true;
            if (name === '--ignore-case') parsed.ignoreCase = true;
            if (name === '--ignore-ancestors') parsed.ignoreAncestors = true;
            if (PGREP_VALUE_LONG.has(name) && !a.includes('=')) i += 1;
            continue;
        }
        if (a.startsWith('-') && a.length > 1) {
            if (PKILL_SIGNAL_ARG.test(a)) continue;
            for (let j = 1; j < a.length; j++) {
                const flag = a[j];
                if (flag === 'f') parsed.full = true;
                if (flag === 'i') parsed.ignoreCase = true;
                if (flag === 'A') parsed.ignoreAncestors = true;
                if (PGREP_VALUE_SHORT.has(flag)) {
                    if (j === a.length - 1) i += 1;
                    break;
                }
            }
            continue;
        }
        parsed.pattern ??= a;
    }
    return parsed;
}

/**
 * Whether a `-f` pattern, as pgrep/pkill would compile it, matches `ownText`: the calling shell's command line, which
 * contains this command verbatim. An expression JavaScript cannot compile counts as matching, so the check fails closed.
 */
function isSelfMatchingFullPattern(cmd: ResolvedCommand, ownText: string): boolean {
    const { full, ignoreCase, ignoreAncestors, pattern } = parsePgrepArgs(cmd.args);
    if (!full || ignoreAncestors || pattern === undefined) return false;
    try {
        return new RegExp(pattern, ignoreCase ? 'i' : '').test(ownText);
    } catch {
        return true;
    }
}

const SELF_KILL_REASON =
    'matches the full command line of every process, including the shell running this command, so it can kill ' +
    "its own caller. Write the pattern so its own text cannot match it, e.g. a bracket class: pkill -f '[s]erver.js', " +
    'or add -A (--ignore-ancestors) where procps-ng supports it.';

/** The commands inside a `$(...)` or backtick argument, which the argument walker leaves as text. */
function substitutionCommands(arg: string): ResolvedCommand[] {
    const m = arg.match(/^\$\(([\s\S]*)\)$/) ?? arg.match(/^`([\s\S]*)`$/);
    return m ? extractCommands(m[1]) : [];
}

/** pkill -f, or kill fed by pgrep -f, whose pattern also matches the calling shell. */
export function selfMatchingKillReason(commands: ResolvedCommand[], ownText: string): string | null {
    for (const cmd of commands) {
        if (cmd.name === 'pkill' && isSelfMatchingFullPattern(cmd, ownText)) return `pkill -f ${SELF_KILL_REASON}`;
    }
    const fedToKill = commands
        .filter(c => c.name === 'kill')
        .flatMap(c => c.args.flatMap(substitutionCommands));
    const pipedToKill = commands.some(c => c.name === 'xargs' && c.args.includes('kill'))
        || (commands.some(c => c.name === 'kill') && /\|\s*while\s+(?:IFS=\S*\s+)?read\b/.test(ownText));
    if (pipedToKill) fedToKill.push(...commands);
    if (fedToKill.some(c => c.name === 'pgrep' && isSelfMatchingFullPattern(c, ownText))) {
        return `kill fed by pgrep -f ${SELF_KILL_REASON}`;
    }
    return null;
}

// ── Staging everything during a conflicted operation ─────────────────────────

const IN_PROGRESS_MARKERS: ReadonlyArray<[string, string]> = [
    ['MERGE_HEAD', 'merge'],
    ['CHERRY_PICK_HEAD', 'cherry-pick'],
    ['REVERT_HEAD', 'revert'],
    ['rebase-merge', 'rebase'],
    ['rebase-apply', 'rebase'],
];

/** The git dir for `start`: a `.git` directory, or the `gitdir:` a worktree's `.git` file points at. */
function gitDirFor(start: string): string | null {
    let dir = start;
    for (;;) {
        const dotGit = join(dir, '.git');
        try {
            const st = statSync(dotGit);
            if (st.isDirectory()) return dotGit;
            if (st.isFile()) {
                const m = readFileSync(dotGit, 'utf-8').match(/^gitdir:\s*(.+?)\s*$/m);
                if (m) return pathResolve(dir, m[1]);
            }
        } catch { /* no .git here */ }
        const parent = dirname(dir);
        if (parent === dir) return null;
        dir = parent;
    }
}

function operationInGitDir(gitDir: string): string | null {
    for (const [marker, operation] of IN_PROGRESS_MARKERS) {
        if (existsSync(join(gitDir, marker))) return operation;
    }
    return null;
}

export function inProgressGitOperation(dir: string): string | null {
    const gitDir = gitDirFor(dir);
    return gitDir ? operationInGitDir(gitDir) : null;
}

/**
 * The repository a git command acts on: `env -C`, cumulative global `-C`, `--git-dir` and `--work-tree` in either
 * spelling, and `GIT_DIR` / `GIT_WORK_TREE` assignments. Relative values resolve against the final `-C` directory.
 */
function gitRepoTarget(cmd: ResolvedCommand, cwd: string): { gitDir: string | null; workDir: string } {
    let base = cmd.chdir ? pathResolve(cwd || '/', cmd.chdir) : cwd;
    let gitDir: string | null = null;
    let workTree: string | null = null;
    for (const assignment of cmd.env ?? []) {
        const m = assignment.match(/^(GIT_DIR|GIT_WORK_TREE)=(.*)$/);
        if (m?.[1] === 'GIT_DIR') gitDir = m[2];
        if (m?.[1] === 'GIT_WORK_TREE') workTree = m[2];
    }
    const args = cmd.args;
    for (let i = 0; i < args.length && args[i].startsWith('-'); i++) {
        const eq = args[i].match(/^(--git-dir|--work-tree)=(.*)$/);
        const option = eq ? eq[1] : args[i];
        const value = eq ? eq[2] : args[i + 1];
        if (!eq && GIT_GLOBAL_VALUE_OPTS.has(option)) i += 1;
        if (value === undefined) continue;
        if (option === '-C') base = pathResolve(base || '/', value);
        else if (option === '--git-dir') gitDir = value;
        else if (option === '--work-tree') workTree = value;
    }
    const at = (p: string) => pathResolve(base || '/', p);
    return { gitDir: gitDir === null ? null : at(gitDir), workDir: workTree === null ? base : at(workTree) };
}

/** Whether a short-option cluster sets `flag` before reaching an option whose value is attached (`-m"msg"`). */
function clusterSets(arg: string, flag: string, valueFlags: string): boolean {
    if (!/^-[^-]/.test(arg)) return false;
    for (const c of arg.slice(1)) {
        if (c === flag) return true;
        if (valueFlags.includes(c)) return false;
    }
    return false;
}

const STAGE_EVERYTHING_PATHSPECS = new Set(['.', './', ':/', ':/.', '*']);

function stagesEverything(args: string[]): string | null {
    const i = gitSubcommandIndex(args);
    const sub = args[i];
    const rest = args.slice(i + 1);
    if (sub === 'add' || sub === 'stage') {
        const all = rest.find(a => a === '--all' || a === '--update' || STAGE_EVERYTHING_PATHSPECS.has(a)
            || clusterSets(a, 'A', '') || clusterSets(a, 'u', ''));
        return all ? `git ${sub} ${all}` : null;
    }
    if (sub === 'commit') {
        const all = rest.find(a => a === '--all' || clusterSets(a, 'a', 'mFCctSu'));
        return all ? `git commit ${all}` : null;
    }
    return null;
}

/** git add -A / commit -a while a merge, rebase, cherry-pick or revert is in progress stages conflict markers. */
export function stageAllDuringConflictReason(cmd: ResolvedCommand, cwd: string): string | null {
    if (cmd.name !== 'git') return null;
    const form = stagesEverything(cmd.args);
    if (!form) return null;
    const { gitDir, workDir } = gitRepoTarget(cmd, cwd);
    if (!gitDir && !workDir) return null;
    const operation = gitDir ? operationInGitDir(gitDir) : inProgressGitOperation(workDir);
    if (!operation) return null;
    return `${form} during an in-progress ${operation} stages conflicted files with their markers. ` +
        'Stage the resolved paths by name (git add <path>...), or abort the operation.';
}

// ── Gated checks ─────────────────────────────────────────────────────────────

/** True when `-<ch>` is given alone or inside a short-option cluster such as `-uf`, before any value-taking letter in `valueFlags`. */
function hasShortFlag(args: string[], ch: string, valueFlags = ''): boolean {
    return args.some(a => /^-[A-Za-z0-9]/.test(a) && clusterSets(a, ch, valueFlags));
}

// `git push` options that take a value, and the short letters among them.
const GIT_PUSH_VALUE_OPTS = new Set(['-o', '--push-option', '--repo', '--receive-pack', '--exec']);
const GIT_PUSH_SHORT_VALUE_FLAGS = 'o';

/** `git push` arguments with every option value removed, so a value is never read as a flag or refspec. Everything from `--` on is kept: those are operands. */
function pushArgsWithoutValues(args: string[]): string[] {
    const out: string[] = [];
    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--') return [...out, ...args.slice(i)];
        if (GIT_PUSH_VALUE_OPTS.has(args[i])) { i++; continue; }
        out.push(args[i]);
    }
    return out;
}

// AWS CLI global options that take a value; they may come before the service.
const AWS_GLOBAL_VALUE_OPTS = new Set([
    '--profile', '--region', '--output', '--endpoint-url', '--query', '--ca-bundle',
    '--cli-read-timeout', '--cli-connect-timeout', '--color', '--cli-binary-format',
]);

/** `aws [global options] <service> <operation> …` → [service, operation, index of operation in args (-1 when absent)]. */
export function awsServiceAndOperation(args: string[]): [string, string, number] {
    const positional: string[] = [];
    let opIndex = -1;
    for (let i = 0; i < args.length && positional.length < 2; i++) {
        const a = args[i];
        if (!a.startsWith('-')) {
            positional.push(a);
            if (positional.length === 2) opIndex = i;
        } else if (AWS_GLOBAL_VALUE_OPTS.has(a)) i++;
    }
    return [positional[0] ?? '', positional[1] ?? '', opIndex];
}

// A psql backslash command runs to the end of its line. The statement before it may continue past it (`\set` between
// two SQL lines) or end at it (`\g`), so the SQL is also read with each one removed and with each one ending a statement.
const PSQL_BACKSLASH_TO_LINE_END = /\\[^\s\\][^\n]*/g;

function psqlStatementTexts(text: string): string[] {
    if (!text.includes('\\')) return [text];
    // `\\` ends a backslash command's arguments, and SQL may follow it on the same line.
    const separated = text.replace(/\\\\/g, '\n');
    return [text, separated.replace(PSQL_BACKSLASH_TO_LINE_END, ''), separated.replace(PSQL_BACKSLASH_TO_LINE_END, ';')];
}

/** Returns gate reason if the command requires approval, null otherwise */
const CF_DESTRUCTIVE_VERB = /^(?:[a-z]+-)*(?:delete|purge|destroy|remove|reset|revoke|roll|rollback|terminate|clear|rotate|invalidate|replace)(?:[-A-Z][-A-Za-z]*)?$/;

export function checkGatedCommand(cmd: ResolvedCommand): string | null {
    const { name, args } = cmd;

    // ── Databases ────────────────────────────────────────────────────────

    // SQL CLIs: scan each arg for the realistic destructive paths an agent can
    // emit. Coverage and false-positive guards live in findDestructiveSqlStatement.
    const sqlDialect = SQL_CLIS[name] ?? (name === 'snow' && args[0] === 'sql' ? 'Snowflake' : null);
    if (sqlDialect) {
        const input = sqlInputFor(cmd);
        if (input.unreadable) return `${sqlDialect} SQL input (${input.unreadable}) can't be checked: too large, too many included files, more text than the guard traces, or not readable before the line runs.`;
        const program = clientProgramGate(cmd);
        if (program) return program;
        if (name === 'snow' && snowTemplating(cmd).some(t => t === 'JINJA' || t === 'ALL')) {
            return 'Snowflake SQL with Jinja templating can\'t be checked: snow renders it into new SQL before it runs.';
        }
        // STANDARD (`<% %>`) and LEGACY (`&{ }`) templating are on by default, and a value -D doesn't give comes from
        // --env or project config the line doesn't show.
        const templating = name === 'snow' ? snowTemplating(cmd) : [];
        if (name === 'snow' && !(templating.length && templating.every(t => t === 'NONE')) && input.texts.some(t => unfilledSnowTemplate(t, cmd))) {
            return 'Snowflake SQL with a template can\'t be checked: snow fills it in before it runs.';
        }
        if (name === 'snow' && input.texts.some(t => /^\s*!(?:source|load)\s+\w+:\/\//im.test(t))) {
            return 'Snowflake SQL that snow fetches from a URL (!source/!load) can\'t be checked before it runs.';
        }
        for (const text of input.texts) {
            for (const statements of name === 'psql' ? psqlStatementTexts(text) : [text]) {
                const matched = findDestructiveSqlStatement(statements)
                    ?? (name === 'snow' && !splitsLikeSnow(statements) ? destructiveKeywordAnywhere(statements) : null);
                if (matched) {
                    return `Destructive ${sqlDialect} SQL detected (${matched.pattern}) — ${matched.statement}`;
                }
            }
        }
    }

    // MongoDB
    if ((name === 'mongosh' || name === 'mongo') && args.some(a => DESTRUCTIVE_MONGO.test(a))) {
        return 'Destructive MongoDB command detected (drop/deleteMany/remove).';
    }

    // Redis
    if (name === 'redis-cli' && args.some(a => /^(?:FLUSHDB|FLUSHALL)$/i.test(a))) {
        return 'Destructive Redis command detected (FLUSHDB/FLUSHALL).';
    }

    // ── Cloud providers ──────────────────────────────────────────────────

    if (name === 'aws') {
        const [service, operation] = awsServiceAndOperation(args);
        if (service === 's3' && ['rm', 'rb'].includes(operation)) {
            return 'Destructive AWS S3 command (rm/rb).';
        }
        if (/^(?:terminate|delete)/.test(operation || '')) {
            return 'Destructive AWS CLI command detected.';
        }
    }
    if (name === 'gcloud' && args.includes('delete')) {
        return 'Destructive gcloud command detected.';
    }
    if (name === 'gsutil' && ['rm', 'rb'].includes(args[0])) {
        return 'Destructive gsutil command (rm/rb).';
    }
    if (name === 'az' && args.includes('delete')) {
        return 'Destructive Azure CLI command detected.';
    }
    if (name === 'doctl' && args.some(a => a === 'delete' || a === 'destroy')) {
        return 'Destructive DigitalOcean CLI command detected.';
    }

    // ── Infrastructure as Code ───────────────────────────────────────────

    if (name === 'terraform') {
        if (args[0] === 'destroy') return 'Destructive Terraform command (destroy).';
        if (args[0] === 'apply' && args.includes('-auto-approve')) {
            return 'Destructive Terraform command (apply -auto-approve).';
        }
    }
    if (name === 'pulumi' && args[0] === 'destroy') return 'Pulumi destroy detected.';
    if (name === 'cdk' && args[0] === 'destroy') return 'CDK destroy detected.';

    // ── Containers / orchestration ───────────────────────────────────────

    if (name === 'kubectl' && ['delete', 'drain', 'cordon'].includes(args[0])) {
        return 'Destructive kubectl command.';
    }
    if (name === 'docker') {
        if (['rm', 'rmi'].includes(args[0])) return 'Destructive Docker command.';
        if (args[0] === 'system' && args[1] === 'prune') return 'Destructive Docker command.';
        if (['volume', 'container', 'image'].includes(args[0]) && args[1] === 'rm') {
            return 'Destructive Docker command.';
        }
    }
    if (name === 'helm' && ['uninstall', 'delete'].includes(args[0])) {
        return 'Destructive Helm command.';
    }

    // ── Platform CLIs ────────────────────────────────────────────────────

    // Data-driven platform CLIs (shared verb-set lookup)
    const platformVerbs = name === 'render' ? undefined : PLATFORM_DESTRUCTIVE[name];
    if (platformVerbs && args.some(a => platformVerbs.has(a))) {
        return `Destructive ${name} CLI command.`;
    }
    if (name === 'render') {
        const change = renderChangeReason(args);
        if (change) return change;
    }

    // Platform CLIs with custom logic
    if (name === 'heroku' && args.some(a => a === 'destroy' || a === 'pg:reset' || a.includes(':destroy'))) {
        return 'Destructive Heroku CLI command.';
    }
    if (name === 'vercel' && ['remove', 'rm'].includes(args[0])) {
        return 'Destructive Vercel CLI command.';
    }
    if (name === 'netlify' && args.some(a => a === 'sites:delete')) {
        return 'Destructive Netlify CLI command.';
    }
    if (name === 'supabase') {
        if (args.includes('delete')) return 'Destructive Supabase CLI command.';
        if (args[0] === 'db' && args[1] === 'reset') return 'Destructive Supabase CLI command.';
    }

    // ── Service CLIs ─────────────────────────────────────────────────────

    if (name === 'gh' && args[0] === 'repo' && args[1] === 'delete') {
        return 'Destructive GitHub CLI command (repo delete).';
    }
    if (name === 'wrangler' && args.includes('delete')) {
        return 'Destructive Cloudflare Wrangler command.';
    }
    // `cf <product> [group…] <operation>` is generated from the whole Cloudflare API, so the
    // destructive operations are matched by verb rather than listed. `cli` (search) and `schema`
    // only describe commands; their arguments name an operation without running it.
    if ((name === 'cf' || name === 'cloudflare') && !['cli', 'schema'].includes(args[0])
        && !args.includes('--dry-run') && !args.includes('--help') && !args.includes('-h')) {
        const operation = args.find(a => !a.startsWith('-') && CF_DESTRUCTIVE_VERB.test(a));
        if (operation) return `Destructive Cloudflare cf command (${operation}).`;
    }
    if (name === 'firebase' && args.some(a => ['projects:delete', 'firestore:delete', 'hosting:disable'].includes(a))) {
        return 'Destructive Firebase CLI command.';
    }

    // ── Git (remote history mutation) ────────────────────────────────────
    // (fleet-hardening P2) Raw `git push --force` was the one unclassified
    // history-mutation path: the MCP git_push tool is lease-protected, but a
    // Bash force push was invisible to the matrix, and server-side branch
    // protection is unavailable on free-plan private repos — this gate is the
    // enforcement point. `--force-with-lease`/`--force-if-includes` stay
    // allowed: they refuse to clobber unseen remote work and are the
    // sanctioned recovery path the git_push tool itself uses.
    if (name === 'git') {
        // Skip git's global options so `git -C /x push -f` classifies like `git push -f`.
        const i = gitSubcommandIndex(args);
        if (args[i] === 'push') {
            const pushArgs = pushArgsWithoutValues(args.slice(i + 1));
            const end = pushArgs.indexOf('--');
            const options = end === -1 ? pushArgs : pushArgs.slice(0, end);
            if (options.includes('--force') || hasShortFlag(options, 'f', GIT_PUSH_SHORT_VALUE_FLAGS)) {
                return 'git push --force rewrites remote history. Use --force-with-lease (refuses to clobber unseen work) or get approval.';
            }
            if (options.includes('--mirror')) {
                return 'git push --mirror force-updates every remote ref.';
            }
            if (options.includes('--prune')) {
                return 'git push --prune deletes every remote ref, in the refspecs pushed, that has no local counterpart.';
            }
            // `+refspec` is per-ref force; `:refspec` deletes the remote ref.
            if (options.includes('--delete') || hasShortFlag(options, 'd', GIT_PUSH_SHORT_VALUE_FLAGS) ||
                pushArgs.some(a => (a.startsWith(':') || a.startsWith('+')) && a.length > 1)) {
                return 'git push deleting or force-updating a remote ref (+/: refspec, --delete).';
            }
        }
    }
    // git's own `git-clean` program, run by path from its exec dir, is the same command as `git clean`.
    const cleanArgs = name === 'git' && args[gitSubcommandIndex(args)] === 'clean' ? args.slice(gitSubcommandIndex(args) + 1)
        : name === 'git-clean' ? args
        : null;
    if (cleanArgs) {
        // Gated unless it is a dry run, -f or not: `clean.requireForce=false` lets it delete without -f.
        const clean = parseGitClean(cleanArgs);
        // The exemption holds only for words the shell passes as written: a variable, glob or brace can expand to
        // `--no-dry-run` (an untracked file of that name matches `*`).
        const end = cleanArgs.indexOf('--');
        const literal = cleanArgs.slice(0, end < 0 ? undefined : end).every(a => /^[\w@%+=:,./ -]*$/.test(a));
        const globalHelp = name === 'git' && args.slice(0, gitSubcommandIndex(args)).some(a => a === '--help' || a === '-h');
        if (!globalHelp && ((!clean.dryRun && !clean.help) || !literal)) {
            return 'git clean permanently deletes untracked files (with -x, ignored ones such as .env too). They skip the trash and cannot be recovered.';
        }
    }

    // ── dbt ──────────────────────────────────────────────────────────────

    if (name === 'dbt' && ['run', 'build'].includes(args[0]) && args.includes('--full-refresh')) {
        return 'dbt --full-refresh drops and recreates tables.';
    }

    // ── dd (disk overwrite) ──────────────────────────────────────────────

    if (name === 'dd' && args.some(a => a.startsWith('if='))) {
        return 'dd with input file — potential disk overwrite.';
    }

    return null;
}

// ── Approval description ─────────────────────────────────────────────────────
// The gate verdict above decides; this section only explains it to the human
// who has to approve. It never changes what is gated. The text is plain so it
// reads the same in whatever approval surface the harness uses.

export interface GateCard {
    label: string;
    summary: string;
}

interface StepCard {
    label: string;
    lines: string[];
    dir?: string;
    /** `inDir`: the step acts on files in the directory it runs in, so the plain sentence names it before `note`. */
    plain: PlainEffect & { inDir?: boolean; note?: string };
}

const STATEMENT_MAX_CHARS = 4000;

/**
 * True when Snowflake's connector splits `sql` into the statements the guard's scanner sees. The connector treats `//`
 * as a comment (except in a word holding `://`), `\\` as an escape in quotes, a line starting with `!` as a client
 * command that ends the statement before it, and `;>` as an async statement end; neither it nor Snowflake treats
 * `$tag$` or a backtick as a quote. Text holding any of them can hide a statement from the scanner.
 */
function splitsLikeSnow(sql: string): boolean {
    return !/[$`\\]|\/\/|\/\*|;\s*>|^\s*!/m.test(sql);
}

const UNANCHORED_DESTRUCTIVE_SQL = [
    ...DESTRUCTIVE_SQL_PATTERNS.map(p => ({ rx: new RegExp(p.rx.source.replace(/^\^/, '\\b'), 'i'), label: p.label })),
    { rx: /\bUPDATE\b[\s\S]*\bSET\b/i, label: 'UPDATE' },
];

/**
 * A destructive keyword anywhere in `sql`, inside literals and comments too, and with every comment also read as the
 * whitespace it may stand for between two keywords: for text the scanner can't split.
 */
function destructiveKeywordAnywhere(sql: string): DestructiveMatch | null {
    const collapsed = sql.replace(/\/\*[\s\S]*?(?:\*\/|$)|(?:--|\/\/)[^\n]*/g, ' ');
    for (const text of [sql, collapsed]) {
        for (const { rx, label } of UNANCHORED_DESTRUCTIVE_SQL) {
            const m = rx.exec(text);
            if (m) return { pattern: label, statement: oneLine(text.slice(m.index, m.index + 200)) };
        }
    }
    return null;
}

/** A destructive statement as the description reads it. `statement` is what the gate saw, for decisions keyed on it. */
interface FoundStatement extends DestructiveMatch {
    /** The statement from its verb on, past leading whitespace, comments and block words such as BEGIN. */
    text: string;
    /** `text` with literals and comments blanked, offsets matching. */
    skeleton: string;
    /** False when a literal or comment in it never closes, or it comes from a guessed reading of the input. */
    parsed: boolean;
}

/** Where a statement's verb starts in its skeleton segment, past whitespace and block words such as BEGIN or IF … THEN. */
function statementStart(segment: string): number {
    const skip = (at: number) => at + segment.slice(at).length - segment.slice(at).trimStart().length;
    let at = skip(0);
    for (let i = 0; i < BLOCK_LEAD_MAX_STRIPS; i++) {
        const m = BLOCK_LEAD.exec(segment.slice(at));
        if (!m?.[0]) break;
        at = skip(at + m[0].length);
    }
    return at;
}

function sqlStatements(
    sql: string,
    outerParsed = true,
    { skeleton, openAt } = sqlSkeleton(sql),
): Array<{ segment: string; original: string; text: string; skeleton: string; parsed: boolean }> {
    const out = [];
    let offset = 0;
    for (const segment of skeleton.split(';')) {
        const end = offset + segment.length;
        const start = offset + statementStart(segment);
        out.push({
            segment,
            original: sql.slice(offset, end).trim(),
            text: sql.slice(start, end).trimEnd(),
            skeleton: skeleton.slice(start, end).trimEnd(),
            parsed: outerParsed && (openAt < 0 || end <= openAt),
        });
        offset = end + 1;
    }
    return out;
}

function destructiveStatements(sql: string, depth = 0, outerParsed = true): FoundStatement[] {
    if (depth > SQL_RECURSION_LIMIT || !SQL_PREFILTER.test(sql)) return [];
    const found: FoundStatement[] = [];
    const lexed = sqlSkeleton(sql);
    for (const { segment, original, text, skeleton, parsed } of sqlStatements(sql, outerParsed, lexed)) {
        for (const { body, isCTE } of decomposeSqlSegment(segment)) {
            const match = checkSqlBody(body, isCTE);
            if (match) {
                found.push({ pattern: match.pattern, statement: original, text, skeleton, parsed });
                break;
            }
        }
    }
    for (const literal of findExecuteImmediateLiterals(sql, lexed.skeleton)) {
        found.push(...destructiveStatements(literal, depth + 1, outerParsed && lexed.openAt < 0));
    }
    return found;
}

/** The condition after a statement's own WHERE (not one inside parentheses), as written, up to RETURNING. */
function topLevelWhere(text: string, skeleton: string): string | null {
    let depth = 0;
    let flat = '';
    for (let i = 0; i < skeleton.length; i++) {
        const c = skeleton[i];
        if (c === '(') depth++;
        flat += depth > 0 ? ' ' : c;
        if (c === ')' && depth > 0) depth--;
    }
    const where = /\bWHERE\b/i.exec(flat);
    if (!where) return null;
    const returning = /\bRETURNING\b/i.exec(flat.slice(where.index));
    const condition = oneLine(text.slice(where.index + where[0].length, returning ? where.index + returning.index : text.length));
    return condition || null;
}

const SQL_OBJECT = String.raw`([^\s;(]+)`;

/** The WHERE condition the other readings of the input give this same UPDATE or DELETE on `table`, when they agree. */
type WhereElsewhere = (verb: 'UPDATE' | 'DELETE', table: string) => string | null;

interface SqlEffect {
    title: string;
    effect: string;
    plain: string;
    /** Follows the database in the plain sentence. */
    note?: string;
    /** Overrides the dialect's usual answer to what could be lost. */
    loss?: string;
}

function sqlEffect(st: FoundStatement, dialect: string, whereElsewhere: WhereElsewhere): SqlEffect {
    const { pattern } = st;
    const s = oneLine(st.text.slice(0, STATEMENT_MAX_CHARS));
    const unsure = (verb: 'UPDATE' | 'DELETE', table: string, rows: string) => {
        const elsewhere = whereElsewhere(verb, table);
        return `${rows} The guard couldn't fully parse this statement, so it can't tell which rows, and the guard rule below may be misreading it.`
            + (elsewhere ? ` Read another way, it is limited to rows where ${code(clip(elsewhere, 160))}.` : '');
    };
    let m: RegExpMatchArray | null;
    if (pattern === 'DROP' && (m = s.match(new RegExp(String.raw`^DROP\s+(MATERIALIZED\s+VIEW|\w+)\s+(?:IF\s+EXISTS\s+)?` + SQL_OBJECT, 'i')))) {
        const kind = m[1].toLowerCase().replace(/\s+/g, ' ');
        const contents = kind === 'schema' || kind === 'database' ? ' and every table and view in it' : '';
        return {
            title: `Drop ${dialect} ${kind} ${m[2]}`,
            effect: `Deletes the ${kind} ${code(m[2])}${contents}, with all data.`,
            plain: `Deletes the ${kind} ${code(m[2])}${contents} and all its data`,
        };
    }
    if (pattern === 'TRUNCATE' && (m = s.match(new RegExp(String.raw`^TRUNCATE\s+(?:TABLE\s+)?(?:IF\s+EXISTS\s+)?` + SQL_OBJECT, 'i')))) {
        return { title: `Empty ${dialect} table ${m[1]}`, effect: `Deletes every row in ${code(m[1])}.`, plain: `Deletes every row of the table ${code(m[1])}` };
    }
    if (pattern === 'DELETE FROM' && (m = s.match(new RegExp(String.raw`^DELETE\s+FROM\s+` + SQL_OBJECT, 'i')))) {
        const title = `Delete rows from ${dialect} table ${m[1]}`;
        if (!st.parsed) {
            return { title, effect: unsure('DELETE', m[1], `Deletes rows in ${code(m[1])}.`), plain: `Deletes rows from the table ${code(m[1])}`, note: "(the guard couldn't tell which rows)" };
        }
        const where = topLevelWhere(st.text, st.skeleton);
        if (where) return { title, effect: `Deletes the rows in ${code(m[1])} where ${code(clip(where, 200))}.`, plain: `Deletes some rows from the table ${code(m[1])}` };
        return HAS_WHERE.test(st.skeleton)
            ? { title, effect: `Deletes rows in ${code(m[1])} chosen by a condition inside a subquery.`, plain: `Deletes rows from the table ${code(m[1])}` }
            : { title, effect: `Deletes every row in ${code(m[1])} (no WHERE clause).`, plain: `Deletes every row of the table ${code(m[1])}` };
    }
    if (pattern === 'CREATE OR REPLACE' && (m = s.match(new RegExp(String.raw`^CREATE\s+OR\s+REPLACE\s+((?:(?:TEMP|TEMPORARY|EXTERNAL|MATERIALIZED|TRANSIENT|SECURE)\s+)*\w+)\s+(?:IF\s+NOT\s+EXISTS\s+)?` + SQL_OBJECT, 'i')))) {
        const kind = m[1].toLowerCase().replace(/\s+/g, ' ');
        return /table/.test(kind)
            ? {
                title: `Replace ${dialect} ${kind} ${m[2]}`,
                effect: `If ${code(m[2])} already exists, it is dropped with all its rows and recreated from this statement.`,
                plain: `Replaces the table ${code(m[2])}, deleting every row it holds now`,
            }
            : {
                title: `Replace ${dialect} ${kind} ${m[2]}`,
                effect: `Overwrites the existing definition of ${kind} ${code(m[2])}.`,
                plain: `Replaces the ${kind} ${code(m[2])}`,
                loss: 'its old definition is lost unless it is saved somewhere else',
            };
    }
    if (pattern === 'INSERT OVERWRITE' && (m = s.match(new RegExp(String.raw`^INSERT\s+OVERWRITE\s+(?:INTO\s+)?(?:TABLE\s+)?` + SQL_OBJECT, 'i')))) {
        return {
            title: `Overwrite ${dialect} table ${m[1]}`,
            effect: `Deletes every row in ${code(m[1])} and replaces them with the query result.`,
            plain: `Replaces every row of the table ${code(m[1])}`,
        };
    }
    if (pattern === 'MERGE' && (m = s.match(new RegExp(String.raw`^MERGE\s+INTO\s+` + SQL_OBJECT, 'i')))) {
        return {
            title: `Merge into ${dialect} table ${m[1]}`,
            effect: `Inserts, updates or deletes rows in ${code(m[1])} as the MERGE rules say.`,
            plain: `Adds, changes or deletes rows in the table ${code(m[1])}`,
        };
    }
    if (pattern === 'ALTER ... DROP' && (m = s.match(new RegExp(String.raw`^ALTER\s+(\w+)\s+(?:IF\s+EXISTS\s+)?` + SQL_OBJECT + String.raw`[\s\S]*?\bDROP\s+((?:COLUMN|CONSTRAINT|PARTITION)\s+)?(?:IF\s+EXISTS\s+)?([^\s,;]+)`, 'i')))) {
        const what = `${(m[3] ?? '').toLowerCase()}${m[4]}`;
        return {
            title: `Drop ${what} from ${dialect} ${m[1].toLowerCase()} ${m[2]}`,
            effect: `Removes ${code(what)} from ${code(m[2])}; any data it held is deleted.`,
            plain: `Removes ${code(what)} and the data it holds from ${code(m[2])}`,
        };
    }
    if (pattern === 'UPDATE without WHERE' && (m = s.match(new RegExp(String.raw`^UPDATE\s+` + SQL_OBJECT, 'i')))) {
        return st.parsed
            ? {
                title: `Update every row in ${dialect} table ${m[1]}`,
                effect: `Rewrites every row in ${code(m[1])} (no WHERE clause).`,
                plain: `Changes every row of the table ${code(m[1])}`,
            }
            : {
                title: `Update rows in ${dialect} table ${m[1]}`,
                effect: unsure('UPDATE', m[1], `Changes rows in ${code(m[1])}.`),
                plain: `Changes rows in the table ${code(m[1])}`,
                note: "(the guard couldn't tell which rows)",
            };
    }
    return { title: `Run destructive ${dialect} SQL (${pattern})`, effect: `Runs a ${pattern} statement.`, plain: `Runs a ${pattern} statement that can delete or overwrite data` };
}

/** Every value of a flag, in `--flag value` and `--flag=value` forms. */
function flagValues(args: string[], names: string[]): string[] {
    const out: string[] = [];
    for (let i = 0; i < args.length; i++) {
        for (const name of names) {
            if (args[i] === name && i + 1 < args.length) out.push(args[i + 1]);
            else if (name.length > 2 && args[i].startsWith(`${name}=`)) out.push(args[i].slice(name.length + 1));
        }
    }
    return out;
}

function flagValue(args: string[], names: string[]): string | undefined {
    return flagValues(args, names)[0];
}

/** Values following a flag up to the next option: `--select a b c`. */
function flagList(args: string[], names: string[]): string[] {
    const out: string[] = [];
    for (let i = 0; i < args.length; i++) {
        for (const name of names) {
            if (args[i].startsWith(`${name}=`)) out.push(args[i].slice(name.length + 1));
            if (args[i] !== name) continue;
            for (let j = i + 1; j < args.length && !args[j].startsWith('-'); j++) out.push(args[j]);
        }
    }
    return out.flatMap(v => v.split(/[\s,]+/)).filter(Boolean);
}

function databaseParts(cmd: ResolvedCommand): Array<[string, string]> {
    const parts: Array<[string, string]> = [];
    if (cmd.name === 'snow') {
        const conn = flagValue(cmd.args, ['-c', '--connection']);
        const role = flagValue(cmd.args, ['--role']);
        const db = flagValue(cmd.args, ['--database', '--dbname']);
        if (conn) parts.push(['connection', conn]);
        if (role) parts.push(['role', role]);
        if (db) parts.push(['database', db]);
    } else if (cmd.name === 'psql') {
        const conninfo = cmd.args.find(a => /^postgres(?:ql)?:\/\/|\bhost=/.test(a)) ?? '';
        const host = flagValue(cmd.args, ['-h', '--host'])
            ?? conninfo.match(/\bhost=(\S+)/)?.[1]
            ?? conninfo.match(/^postgres(?:ql)?:\/\/(?:[^@/]*@)?([^/:?]+)/)?.[1];
        const db = flagValue(cmd.args, ['-d', '--dbname'])
            ?? conninfo.match(/\bdbname=(\S+)/)?.[1]
            ?? conninfo.match(/^postgres(?:ql)?:\/\/[^/]*\/([^?]+)/)?.[1];
        if (host) parts.push(['host', host]);
        if (db) parts.push(['database', db]);
    }
    return parts;
}

function databaseLine(cmd: ResolvedCommand): string | null {
    const parts = databaseParts(cmd).map(([k, v]) => `${k} ${code(v)}`);
    if (cmd.name === 'snow' && !databaseParts(cmd).some(([k]) => k === 'connection')) parts.unshift('default connection');
    return parts.length ? `Database: ${parts.join(' · ')}` : null;
}

/** Where a SQL client step runs, in words: "in the PostgreSQL database `app` on `db.example.test`". */
function databasePlace(cmd: ResolvedCommand, dialect: string): string {
    const parts = new Map(databaseParts(cmd));
    if (cmd.name === 'snow') return `in Snowflake (${parts.has('connection') ? `connection ${code(parts.get('connection')!)}` : 'the default connection'})`;
    const db = parts.get('database');
    const host = parts.get('host');
    return db || host ? `in the ${dialect} database${db ? ` ${code(db)}` : ''}${host ? ` on ${code(host)}` : ''}` : `in a ${dialect} database`;
}

function sqlStep(dialect: string, cmd: ResolvedCommand): StepCard {
    // psql may read a backslash command as running to the end of its line, which the gate also checks; a statement
    // only that reading finds was guessed at, not parsed.
    const readings = sqlInputOf(cmd).texts.flatMap(t => (cmd.name === 'psql' ? psqlStatementTexts(t) : [t]).map((text, i) => ({ text, guessed: i > 0 })));
    const segments = readings.map(r => (SQL_PREFILTER.test(r.text) ? sqlStatements(r.text) : []));
    // Per reading and target: the statements on that target, and how many of them come before each segment.
    const onTarget = new Map<string, { list: ReturnType<typeof sqlStatements>; before: number[] }>();
    const targetIn = (reading: number, verb: 'UPDATE' | 'DELETE', table: string) => {
        const key = `${reading} ${verb} ${table}`;
        let entry = onTarget.get(key);
        if (!entry) {
            const head = new RegExp(String.raw`^${verb === 'UPDATE' ? 'UPDATE' : String.raw`DELETE\s+FROM`}\s+${table.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?=[\s(]|$)`, 'i');
            const list: ReturnType<typeof sqlStatements> = [];
            const before: number[] = [];
            for (const seg of segments[reading]) {
                before.push(list.length);
                if (head.test(seg.skeleton)) list.push(seg);
            }
            onTarget.set(key, (entry = { list, before }));
        }
        return entry;
    };
    // The WHERE every other reading gives the `nth` UPDATE or DELETE on `table`, when each that reads it there parsed it
    // with one and they agree; a reading that parsed it without one means no WHERE is borrowed.
    const wheres = new Map<string, string | null>();
    const whereAt = (verb: 'UPDATE' | 'DELETE', table: string, nth: number): string | null => {
        const key = `${verb} ${table} ${nth}`;
        if (wheres.has(key)) return wheres.get(key)!;
        const found = new Set<string>();
        let vetoed = false;
        readings.forEach(({ guessed }, r) => {
            const st = guessed ? undefined : targetIn(r, verb, table).list[nth];
            if (!st?.parsed) return;
            const where = topLevelWhere(st.text, st.skeleton);
            if (where) found.add(where);
            else vetoed = true;
        });
        const where = !vetoed && found.size === 1 ? [...found][0] : null;
        wheres.set(key, where);
        return where;
    };
    // One statement read several ways is described once, but one that runs twice in a reading is listed twice. The text
    // of one the guard couldn't parse is unreliable past its verb and object, so it repeats any other unparsed statement
    // with the same title.
    const statements: Array<FoundStatement & { effect: SqlEffect }> = [];
    const listed = new Map<string, number>();
    readings.forEach(({ text, guessed }, r) => {
        const inReading = new Map<string, number>();
        const segs = segments[r];
        // Statements come in the order of their segments; one run from an EXECUTE IMMEDIATE literal matches none.
        let next = 0;
        for (const st of destructiveStatements(text)) {
            const found = { ...st, parsed: st.parsed && !guessed };
            let at = -1;
            for (let i = next; i < segs.length; i++) {
                if (segs[i].text === st.text && segs[i].skeleton === st.skeleton) {
                    at = i;
                    next = i + 1;
                    break;
                }
            }
            const whereElsewhere: WhereElsewhere = (verb, table) => (at < 0 ? null : whereAt(verb, table, targetIn(r, verb, table).before[at]));
            const effect = sqlEffect(found, dialect, whereElsewhere);
            const key = found.parsed ? `parsed\u0000${found.pattern}\u0000${oneLine(found.text)}` : `unparsed\u0000${effect.title}`;
            const n = (inReading.get(key) ?? 0) + 1;
            inReading.set(key, n);
            if (n <= (listed.get(key) ?? 0)) continue;
            listed.set(key, n);
            statements.push({ ...found, effect });
        }
    });
    const lines = statements.slice(0, 3).map((st, i) => `${i === 0 ? 'If you approve:' : 'And:'} ${st.effect.effect}`);
    const first = statements[0]?.effect;
    let label = first?.title ?? `Run destructive ${dialect} SQL`;
    if (statements.length > 1) label += ` (+${Math.min(statements.length, 3) - 1} more)`;
    const more = statements.length > 1 ? `, plus ${statements.length - 1} more statement${statements.length > 2 ? 's' : ''} that can delete or overwrite data` : '';
    const plain = first
        ? `${first.plain} ${databasePlace(cmd, dialect)}${first.note ? ` ${first.note}` : ''}${more}`
        : `Runs ${dialect} commands the guard couldn't fully check ${databasePlace(cmd, dialect)}, so it can't say what they change`;
    lines.push(dialect === 'Snowflake'
        ? 'Undo: only through Snowflake Time Travel or UNDROP, and only within the retention window.'
        : 'Undo: only from a backup.');
    const db = databaseLine(cmd);
    if (db) lines.push(db);
    return {
        label,
        lines,
        plain: {
            what: plain,
            loss: first?.loss ?? (dialect === 'Snowflake'
                ? 'only Snowflake Time Travel can bring back what it deletes or overwrites, and only for a limited time'
                : 'only a backup can bring back what it deletes or overwrites'),
        },
    };
}

function defaultDbtTarget(dir: string | undefined, cmd: ResolvedCommand): string | null {
    if (!dir) return null;
    const project = readConfigFile(join(dir, 'dbt_project.yml'));
    const profile = flagValue(cmd.args, ['--profile']) ?? project?.match(/^profile:\s*['"]?([\w.-]+)/m)?.[1];
    if (!profile) return null;
    const envDir = cmd.env?.find(e => e.startsWith('DBT_PROFILES_DIR='))?.slice('DBT_PROFILES_DIR='.length) ?? process.env.DBT_PROFILES_DIR;
    const candidates = [flagValue(cmd.args, ['--profiles-dir']), envDir, dir, join(HOME, '.dbt')].filter((d): d is string => !!d);
    for (const d of candidates) {
        const profiles = readConfigFile(join(d.startsWith('/') ? d : join(dir, d), 'profiles.yml'));
        if (!profiles) continue;
        const block = profiles.split(new RegExp(`^${profile.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}:\\s*$`, 'm'))[1];
        const target = block?.split(/^\S/m)[0].match(/^\s+target:\s*['"]?([\w.-]+)/m)?.[1];
        if (target) return target;
    }
    return null;
}

function dbtStep(cmd: ResolvedCommand, dir: string | undefined): StepCard {
    const models = flagList(cmd.args, ['--select', '-s', '--models', '-m']);
    const selector = flagValue(cmd.args, ['--selector']);
    const runtime = models.some(m => m.includes('$') || m.includes(FILLED));
    const what = selector ? `dbt models chosen by selector ${selector}`
        : runtime ? 'dbt models chosen at run time'
        : models.length === 1 ? `dbt model ${models[0]}`
        : models.length > 1 ? `${models.length} dbt models`
        : 'every dbt model in the project';
    const lines = [
        'If you approve: each selected incremental model (and seed) is dropped and rebuilt from source instead of updated in place. Rows that exist only from earlier incremental runs are lost.',
    ];
    if (models.length > 1 && !runtime) lines.push(`Models: ${code(clip(models.join(', '), 400))}`);
    const target = flagValue(cmd.args, ['--target', '-t']);
    const fallback = target ? null : defaultDbtTarget(dir, cmd);
    lines.push(`dbt target: ${target ? code(target)
        : fallback ? `${code(fallback)} (the profile's default; no \`--target\` given)`
        : "the profile's default (no `--target` given)"}`);
    const empty = cmd.args.includes('--empty');
    if (empty) {
        lines.push('⚠️ `--empty` is set: every model this run builds will have zero rows afterwards.');
    }
    const plainWhat = selector ? `the dbt models chosen by selector ${code(selector)}`
        : runtime ? 'dbt models chosen when the command runs'
        : models.length === 1 ? `the dbt model ${code(models[0])}`
        : models.length > 1 ? `${models.length} dbt models`
        : 'every dbt model in the project';
    const where = target ? `the dbt target ${code(target)}` : fallback ? `the dbt target ${code(fallback)}` : "the profile's default dbt target";
    return {
        label: `Rebuild ${what} from scratch (--full-refresh)`,
        lines,
        plain: {
            what: `Deletes and rebuilds ${plainWhat} from scratch in ${where}${empty ? ', leaving them empty' : ''}`,
            loss: 'rows that only earlier runs kept are lost for good',
        },
    };
}

function gitPushStep(cmd: ResolvedCommand): StepCard {
    const valueOpts = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--exec-path']);
    let i = 0;
    let dir: string | undefined;
    while (i < cmd.args.length && cmd.args[i] !== 'push') {
        if (cmd.args[i] === '-C') dir = cmd.args[i + 1];
        i += valueOpts.has(cmd.args[i]) ? 2 : 1;
    }
    const rest = cmd.args.slice(i + 1);
    const positional: string[] = [];
    const flags = new Set<string>();
    let operandsOnly = false;
    for (const a of pushArgsWithoutValues(rest)) {
        if (a === '--' && !operandsOnly) { operandsOnly = true; continue; }
        if (operandsOnly || !a.startsWith('-')) positional.push(a);
        else if (a.startsWith('--')) flags.add(a.split('=')[0]);
        else for (const ch of a.slice(1)) {
            flags.add(`-${ch}`);
            if (GIT_PUSH_SHORT_VALUE_FLAGS.includes(ch)) break;
        }
    }
    const remote = positional[0] ?? 'the upstream remote';
    const refs = positional.slice(1);
    const remoteRef = (spec: string) => { const s = spec.replace(/^\+/, ''); return s.includes(':') ? s.slice(s.indexOf(':') + 1) : s; };
    const refList = (xs: string[]) => xs.map(remoteRef).join(', ');

    if (flags.has('--mirror')) {
        return { dir, label: `Mirror-push every branch and tag to ${remote}`, lines: [
            `If you approve: every branch and tag on ${code(remote)} is made to match this clone. Remote branches and tags that don't exist here are deleted.`,
        ], plain: {
            what: `Makes the shared copy ${code(remote)} match this one exactly, deleting branches and tags that exist only there`,
            loss: 'work that exists only on those is lost for everyone',
        } };
    }
    if (flags.has('--prune')) {
        const scope = refs.length ? `matching ${code(refs.join(' '))}` : 'covered by the push (branches, by default)';
        return { dir, label: `Delete remote refs on ${remote} that don't exist locally (--prune)`, lines: [
            `If you approve: every ref on ${code(remote)} ${scope} with no local counterpart is deleted. That can include tags when the refspec names them; pull requests from deleted branches close.`,
        ], plain: {
            what: `Deletes the branches on the shared copy ${code(remote)} that this copy doesn't have`,
            loss: 'work that exists only on them is lost for everyone, and their pull requests close',
        } };
    }
    const deleted = flags.has('--delete') || flags.has('-d') ? refs : refs.filter(r => r.startsWith(':'));
    if (deleted.length) {
        return { dir, label: `Delete remote branch ${refList(deleted)} on ${remote}`, lines: [
            `If you approve: ${code(refList(deleted))} is deleted on ${code(remote)}. Pull requests from it close, and commits pushed only there are lost unless someone has a copy.`,
        ], plain: {
            what: `Deletes the branch ${code(refList(deleted))} from the shared copy ${code(remote)}`,
            loss: 'work saved only on it is lost unless someone has a copy, and its pull requests close',
        } };
    }
    const forceAll = flags.has('--force') || flags.has('-f');
    const forced = forceAll ? refs : refs.filter(r => r.startsWith('+'));
    const which = flags.has('--all') || flags.has('--branches') ? 'every local branch'
        : flags.has('--tags') ? 'every tag'
        : forced.length ? code(refList(forced)) : 'the current branch';
    const plainWhich = flags.has('--all') || flags.has('--branches') ? 'every branch'
        : flags.has('--tags') ? 'every tag'
        : forced.length ? `the branch ${code(refList(forced))}` : 'the current branch';
    return { dir, label: `Force-push ${which.replace(/`/g, '')} to ${remote}`, lines: [
        `If you approve: ${which} on ${code(remote)} is overwritten with this local history. Commits on the remote that aren't in this copy are discarded for everyone.`,
    ], plain: {
        what: `Overwrites the history of ${plainWhich} on the shared copy ${code(remote)} with this copy's`,
        loss: "work others saved there that this copy doesn't have is lost for everyone",
    } };
}

interface GitCleanArgs { dryRun: boolean; help: boolean; ignored: boolean; onlyIgnored: boolean; dirs: boolean; excluded: string[]; paths: string[] }

/**
 * `git clean`'s arguments read in order, as git's option parser does: the last of `-n`/`--dry-run`/`--no-dry-run`
 * wins, `-e`/`--exclude` take a value, and a long option may be any unambiguous prefix of its name.
 */
function parseGitClean(rest: string[]): GitCleanArgs {
    const out: GitCleanArgs = { dryRun: false, help: false, ignored: false, onlyIgnored: false, dirs: false, excluded: [], paths: [] };
    for (let i = 0; i < rest.length; i++) {
        const a = rest[i];
        if (a === '--') {
            out.paths.push(...rest.slice(i + 1));
            break;
        }
        if (a.startsWith('--')) {
            const [name, value] = [a.slice(2).split('=')[0], a.includes('=') ? a.slice(a.indexOf('=') + 1) : undefined];
            if (name && 'dry-run'.startsWith(name)) out.dryRun = true;
            else if (name.length > 3 && 'no-dry-run'.startsWith(name)) out.dryRun = false;
            else if (name && 'exclude'.startsWith(name)) out.excluded.push(value ?? rest[++i] ?? '');
            else if (name.length > 1 && 'help'.startsWith(name)) out.help = true;
            continue;
        }
        if (!/^-[A-Za-z]/.test(a)) {
            out.paths.push(a);
            continue;
        }
        for (let k = 1; k < a.length; k++) {
            const letter = a[k];
            if (letter === 'n') out.dryRun = true;
            else if (letter === 'h') out.help = true;
            else if (letter === 'x') out.ignored = true;
            else if (letter === 'X') out.onlyIgnored = true;
            else if (letter === 'd') out.dirs = true;
            else if (letter === 'e') {
                out.excluded.push(k < a.length - 1 ? a.slice(k + 1) : rest[++i] ?? '');
                break;
            }
        }
    }
    out.excluded = out.excluded.filter(Boolean);
    return out;
}

/** The directory git runs in after every `-C` (relative ones compose) and `--work-tree`, or undefined when none is given. */
function gitEffectiveDir(args: string[], env: string[] = []): string | undefined {
    let dir: string | undefined;
    // A GIT_WORK_TREE the command sets is the work tree unless --work-tree overrides it.
    let workTree = env.findLast(e => e.startsWith('GIT_WORK_TREE='))?.slice('GIT_WORK_TREE='.length);
    for (let i = 0; i < gitSubcommandIndex(args); i++) {
        const a = args[i];
        if (a === '-C') {
            const next = args[++i] ?? '';
            dir = next.startsWith('/') || dir === undefined ? next : join(dir, next);
        } else if (a === '--work-tree') workTree = args[++i];
        else if (a.startsWith('--work-tree=')) workTree = a.slice('--work-tree='.length);
        else if (GIT_GLOBAL_VALUE_OPTS.has(a)) i++;
    }
    return workTree !== undefined ? (workTree.startsWith('/') || dir === undefined ? workTree : join(dir, workTree)) : dir;
}

function gitCleanStep(cmd: ResolvedCommand): StepCard {
    const { ignored, onlyIgnored, dirs, excluded, paths } = parseGitClean(cmd.args.slice(gitSubcommandIndex(cmd.args) + 1));
    const what = onlyIgnored ? 'ignored files' : ignored ? 'untracked and ignored files' : 'untracked files';
    const where = paths.length ? ` under ${paths.map(code).join(', ')}` : '';
    const lines = [
        // A pathspec matches untracked directories whole, with or without -d.
        `If you approve: all ${what}${dirs || paths.length ? ' and directories' : ''}${where} are deleted, skipping the trash. They cannot be recovered.`,
    ];
    if (ignored || onlyIgnored) lines.push('Ignored files include local secrets and data such as `.env`, caches and build output.');
    // -e adds to the ignore rules: it protects files from a plain or -x clean, and adds to what -X deletes. A leading
    // `!` un-ignores instead, so its effect is the reverse.
    // The last of several -e rules for one pattern wins, as in a .gitignore.
    const last = new Map(excluded.map(p => [p.replace(/^!/, ''), p.startsWith('!')]));
    const negated = [...last].filter(([, neg]) => neg).map(([p]) => p);
    const plain = [...last].filter(([, neg]) => !neg).map(([p]) => p);
    const kept = onlyIgnored ? negated : plain;
    const added = onlyIgnored ? plain : negated;
    if (kept.length) lines.push(`Kept: files matching ${kept.map(code).join(', ')}.`);
    if (added.length) lines.push(`Also deleted: files matching ${added.map(code).join(', ')}, which -e ${onlyIgnored ? 'marks as ignored' : 'un-ignores'}.`);
    const plainWhat = onlyIgnored ? 'the files Git is set to ignore' : 'every file not saved in Git';
    const plainNote = onlyIgnored ? ', which often hold secrets, local data and build output'
        : ignored ? ', including ignored files, which often hold secrets and local data' : '';
    return {
        dir: gitEffectiveDir(cmd.args, cmd.env),
        label: `Permanently delete ${what}${where.replace(/`/g, '')} (git clean)`,
        lines,
        plain: { what: `Permanently deletes ${plainWhat}${where}`, note: plainNote, loss: "they skip the trash and can't be recovered", inDir: true },
    };
}

function awsStep(cmd: ResolvedCommand): StepCard {
    const [service, op, opIndex] = awsServiceAndOperation(cmd.args);
    const operands = cmd.args.slice(opIndex + 1).filter(a => !a.startsWith('-'));
    const lines: string[] = [];
    let label = `AWS ${service} ${op}`;
    let plain: PlainEffect;
    if (service === 's3' && op === 'rm') {
        const recursive = cmd.args.includes('--recursive');
        label = `Delete S3 ${recursive ? 'objects under' : 'object'} ${operands[0] ?? ''}`.trim();
        lines.push(`If you approve: deletes ${recursive ? 'everything under ' : ''}${code(operands[0] ?? '?')}. S3 has no undo unless the bucket has versioning.`);
        plain = {
            what: `Deletes ${recursive ? 'every file under' : 'the file'} ${code(operands[0] ?? '?')} from Amazon S3 cloud storage`,
            loss: "it can't be recovered unless the bucket keeps old versions",
        };
    } else if (service === 's3' && op === 'rb') {
        label = `Delete S3 bucket ${operands[0] ?? ''}`.trim();
        const force = cmd.args.includes('--force');
        lines.push(`If you approve: deletes the bucket ${code(operands[0] ?? '?')}${force ? ' and every object in it' : ''}.`);
        plain = { what: `Deletes the Amazon S3 storage bucket ${code(operands[0] ?? '?')}${force ? ' and every file in it' : ''}`, loss: "this can't be undone" };
    } else {
        const ids: string[] = [];
        cmd.args.forEach((a, k) => {
            if (!/^--[\w-]*(?:id|ids|name|names|arn|arns)$/.test(a)) return;
            const values = [];
            for (let j = k + 1; j < cmd.args.length && !cmd.args[j].startsWith('-'); j++) values.push(cmd.args[j]);
            if (values.length) ids.push(`${a} ${values.join(' ')}`);
        });
        lines.push(`If you approve: runs ${code(op)} against AWS ${service}${ids.length ? ` for ${code(clip(ids.join(' '), 300))}` : ''}. AWS has no undo for delete and terminate calls.`);
        plain = { what: `Deletes or shuts down AWS ${service} resources (${code(op)})`, loss: "AWS can't undo a delete or terminate" };
    }
    const profile = flagValue(cmd.args, ['--profile']);
    if (profile) {
        lines.push(`AWS profile: ${code(profile)}`);
        plain = { ...plain, what: `${plain.what} in the AWS account of profile ${code(profile)}` };
    }
    return { label, lines, plain };
}

const GENERIC_EFFECTS: Record<string, [effect: string, loss: string]> = {
    'terraform destroy': ['Destroys every resource this Terraform state manages.', "the resources and the data in them can't be brought back"],
    'terraform apply': ['Applies changes without showing the plan first; it can create, change or destroy infrastructure.', "anything it destroys can't be brought back"],
    'pulumi destroy': ['Destroys every resource in the stack.', "the resources and the data in them can't be brought back"],
    'cdk destroy': ['Destroys every resource in the stack.', "the resources and the data in them can't be brought back"],
    'kubectl delete': ['Deletes the named Kubernetes resources.', 'data kept only inside them is lost'],
    'kubectl drain': ['Evicts every pod from the node and stops new ones landing there.', 'running work is interrupted, though nothing is deleted and it can be reversed'],
    'kubectl cordon': ['Stops new pods being scheduled on the node.', 'nothing is deleted, and it can be reversed'],
    'docker rm': ['Deletes the containers, with any data not stored in a volume.', 'data not stored in a volume is lost'],
    'docker rmi': ['Deletes the images.', 'they can usually be rebuilt or downloaded again'],
    'docker system': ['Deletes stopped containers, unused networks and dangling images.', "what it removes can't be recovered"],
    'docker volume': ['Deletes the volumes and the data in them.', "the data in them can't be recovered"],
    'helm uninstall': ['Removes the release and every Kubernetes resource it created.', 'data kept only in those resources is lost'],
    'helm delete': ['Removes the release and every Kubernetes resource it created.', 'data kept only in those resources is lost'],
    'gh repo': ['Permanently deletes the GitHub repository.', "its code, issues and pull requests can't be recovered"],
    dd: ['Writes raw bytes to the output target; pointed at a disk, it overwrites it.', "whatever it overwrites can't be recovered"],
    render: ['Changes the Render service, database or job named in the step below, which is not listed as dev, so treat it as production.', "some changes, such as a deleted database, can't be undone"],
};

function genericStep(cmd: ResolvedCommand, reason: string): StepCard {
    const verbs = cmd.args.filter(a => /^[a-z][\w:-]*$/i.test(a)).slice(0, 2);
    const run = code([cmd.name, ...verbs].join(' '));
    const targets = flagValues(cmd.args, ['-target']);
    const described: [effect: string, loss: string] | undefined = cmd.name === 'terraform' && targets.length
        ? [`Destroys or changes the targeted resources: ${code(clip(targets.join(', '), 300))}.`, "anything it destroys can't be brought back"]
        : GENERIC_EFFECTS[`${cmd.name} ${cmd.args[0] ?? ''}`] ?? GENERIC_EFFECTS[cmd.name]
            ?? (PLATFORM_DESTRUCTIVE[cmd.name] ? [`Deletes or shuts down the ${cmd.name} resource named in the step below.`, "this can't be undone"] : undefined);
    const plain: PlainEffect = described
        ? { what: `Runs ${run}, which ${described[0].charAt(0).toLowerCase()}${described[0].slice(1)}`, loss: described[1] }
        : { what: `Runs ${run}, which the guard flags as able to delete or overwrite something`, loss: 'it may not be possible to undo' };
    return { label: `Run ${[cmd.name, ...verbs].join(' ')}`, lines: [`If you approve: ${described?.[0] ?? reason}`], plain };
}

const DIRECTORY_CHANGERS = new Set(['cd', 'pushd', 'popd']);

/**
 * The directories a later command may run in, given those it may have started in and a `cd`, `pushd` or `popd`
 * before it; null once one can't be known. The parsed commands drop subshell and branch structure, so a change
 * may not have applied and every directory along the way stays possible.
 */
function directoriesAfter(dirs: string[] | null, change: ResolvedCommand): string[] | null {
    if (dirs === null || change.name === 'popd') return null;
    const operands = change.args.filter(a => a !== '--' && !/^-[LPe@]+$/.test(a));
    const target = operands[0];
    if (operands.length !== 1 || !target || /^[-+~]|[$`*?[]/.test(target)) return null;
    return [...new Set([...dirs, ...dirs.map(d => pathResolve(d, target))])];
}
/**
 * Yield each command the gate decides on, with its reason, in order: gated by
 * checkGatedCommand and not exempted as a dev-scope, local scratch Postgres or lab target. evaluateBashCommand
 * gates on the first; the description describes the same ones.
 */
function* gatedSteps(
    commands: ResolvedCommand[],
    command: string,
    cwd: string,
    lab: boolean,
    log: boolean,
    localPg: LocalPgHost = LIVE_LOCAL_PG_HOST,
): Generator<{ cmd: ResolvedCommand; reason: string; outer: ResolvedCommand; moves?: ResolvedCommand[]; fix?: string }> {
    let dirs: string[] | null = [cwd];
    for (const outer of commands) {
        if (DIRECTORY_CHANGERS.has(outer.name)) dirs = directoriesAfter(dirs, outer);
        const outerReason = checkGatedCommand(outer);
        for (const { step: cmd, reason, runtime, moves } of outerReason ? [{ step: outer, reason: outerReason }] as InnerGate[] : innerGatedSteps(outer)) {
            if (runtime) {
                yield { cmd, reason, outer, moves };
                continue;
            }
            if (clientProgramGate(cmd) !== null) {
                yield { cmd, reason, outer, moves };
                continue;
            }
            const dev = devScopeTargetOf(cmd, commands, command, cmd === outer);
            if (dev !== null) {
                if (log) console.error(`dev-scope: allowed ${cmd.name} against ${dev}`);
                continue;
            }
            // Only a top-level psql: one xargs or find runs is not the command line the target was read from.
            const local = cmd === outer ? localPgTargetOf(cmd, commands, command, localPg) : null;
            if (local !== null) {
                if (log) console.error(`local-pg: allowed ${cmd.name} against ${local}`);
                continue;
            }
            if (lab) {
                // A step under `env -C`, or after a `cd`, resolves its target (a bare remote, a checkout) from there;
                // it is exempt only if every directory it may be in is.
                let from: string[] | null = dirs && cmd.chdir ? dirs.map(d => pathResolve(d, cmd.chdir!)) : dirs;
                for (const move of moves ?? []) from = directoriesAfter(from, move);
                const target = from && from.every(d => labTargetOf(cmd, d) !== null) ? labTargetOf(cmd, from[0]) : null;
                if (target !== null) {
                    if (log) logLabScope(`allowed ${cmd.name} against lab target ${target}`);
                    continue;
                }
            }
            const withoutPsqlrc = cmd === outer ? localPgTargetOf(cmd, commands, command, localPg, true) : null;
            if (withoutPsqlrc !== null) {
                yield {
                    cmd, reason, outer, moves,
                    fix: `${reason}: psql against the scratch Postgres at ${withoutPsqlrc} runs without approval only with -X (--no-psqlrc), since a psqlrc file can connect somewhere other than the -h shown. Run the same command again with -X added.`,
                };
                continue;
            }
            yield { cmd, reason, outer, moves };
        }
    }
}

/**
 * Describe a gated command for its approver: a title naming what will be
 * changed, what approving does, and the exact step that tripped the gate with
 * the variables the command provably sets filled in.
 */
export function describeGate(command: string, reason: string, cwd: string = currentWorkingDir()): GateCard {
    const fallback = {
        label: reason,
        summary: plainSentence({ what: "The guard flagged this command as able to delete or overwrite something but couldn't work out what", loss: 'check the full command before approving' }),
    };
    try {
        const commands = extractCommands(command);
        if (commands[0]?.script) commands[0].script.cwd = cwd;
        const gated = [...gatedSteps(commands, command, cwd, isLabSession(), false)];
        if (gated.length === 0) return fallback;
        const view = viewShell(command);

        const evaluated = (cmd: ResolvedCommand, unresolved: Set<string>): ResolvedCommand => {
            const texts = cmd.pos === undefined ? undefined : view.commandAt(cmd.pos)?.argTexts;
            if (!texts || texts.length < cmd.args.length) {
                cmd.args.filter(a => a.includes('$')).forEach(a => unresolved.add(clip(a, 40)));
                return cmd;
            }
            const args = texts.slice(texts.length - cmd.args.length).map(t => {
                const r = evalWord(t, view, cmd.pos!);
                r.unresolved.forEach(u => unresolved.add(u));
                return r.value;
            });
            return { ...cmd, args };
        };
        const cdTo = (dir: string | undefined, next: string): string | undefined =>
            next.includes('$') ? undefined : next.startsWith('/') ? next : dir && join(dir, next);
        // `outer` is the top-level command `target` runs inside (itself, unless xargs or find -exec runs it), and
        // `moves` the `cd`s its script makes before it.
        const directoryBefore = (target: ResolvedCommand, outer: ResolvedCommand, moves: ResolvedCommand[] = []): string | undefined => {
            let dir: string | undefined;
            for (const c of commands) {
                if (c === outer) break;
                if (c.name !== 'cd' || !c.args[0]) continue;
                dir = cdTo(dir, evaluated(c, new Set()).args[0]);
            }
            dir = target.chdir ?? outer.chdir ?? dir;
            for (const m of moves) dir = m.name === 'cd' && m.args[0] ? cdTo(dir, m.args[0]) : undefined;
            return dir;
        };

        const steps = gated.slice(0, 3).map(({ cmd: raw, reason: why, outer, moves }) => {
            const unresolved = new Set<string>();
            const cmd = evaluated(raw, unresolved);
            const sqlDialect = SQL_CLIS[cmd.name] ?? (cmd.name === 'snow' && cmd.args[0] === 'sql' ? 'Snowflake' : null);
            const dirBefore = directoryBefore(raw, outer, moves);
            const step: StepCard =
                sqlDialect ? sqlStep(sqlDialect, cmd)
                : cmd.name === 'dbt' ? dbtStep(cmd, dirBefore)
                : cmd.name === 'git-clean' ? gitCleanStep({ ...cmd, args: ['clean', ...cmd.args] })
                : cmd.name === 'git' ? (cmd.args[gitSubcommandIndex(cmd.args)] === 'clean' ? gitCleanStep(cmd) : gitPushStep(cmd))
                : cmd.name === 'aws' ? awsStep(cmd)
                : genericStep(cmd, why);
            const dir = step.dir === undefined ? dirBefore
                : step.dir.startsWith('/') || dirBefore === undefined || !dirBefore.startsWith('/') ? step.dir
                : join(dirBefore, step.dir);
            const shown = raw.pos === undefined ? raw.raw : evalWord(raw.raw, view, raw.pos, true).value;
            const lines = [...step.lines];
            if (dir) lines.push(`Directory: ${code(dir)}`);
            lines.push(`Step needing approval: ${code(clip(oneLine(shown), 320))}`);
            if (unresolved.size) {
                const list = [...unresolved];
                lines.push(`⚠️ ${list.map(code).join(', ')} ${list.length === 1 ? 'is' : 'are'} only known when the command runs, so the value${list.length === 1 ? '' : 's'} above may differ.`);
            }
            if ([raw.name, ...raw.args].some(w => w.includes(FILLED))) lines.push(`⚠️ Part of this step is ${outer.name === 'xargs' ? 'what xargs reads' : 'each file find matches'}, only known when the command runs.`);
            const plain = { what: `${step.plain.what}${step.plain.inDir && dir ? ` in ${code(dir)}` : ''}${step.plain.note ?? ''}`, loss: step.plain.loss };
            return { label: step.label, lines, plain };
        });

        let label = steps[0].label;
        if (gated.length > 1) label += ` + ${gated.length - 1} more destructive step${gated.length > 2 ? 's' : ''}`;
        const lines = [plainSentence(steps[0].plain, gated.length - 1), '', ...steps.flatMap((s, i) => (i === 0 ? s.lines : ['', `Also: ${s.label}`, ...s.lines]))];
        if (gated.length > steps.length) lines.push('', `…and ${gated.length - steps.length} more destructive steps; see the full command.`);
        if (commands.length > gated.length) {
            lines.push('', `Approving runs the whole command (${commands.length} steps), not only the step${gated.length > 1 ? 's' : ''} described here.`);
        }
        lines.push(`Guard rule: ${clip(oneLine(reason), 200)}`);
        return { label: clip(label, CARD_LABEL_MAX_CHARS), summary: fitLines(lines, CARD_SUMMARY_MAX_CHARS) };
    } catch {
        return fallback;
    }
}

/** The one text a harness's own approval prompt shows: title, blank line, details. */
export function approvalText(card: GateCard): string {
    return card.summary && card.summary !== card.label ? `${card.label}\n\n${card.summary}` : card.label;
}

// ── rm checks ────────────────────────────────────────────────────────────────

/**
 * Apply three-tier rm protection. Returns the full block message (already
 * prefixed with `BLOCKED:`) when the rm should be blocked, or null when it is
 * allowed. The caller is responsible for emitting the message and exiting.
 *
 * `opts.isExtraSafe` widens tier 2 (the ephemeral-path allowlist) for the
 * caller's scope. evaluateBashCommand passes its lab-worktree matcher through it
 * in a Lab session and nothing else does — the default behavior is unchanged.
 */
export function checkRmDecision(
    cmd: ResolvedCommand,
    opts: { isExtraSafe?: (path: string) => boolean } = {},
): string | null {
    const safe = opts.isExtraSafe
        ? (p: string) => isSafePath(p) || opts.isExtraSafe!(p)
        : isSafePath;
    // Separate flags from paths using AST-parsed args
    const flags: string[] = [];
    const paths: string[] = [];
    let endOfFlags = false;

    for (const arg of cmd.args) {
        if (arg === '--') {
            endOfFlags = true;
        } else if (!endOfFlags && arg.startsWith('-')) {
            flags.push(arg);
        } else {
            paths.push(arg);
        }
    }

    const isRecursive = flags.some(f => /^-[^-]*r/i.test(f) || f === '--recursive');
    const isForce = flags.some(f => /^-[^-]*f/.test(f) || f === '--force');

    if (paths.length === 0) {
        return `BLOCKED: '${cmd.raw}' — rm requires an explicit path. Use: trash <path>`;
    }

    // Dangerous wildcards — bare *, ., .. always blocked; ./* and ../* when -r or -f
    const hasDangerousWildcard = paths.some(p => {
        if (p === '*' || p === '.' || p === '..') return true;
        if (isRecursive || isForce) {
            if (p === './*' || p === '../*') return true;
        }
        return false;
    });
    if (hasDangerousWildcard) {
        return `BLOCKED: '${cmd.raw}' — rm with bare wildcard/dot is not allowed. Be explicit about which paths to delete.`;
    }

    // Tier 1: protected paths → hard block (safe ephemeral paths take priority)
    for (const p of paths) {
        if (!safe(p) && isProtectedPath(p)) {
            return `BLOCKED: '${cmd.raw}' — '${p}' is a protected path.`;
        }
    }

    // Tier 2: safe ephemeral paths → allow
    // Tier 3: everything else → redirect to trash (flag only the unsafe paths)
    const unsafePaths = paths.filter(p => !safe(p));
    if (unsafePaths.length > 0) {
        const trashCmd = `trash ${unsafePaths.join(' ')}`;
        return `BLOCKED: rm is not allowed for non-ephemeral paths. Re-run your command using trash instead:\n\n  ${trashCmd}\n\ntrash moves files to macOS Trash (recoverable). Ephemeral paths (tmp, node_modules, dist, build, .cache, coverage, __pycache__, etc.) are allowed with rm.`;
    }

    return null;
}

/** Why the guard can't read `command` the way bash will run it, so commands it hides go unchecked; null when it can. */
function shellParseProblem(command: string): string | null {
    try {
        parseShell(command);
        return null;
    } catch (e) {
        if (!(e instanceof ShellParseError)) return null;
        return `The guard can't read this command the way bash will run it (${e.message}), so it can't check what runs after that point. Put a heredoc on a named command (not a bare redirect or coproc), with its delimiter quoted whole ('EOF') or not at all (EOF).`;
    }
}

/**
 * Replicate main()'s decision ordering against a raw bash command string,
 * WITHOUT the approval-bypass step (that stays in the caller) and without any
 * process.exit / stderr:
 *   (1) hard block (first non-null checkHardBlock) ⇒ block
 *   (2) gated command (first non-null checkGatedCommand) ⇒ gate
 *   (3) rm decision (first non-null checkRmDecision) ⇒ block
 *   else ⇒ allow
 *
 * Reasons are returned verbatim: hard-block reasons are the bare message
 * (the caller prefixes `BLOCKED: `); gated reasons are the bare gate reason;
 * rm reasons are already prefixed with `BLOCKED:`.
 *
 * `opts.skipGate` skips tier (2). The caller uses this for the post-approval
 * pass: in the original main(), an approved gate falls through to the rm tier,
 * so a destructive rm in the same command line is still blocked even after the
 * gated verb was approved. Skipping tier (2) reproduces that fall-through.
 *
 * `opts.cwd` is the working directory the command will run in — supplied by an
 * adapter that has it on its hook input (Claude's `cwd` field), else
 * process.cwd(). The scope predicates below resolve a bare `git push origin`
 * through it, and the conflict hard block finds the repository whose
 * in-progress operation it checks from it.
 *
 * LAB SCOPE (tier 2 and tier 3 only): in a Lab session, a gated verb aimed at a
 * lab target allows instead of holding, and a lab worktree path joins the rm
 * ephemeral allowlist. Tier 1 is never exempted. Both predicates must hold and
 * both fail closed — see "Lab-scoped exemption" above.
 *
 * `opts.localPg` is the host the local scratch Postgres exemption reads procfs
 * and the environment from; adapters leave it unset for the real one.
 */
export function evaluateBashCommand(
    command: string,
    opts: { skipGate?: boolean; cwd?: string; localPg?: LocalPgHost } = {},
): GateEvaluation {
    if (clientShellVerdicts) return evaluateBashLine(command, opts);
    clientShellVerdicts = new Map();
    try {
        return evaluateBashLine(command, opts);
    } finally {
        clientShellVerdicts = null;
    }
}

function evaluateBashLine(
    command: string,
    opts: { skipGate?: boolean; cwd?: string; localPg?: LocalPgHost },
): GateEvaluation {
    const commands = extractCommands(command);
    const ephemeralMktempVariables = findEphemeralMktempVariables(command);
    const lab = isLabSession();
    const cwd = opts.cwd ?? currentWorkingDir();
    if (commands[0]?.script) commands[0].script.cwd = cwd;

    // --- Hard block checks (no bypass, ever — lab included) ---
    for (const cmd of commands) {
        const reason = checkHardBlock(cmd) ?? stageAllDuringConflictReason(cmd, cwd);
        if (reason) {
            return { action: 'block', reason };
        }
    }
    const selfKill = selfMatchingKillReason(commands, command);
    if (selfKill) return { action: 'block', reason: selfKill };
    const merge = noMergeReason(commands, cwd, command);
    if (merge) return { action: 'block', reason: merge };
    // A line the guard can't read the way bash runs it blocks and stays blocked on the approval replay: approval
    // can't clear what could not be read, the same as a shell taking its command from a variable.
    const unreadable = shellParseProblem(command);
    if (unreadable) return { action: 'block', reason: unreadable };

    // --- Gated checks ---
    if (!opts.skipGate) {
        const first = gatedSteps(commands, command, cwd, lab, true, opts.localPg).next();
        // A step one flag short of the scratch-Postgres exemption is refused with that flag named, not sent to an
        // approver: the agent reruns it with -X and it passes without a card.
        if (!first.done) return first.value.fix ? { action: 'block', reason: first.value.fix } : { action: 'gate', reason: first.value.reason };
    }

    // --- rm-specific checks (three-tier protection) ---
    for (const cmd of commands) {
        if (cmd.name === 'rm') {
            const proven = typeof cmd.pos === 'number'
                ? ephemeralMktempVariables.get(cmd.pos) ?? new Set<string>()
                : new Set<string>();
            const resolved = resolveEphemeralRmArgs(cmd, proven);
            let reason = checkRmDecision(resolved);
            if (reason && lab) {
                // Re-decide with lab worktree paths counted as ephemeral. Only
                // logged when it actually changes the outcome.
                const relaxed = checkRmDecision(resolved, { isExtraSafe: isLabWorktreePath });
                if (relaxed === null) {
                    logLabScope(`allowed rm against lab target ${resolved.args.filter(a => !a.startsWith('-')).join(' ')}`);
                }
                reason = relaxed;
            }
            if (reason) {
                return { action: 'block', reason };
            }
        }
    }

    return { action: 'allow' };
}

// ── Legacy gate-file compatibility ────────────────────────────────────────────
// Current local Claude and Codex adapters use their native `ask` permission
// decision. The agent-writable marker below is retired — see
// `consumeGateApproval`. GATE_DIR itself still hosts the claim files.

export const GATE_DIR = '/tmp/.claude-destructive-gate';

export function computeGateHash(command: string): string {
    return createHash('sha256').update(command).digest('hex').slice(0, 16);
}

export function consumeGateApproval(_command: string): boolean {
    // RETIRED (nanoclaw #858). This used to unlink `<GATE_DIR>/<hash(command)>`
    // and answer true, which made the caller skip the approval gate outright.
    // GATE_DIR is under /tmp — agent-writable — and NOTHING in either tree ever
    // wrote that marker: the only real approval path is the session-DB gate
    // (`runGateRequest`), whose decision the HOST writes to inbound.db. So the
    // read granted nothing legitimate and was a pure self-approval door for any
    // process in the container that could create one file. It now answers false
    // unconditionally. The export stays because NanoClaw's in-tree Codex chain
    // validates its presence at load (codex-hooks/runner.ts `validateGuardCore`)
    // and older container images still call it.
    return false;
}

// ── One approval card per tool call (cross-process claim) ────────────────────
// A Codex tool call dispatches EVERY matched PreToolUse handler, and it does so
// CONCURRENTLY: `execute_handlers_with_metadata` pushes each handler onto a
// `FuturesUnordered` before awaiting any of them, and `should_block` is a plain
// `.any()` over all the results — there is no ordering and no short-circuit on a
// deny (codex-rs 0.154.0 `hooks/src/engine/dispatcher.rs`,
// `hooks/src/events/pre_tool_use.rs`). Measured on a real 0.154.0 run: two
// PreToolUse handlers started 0.7 ms apart and received the SAME `tool_use_id`.
//
// In a NanoClaw container there are two such handlers — the in-tree chain and
// this plugin's `codex-guard.ts` — and both reach the session-DB gate. Without a
// claim, one gated command raises TWO approval cards, each needing its own
// answer. It fails closed (both must approve), but it doubles approval traffic
// on exactly the commands that matter most.
//
// Deduping HERE, at the approval layer, rather than by silencing one chain, is
// what keeps it safe: both chains still evaluate the command in full, so no
// guard's coverage depends on the other running, and a third PreToolUse handler
// would join the same claim rather than add a third card.
//
// The protocol is two files per claim, in a shared /tmp dir, and it has to work
// between separate PROCESSES that start within a millisecond of each other:
//
//   <claim>.lock   created with O_EXCL. Exactly one process wins it and becomes
//                  the OWNER: it stages the request and publishes the id.
//   <claim>        written as `<claim>.tmp` then RENAMED, so it never exists in
//                  a half-written state. Losers read it to learn the owner's
//                  requestId and then poll the same decision.
//
// A loser that never sees `<claim>` appear — the owner crashed, or failed to
// stage — falls back to staging its own request. Two cards is a worse
// experience; no gate at all is a security failure, so the fallback is the
// fail-closed direction.

export const GATE_CLAIM_DIR = `${GATE_DIR}/claims`;

/** How long a loser waits for the owner to publish its requestId. */
const CLAIM_PUBLISH_TIMEOUT_MS = 15_000;
const CLAIM_POLL_INTERVAL_MS = 25;
/** Claims older than this are swept; matches the 60-minute gate window. */
const CLAIM_MAX_AGE_MS = 60 * 60 * 1000;

/**
 * Identity of ONE approval card: the tool call, plus which gate is asking.
 *
 * `toolUseId` is what makes two handlers of the same tool call collide and two
 * different tool calls not. `action` is in the key so a single tool call that
 * legitimately needs two DIFFERENT approvals — a destructive gate and an
 * outbound-email gate — still raises one card each rather than collapsing into
 * whichever staged first and answering one question with the other's approval.
 *
 * The COMMAND is deliberately NOT in the key, and leaving it in was a real bug
 * caught before this shipped. The two guards do not see the same command string:
 * NanoClaw's in-tree chain runs its Bash sanitizer FIRST and gates on the
 * rewritten `unset <secret-vars> 2>/dev/null; <original>` form, while this
 * adapter gates on the raw command from the hook input — codex hands every
 * handler the same `input_json`, built once before any of them runs. Keying on
 * the command therefore produced two different keys for one tool call and both
 * guards staged anyway, exactly the behaviour the claim exists to remove. One
 * tool call is one command, so (toolUseId, action) is both sufficient and the
 * only thing the two chains can agree on.
 */
export function gateClaimKey(toolUseId: string, action: string): string {
    return createHash('sha256').update(`${toolUseId}\u0000${action}`).digest('hex').slice(0, 32);
}

/** Remove claim files older than the gate window. Best-effort, never throws. */
function sweepStaleClaims(nowMs: number): void {
    let entries: string[];
    try {
        entries = readdirSync(GATE_CLAIM_DIR);
    } catch {
        return;
    }
    for (const entry of entries) {
        const full = `${GATE_CLAIM_DIR}/${entry}`;
        try {
            if (nowMs - statSync(full).mtimeMs > CLAIM_MAX_AGE_MS) unlinkSync(full);
        } catch {
            // Gone already, or not ours to remove.
        }
    }
}

/**
 * Which `delivered.status` values mean a human has ANSWERED the card.
 *
 * Extracted and exported because this predicate, not the SQLite plumbing around
 * it, is where the bug was: an earlier revision treated the mere PRESENCE of a
 * row as decided, which made every `pending` card — the live, unanswered state —
 * look settled. The DB path is a hardcoded container mount, so the round trip
 * cannot be driven from a unit test; the predicate can, exhaustively.
 *
 * An unknown status is NOT decided: a future status this code has never heard of
 * is more likely a new in-flight state than a new terminal one, and guessing
 * "decided" is the answer that silently duplicates approval cards.
 */
export function isDecidedGateStatus(status: string | null | undefined): boolean {
    return status === 'delivered' || status === 'failed';
}

/**
 * Has this requestId ALREADY been decided?
 *
 * A live peer publishes an id that nothing has answered yet, so a published id
 * that already carries a `delivered` row is not a peer to wait on — it is a past
 * decision being replayed, and honouring it would hand this tool call an
 * approval a human gave to a different command.
 *
 * The claim directory lives under /tmp, which an agent can write to, so this is
 * the one check that cannot be skipped: without it, planting a claim pointing at
 * any previously-approved requestId skips the gate outright. (It also covers the
 * no-attacker case — a `tool_use_id` repeating inside the sweep window would
 * otherwise reuse the earlier decision.)
 *
 * DECIDED means `delivered` or `failed` — NOT `pending`. The host writes a
 * `pending` row the moment it posts the card and leaves it there for the whole
 * decision window (nanoclaw `src/modules/bash-gate/index.ts` →
 * `src/modules/mailbox/ops/delivery.ts`), so `pending` is precisely the state a
 * loser SHOULD wait on. Counting it as decided fails safe but reintroduces the
 * duplicate cards this whole mechanism removes: every loser arriving more than
 * one host poll (~1s) after the owner staged would raise its own card, and a
 * command needing both the destructive and the email gate would raise four.
 * Every other reader agrees — `pollDeliveredTable` below, and nanoclaw's
 * `container/agent-runner/src/db/delivery-acks.ts`, both treat `pending` as
 * unresolved.
 *
 * Unreadable DB, missing table, anything unexpected: answer TRUE. "I could not
 * check" must refuse the shortcut and make the caller stage its own card, never
 * wave it through.
 */
export function gateRequestAlreadyDecided(requestId: string): boolean {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { Database } = require('bun:sqlite') as typeof import('bun:sqlite');
    let db: import('bun:sqlite').Database | undefined;
    try {
        db = new Database(NANOCLAW_INBOUND_DB, { readonly: true });
        db.exec('PRAGMA busy_timeout = 2000');
        const row = db.prepare('SELECT status FROM delivered WHERE message_out_id = ?').get(requestId) as
            | { status?: string }
            | undefined
            | null;
        return isDecidedGateStatus(row?.status);
    } catch {
        return true;
    } finally {
        try {
            db?.close();
        } catch {
            // Nothing left to do.
        }
    }
}

export type GateClaim =
    | { owner: true }
    /** Another process owns the card; poll `requestId` for the shared decision. */
    | { owner: false; requestId: string }
    /** Nobody published in time — stage your own request (fail-closed). */
    | { owner: false; requestId: null };

/**
 * Claim the right to stage the approval card for `key`, or find out who did.
 *
 * The winner MUST follow up with `publishGateClaim` (on a successful stage) or
 * `abandonGateClaim` (on a failure), or every peer waits out
 * CLAIM_PUBLISH_TIMEOUT_MS and stages its own.
 *
 * Any filesystem failure answers `{ owner: true }`: unable to coordinate means
 * behaving exactly as this code did before the claim existed.
 */
export function claimGateRequest(key: string, nowMs: number = Date.now()): GateClaim {
    const lockPath = `${GATE_CLAIM_DIR}/${key}.lock`;
    const claimPath = `${GATE_CLAIM_DIR}/${key}`;
    try {
        mkdirSync(GATE_CLAIM_DIR, { recursive: true });
        sweepStaleClaims(nowMs);
    } catch {
        return { owner: true };
    }

    try {
        closeSync(openSync(lockPath, 'wx'));
        return { owner: true };
    } catch (err) {
        if ((err as NodeJS.ErrnoException)?.code !== 'EEXIST') return { owner: true };
    }

    // Someone else holds the lock. Wait for them to publish the requestId.
    const deadline = nowMs + CLAIM_PUBLISH_TIMEOUT_MS;
    while (Date.now() < deadline) {
        try {
            const requestId = readFileSync(claimPath, 'utf-8').trim();
            if (requestId) return { owner: false, requestId };
        } catch {
            // Not published yet, or the owner abandoned it — the lock's absence
            // means the latter, and racing for it now would just duplicate the
            // wait, so keep polling until the deadline either way.
        }
        if (!existsSync(lockPath)) break;
        sleepSync(CLAIM_POLL_INTERVAL_MS);
    }
    // One last look: the owner may have published between the final read and
    // the lock disappearing.
    try {
        const requestId = readFileSync(claimPath, 'utf-8').trim();
        if (requestId) return { owner: false, requestId };
    } catch {
        // Genuinely nothing published.
    }
    return { owner: false, requestId: null };
}

/** Publish the owner's requestId, atomically, so losers can poll the same decision. */
export function publishGateClaim(key: string, requestId: string): void {
    const claimPath = `${GATE_CLAIM_DIR}/${key}`;
    try {
        // Written then renamed: a loser must never read a half-written id.
        writeFileSync(`${claimPath}.tmp`, requestId);
        renameSync(`${claimPath}.tmp`, claimPath);
    } catch {
        // A loser falls back to staging its own request — two cards, never none.
    }
}

/** Release a claim the owner could not stage, so a peer can take it over. */
export function abandonGateClaim(key: string): void {
    try {
        unlinkSync(`${GATE_CLAIM_DIR}/${key}.lock`);
    } catch {
        // Never created, or already gone.
    }
}

// ── NanoClaw session-DB approval gate ────────────────────────────────────────
// NOT a side-channel IPC: this rides NanoClaw v2's sole IO surface — the two
// session DBs ("everything is a message"). Direct writes to /workspace/outbound.db
// and polling reads from
// /workspace/inbound.db (both host-managed mounts). Schema stays in sync with
// container/agent-runner/src/db/{connection,messages-out,delivery-acks}.ts in
// the nanoclaw-v2 repo — any schema change there needs a matching change here.

/** Synchronous sleep using Atomics.wait (no busy loop). */
const SLEEP_BUFFER = new Int32Array(new SharedArrayBuffer(4));
export function sleepSync(ms: number): void {
    Atomics.wait(SLEEP_BUFFER, 0, 0, ms);
}

/**
 * Write a request_bash_gate system action to outbound.db. requestId === id,
 * so the container side can poll `delivered` with that same string to learn
 * whether the admin approved. seq must be odd (container-side convention —
 * host uses even). We compute seq under BEGIN IMMEDIATE to serialize against
 * any concurrent writeMessageOut from the agent-runner process.
 */
export type GateAction = 'request_destructive_gate' | 'request_bash_gate' | 'request_prod_gate' | 'request_send_gate';

export function writeGateRequest(
    label: string,
    summary: string,
    command: string,
    action: GateAction = 'request_destructive_gate',
    sendParts?: string[],
): string {
    // Dynamic import so non-NanoClaw environments (plain Claude Code) never
    // touch bun:sqlite — the module is only present under bun runtime.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { Database } = require('bun:sqlite') as typeof import('bun:sqlite');

    const requestId = `gate-${Date.now()}-${randomBytes(4).toString('hex')}`;
    const content = JSON.stringify({
        action,
        requestId,
        label,
        summary,
        // The host renders a bounded head+tail preview and retains the full
        // command in its approval record. Truncating here would discard final
        // arguments before the approver or audit trail could inspect them.
        command,
        ...(sendParts !== undefined ? { sendParts } : {}),
    });

    const outbound = new Database(NANOCLAW_OUTBOUND_DB);
    outbound.exec('PRAGMA busy_timeout = 5000');
    const inbound = new Database(NANOCLAW_INBOUND_DB, { readonly: true });
    inbound.exec('PRAGMA busy_timeout = 5000');
    try {
        outbound.exec('BEGIN IMMEDIATE');
        try {
            const maxOut = (outbound
                .prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_out')
                .get() as { m: number }).m;
            const maxIn = (inbound
                .prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_in')
                .get() as { m: number }).m;
            const max = Math.max(maxOut, maxIn);
            const seq = max % 2 === 0 ? max + 1 : max + 2; // next odd

            outbound
                .prepare(
                    `INSERT INTO messages_out (id, seq, timestamp, kind, content)
                     VALUES ($id, $seq, datetime('now'), 'system', $content)`,
                )
                .run({ $id: requestId, $seq: seq, $content: content });
            outbound.exec('COMMIT');
        } catch (err) {
            try { outbound.exec('ROLLBACK'); } catch { /* ignore */ }
            throw err;
        }
    } finally {
        outbound.close();
        inbound.close();
    }

    return requestId;
}

/**
 * Poll inbound.db's `delivered` table for the host's decision on our
 * requestId. delivered writes come from:
 *   - admin click-through → bash-gate handler writes status='delivered'
 *   - admin rejects / 60-min timeout on the host → status='failed'
 *
 * Opening a fresh connection per poll (instead of persisting one) sidesteps
 * cross-mount visibility issues where a long-held SQLite reader can freeze
 * on an early snapshot and never see host writes — the same reason
 * inbound.db forces journal_mode=DELETE.
 */
export function pollDeliveredTable(requestId: string, timeoutMs: number): GateDecision {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { Database } = require('bun:sqlite') as typeof import('bun:sqlite');
    const deadline = Date.now() + timeoutMs;

    while (Date.now() < deadline) {
        const db = new Database(NANOCLAW_INBOUND_DB, { readonly: true });
        db.exec('PRAGMA busy_timeout = 2000');
        try {
            const row = db
                .prepare('SELECT status FROM delivered WHERE message_out_id = ?')
                .get(requestId) as { status?: string } | undefined;
            if (row && row.status === 'delivered') return 'approved';
            if (row && row.status === 'failed') return 'denied';
        } catch {
            // Schema mismatch (old session DB, table missing) — treat as
            // denied rather than busy-loop forever against a broken surface.
            db.close();
            return 'denied';
        } finally {
            db.close();
        }
        sleepSync(500);
    }
    return 'timeout';
}

/**
 * Lower-level NanoClaw session-DB approval gate, parameterized on the gate
 * `action`. Stage an approval request on outbound.db, then poll inbound.db's
 * `delivered` table for the host's decision (60-min window, matching host
 * BASH_GATE_TIMEOUT_MS).
 *
 * `opts.action` selects the host-side handler the staged request routes to:
 *   - 'request_destructive_gate' — the destructive-command gate (default path).
 *   - 'request_bash_gate'        — the generic bash gate (email gate uses this).
 *   - 'request_prod_gate'        — a production change; the host counts only an owner's or admin's click.
 *   - 'request_send_gate'        — an email or Slack post in a person's name; owner or admin only, and the
 *                                  host skips the card when they already said "send" to a draft showing it.
 *
 * Fail-closed: if writeGateRequest throws (session DBs in a broken state),
 * returns 'denied'. The CALLER emits the stderr/exit — this function never
 * touches process.exit so it stays reusable across hooks.
 *
 * `opts.onStageError` (optional) fires with the staging error before the
 * fail-closed 'denied' return, so a caller can reproduce the original
 * "could not stage approval request" message distinct from an admin denial.
 */
export function runGateRequest(
    command: string,
    reason: string,
    opts: {
        action: GateAction;
        // What a send gate would deliver; the host may accept a person's own "send" to a draft showing all of it.
        sendParts?: string[];
        onStageError?: (err: unknown) => void;
        // Card title and body. Either one omitted falls back to `reason`.
        label?: string;
        summary?: string;
        // The tool call this gate belongs to (`tool_use_id` from the PreToolUse
        // hook input). When given, concurrently-dispatched guards for the SAME
        // tool call share ONE approval card instead of raising one each — see
        // `claimGateRequest`. Omitted, behaviour is exactly as before.
        toolUseId?: string;
    },
): GateDecision {
    const key = opts.toolUseId ? gateClaimKey(opts.toolUseId, opts.action) : null;
    if (key) {
        const claim = claimGateRequest(key);
        if (!claim.owner && claim.requestId && !gateRequestAlreadyDecided(claim.requestId)) {
            // A peer guard already staged this exact card. Wait on ITS decision
            // so the human answers once and both guards honour that one answer.
            return pollDeliveredTable(claim.requestId, 60 * 60 * 1000);
        }
        // Either we own the claim, or nobody published in time. Both stage
        // below; the second case is the fail-closed fallback (two cards beats
        // no gate).
    }

    let requestId: string;
    try {
        requestId = writeGateRequest(opts.label ?? reason, opts.summary ?? reason, command, opts.action, opts.sendParts);
    } catch (err) {
        // If we can't even stage the request, the session DBs are in a broken
        // state. Deny rather than silently allowing — the gate is fail-closed.
        if (key) abandonGateClaim(key);
        opts.onStageError?.(err);
        return 'denied';
    }
    if (key) publishGateClaim(key, requestId);

    return pollDeliveredTable(requestId, 60 * 60 * 1000); // 60 min, matches host BASH_GATE_TIMEOUT_MS
}

/**
 * NanoClaw destructive-command session-DB approval gate. Thin wrapper over
 * runGateRequest with action='request_destructive_gate'.
 *
 * SIGNATURE IS LOAD-BEARING — `(command, reason, onStageError?, toolUseId?, cwd?)`.
 * Existing callers (block-destructive.ts, opencode-guard.ts) pass the
 * onStageError callback as the 3rd positional arg. Do NOT add a positional
 * `action` here; route action selection through runGateRequest instead.
 *
 * `toolUseId` is APPENDED rather than folded into an options object for the same
 * reason: a caller on an older container image passes three arguments and keeps
 * working, and a caller that passes four gets one approval card per tool call
 * even when two guards gate the same command concurrently. `cwd` is appended
 * for the same reason; it lets the description match a lab-scope verdict.
 */
export function runNanoclawGate(
    command: string,
    reason: string,
    onStageError?: (err: unknown) => void,
    toolUseId?: string,
    cwd?: string,
): GateDecision {
    const action = changesProduction(command, cwd) ? 'request_prod_gate' : 'request_destructive_gate';
    return runGateRequest(command, reason, { action, onStageError, toolUseId, ...describeGate(command, reason, cwd) });
}

/**
 * Whether a step the gate stops on may change Render production: a render step, or one whose verdict came from a
 * render command it runs (a SQL client's shell escape, inline or from a file). A command the guard cannot read
 * counts if it names render.
 */
export function changesProduction(command: string, cwd: string = currentWorkingDir()): boolean {
    try {
        const commands = extractCommands(command);
        if (commands[0]?.script) commands[0].script.cwd = cwd;
        return [...gatedSteps(commands, command, cwd, isLabSession(), false)].some(step => step.cmd.name === 'render' || step.reason.includes(RENDER_CHANGE_REASON) || step.reason.includes(CLIENT_PROGRAM_GATE) || /\brender\b/.test(step.cmd.raw));
    } catch {
        return /\brender\b/.test(command);
    }
}

/**
 * NanoClaw email session-DB approval gate. Thin wrapper over runGateRequest
 * with action='request_bash_gate' — the same host-side handler the in-tree
 * email gate uses (nanoclaw claude.ts createEmailGateHook).
 *
 * `(command, reason, onStageError?, summary?)` — the first three positionals
 * match runNanoclawGate (load-bearing: existing callers/tests pass onStageError
 * 3rd). The optional 4th `summary` carries evaluateEmailSend's structured card
 * body (from/to/cc/bcc/body); when omitted, the card falls back to `reason` for
 * both label and summary. Threading summary gives OpenCode's approval card the
 * same structured content as Claude's in-tree card (S-QA2 parity).
 */
export function runEmailGate(
    command: string,
    reason: string,
    onStageError?: (err: unknown) => void,
    summary?: string,
    toolUseId?: string,
): GateDecision {
    const sendParts = sendPartsByCommand.get(command);
    sendPartsByCommand.delete(command);
    return runGateRequest(command, reason, {
        action: 'request_send_gate', onStageError, summary, toolUseId, ...(sendParts ? { sendParts } : {}),
    });
}

const sendPartsByCommand = new Map<string, string[]>();

/** Records what a send delivers for its gate request: `evaluateEmailSend` reads the command, `runEmailGate` stages it. */
export function noteSendParts(command: string, parts: string[] | null): void {
    if (parts) sendPartsByCommand.set(command, parts);
    else sendPartsByCommand.delete(command);
}

// ── Repositories agents never merge into ─────────────────────────────────────
// Some repositories belong to another team: agents open draft pull requests there and hand them over, and never
// merge or push to a protected branch. Which repositories and branches is deployment data in an untracked
// `merge-scope.local.json`, found like lab-scope.local.json:
//   {"noMerge": {"<org>/<repo>": ["<protected branch>", …]}}
// No file refuses nothing. A file that can't be read or parsed refuses every merge it can see.

export const MERGE_SCOPE_FILE_ENV = 'BOOTSTRAP_MERGE_SCOPE_FILE';
const MERGE_SCOPE_FILE = 'merge-scope.local.json';
const GITHUB_REPO_IN_TEXT_RE = /github\.com(?::\d+)?[/:]([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+?)(?:\.git)?(?=[/?#\s]|$)/;
const API_MERGE_RE = /(?:^|[\s/])repos\/(\S+?)\/(?:pulls\/[^/\s]+\/merge|merges)\b/;
const GRAPHQL_MERGE_RE = /\b(?:mergePullRequest|enablePullRequestAutoMerge|mergeBranch)\b/;

export type MergeScope = Map<string, Set<string>>;

/** Parse a merge-scope file's text, keyed by lower-cased `org/repo`. Null when anything about it is unusable. */
export function parseMergeScope(text: string): MergeScope | null {
    let raw: unknown;
    try {
        raw = JSON.parse(text);
    } catch {
        return null;
    }
    const entries = (raw as { noMerge?: unknown } | null)?.noMerge;
    if (!entries || typeof entries !== 'object' || Array.isArray(entries)) return null;
    const scope: MergeScope = new Map();
    for (const [repo, branches] of Object.entries(entries)) {
        if (!ORG_REPO_RE.test(repo) || !Array.isArray(branches) || branches.length === 0
            || !branches.every((b: unknown) => typeof b === 'string' && /^[A-Za-z0-9._/-]{1,200}$/.test(b))) {
            return null;
        }
        scope.set(repo.toLowerCase(), new Set(branches as string[]));
    }
    return scope;
}

function currentMergeScope(): MergeScope | null | 'unreadable' {
    const file = deploymentFilePath(MERGE_SCOPE_FILE, MERGE_SCOPE_FILE_ENV);
    if (!file || !existsSync(file)) return null;
    try {
        return parseMergeScope(readFileSync(file, 'utf-8')) ?? 'unreadable';
    } catch {
        return 'unreadable';
    }
}

/** `org/repo` a remote URL, `org/repo` word or GitHub URL names, lower-cased; null for anything else. */
function githubRepoOf(value: string): string | null {
    const url = GITHUB_REPO_IN_TEXT_RE.exec(value);
    if (url) return `${url[1]}/${url[2]}`.toLowerCase();
    return ORG_REPO_RE.test(value) && !REPO_URL_RE.test(value) ? value.replace(/\.git$/, '').toLowerCase() : null;
}

/** The git directory and common directory of the checkout containing `dir`, or null. */
function gitDirsOf(dir: string): { gitDir: string; commonDir: string } | null {
    let current = pathResolve(dir);
    for (;;) {
        const dotGit = join(current, '.git');
        try {
            const stat = statSync(dotGit);
            let gitDir = dotGit;
            if (stat.isFile()) {
                const pointer = /^gitdir:\s*(.+)$/m.exec(readFileSync(dotGit, 'utf-8'));
                if (!pointer) return null;
                gitDir = pathResolve(current, pointer[1].trim());
            }
            let commonDir = gitDir;
            try {
                commonDir = pathResolve(gitDir, readFileSync(join(gitDir, 'commondir'), 'utf-8').trim());
            } catch {
                commonDir = gitDir;
            }
            return { gitDir, commonDir };
        } catch {
            const parent = dirname(current);
            if (parent === current) return null;
            current = parent;
        }
    }
}

/** The repository a checkout's remote points at, read from its git config. */
function checkoutRemoteRepo(dir: string, remote = 'origin'): string | null {
    const dirs = gitDirsOf(dir);
    if (!dirs) return null;
    let config: string;
    try {
        config = readFileSync(join(dirs.commonDir, 'config'), 'utf-8');
    } catch {
        return null;
    }
    const section = new RegExp(String.raw`^\[remote\s+"${remote.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}"\]([^[]*)`, 'm').exec(config);
    const url = section ? /^\s*url\s*=\s*(.+)$/m.exec(section[1])?.[1].trim() : undefined;
    return url ? githubRepoOf(url) : null;
}

/**
 * Every GitHub repository a checkout's remotes point at. gh picks among them (upstream, then github, then origin),
 * so a command that lets gh choose may reach any of them.
 */
function checkoutRemoteRepos(dir: string): Array<string | null> {
    const dirs = gitDirsOf(dir);
    if (!dirs) return [null];
    let config: string;
    try {
        config = readFileSync(join(dirs.commonDir, 'config'), 'utf-8');
    } catch {
        return [null];
    }
    const names = [...config.matchAll(/^\[remote\s+"([^"]+)"\]/gm)].map(m => m[1]);
    return names.length ? names.map(name => checkoutRemoteRepo(dir, name)) : [null];
}

/** The branch a checkout has out, or null when detached or unreadable. */
function checkoutBranch(dir: string): string | null {
    const dirs = gitDirsOf(dir);
    if (!dirs) return null;
    try {
        return /^ref:\s*refs\/heads\/(.+)$/m.exec(readFileSync(join(dirs.gitDir, 'HEAD'), 'utf-8'))?.[1].trim() ?? null;
    } catch {
        return null;
    }
}

/**
 * Undefined when no earlier step moves the checked-out branch; null when one does (a switch, a checkout, a branch
 * rename, `gh pr checkout`), since what it leaves checked out isn't read.
 */
function headAfterSwitches(earlier: ResolvedCommand[]): null | undefined {
    return earlier.some(c => {
        if (c.name === 'gh') { const g = ghArgs(c.args).args; return g[0] === 'pr' && ['checkout', 'co'].includes(g[1]); }
        if (c.name !== 'git') return false;
        const sub = c.args[gitSubcommandIndex(c.args)];
        if (sub === 'switch' || sub === 'checkout') return true;
        return sub === 'branch' && c.args.some(a => /^-[a-zA-Z]*[mM]|^--move$/.test(a));
    }) ? null : undefined;
}

/** Branch names a `git push` writes to, or null when it may write to every branch or the guard can't tell. */
function pushedBranches(args: string[], dir: string | null, head?: string | null): string[] | null {
    const sub = gitSubcommandIndex(args);
    const rest = args.slice(sub + 1);
    if (rest.some(a => /^--[a-z]/.test(a) && ['all', 'mirror', 'branches'].some(o => o.startsWith(a.slice(2))))) return null;
    const positionals = pushArgsWithoutValues(rest).filter(a => !a.startsWith('-'));
    const refspecs = positionals.slice(1);
    // `--tags` alone pushes tags and no branch.
    if (refspecs.length === 0 && rest.includes('--tags')) return [];
    if (refspecs.length === 0) {
        const branch = head !== undefined ? head : dir ? checkoutBranch(dir) : null;
        return branch ? [branch] : null;
    }
    const names: string[] = [];
    for (const spec of refspecs) {
        const target = (spec.includes(':') ? spec.slice(spec.indexOf(':') + 1) : spec).replace(/^\+/, '').replace(/^refs\/heads\//, '');
        if (target === 'HEAD' || target === '') {
            const branch = head !== undefined ? head : dir ? checkoutBranch(dir) : null;
            if (!branch) return null;
            names.push(branch);
        } else if (/[$`*]/.test(target)) {
            return null;
        } else {
            names.push(target);
        }
    }
    return names;
}

/** The last value a command gives `name`: its own prefix, else an earlier `export`, else what the session inherited. */
function assignedValue(name: string, cmd: ResolvedCommand, commands: ResolvedCommand[]): string | undefined {
    const pick = (entries: string[]) => entries.map(e => e.startsWith(`${name}=`) ? e.slice(name.length + 1) : undefined).filter((v): v is string => v !== undefined).at(-1);
    return pick(cmd.env ?? []) ?? pick(commands.slice(0, commands.indexOf(cmd)).flatMap(c => c.name === 'export' ? c.args : [])) ?? process.env[name];
}

/** `gh`'s arguments with the inherited `-R`/`--repo` taken out, and the repository it names. */
function ghArgs(args: string[]): { args: string[]; repo: string | undefined } {
    const rest: string[] = [];
    let repo: string | undefined;
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a === '-R' || a === '--repo') repo = args[++i];
        else if (a.startsWith('--repo=')) repo = a.slice('--repo='.length);
        else if (/^-R./.test(a)) repo = a.slice(2);
        else rest.push(a);
    }
    return { args: rest, repo };
}

/** Why a command merges into, or pushes to a protected branch of, a repository agents never merge into. */
function noMergeReason(commands: ResolvedCommand[], cwd: string, line: string): string | null {
    const scope = currentMergeScope();
    if (scope === null) return null;
    const refused = (repo: string | null, what: string): string | null => {
        if (scope === 'unreadable') return `${what}: merge-scope.local.json can't be read, so every merge is refused until it's fixed.`;
        if (repo === null || !scope.has(repo)) return null;
        return `${what} in ${repo}, which belongs to another team. Open the pull request as a draft and hand it to them; agents never merge there.`;
    };
    let dirs: string[] | null = [cwd];
    for (const cmd of commands) {
        if (DIRECTORY_CHANGERS.has(cmd.name)) dirs = directoriesAfter(dirs, cmd);
        // After a cd the step may run in any of the directories it could have reached; each one is checked.
        const places: Array<string | null> = dirs && !/[$`]/.test(cmd.chdir ?? '') ? dirs.map(d => pathResolve(d, cmd.chdir ?? '.')) : [null];
        const earlier = commands.slice(0, commands.indexOf(cmd));
        const head = headAfterSwitches(earlier);
        // A remote added, renamed or repointed, or a clone, earlier in the step leaves the checkout's repository unread.
        const remotesMoved = earlier.some(c => (c.name === 'git' && (['remote', 'clone'].includes(c.args[gitSubcommandIndex(c.args)])
            || (c.args[gitSubcommandIndex(c.args)] === 'config' && c.args.some(a => /^remote\./.test(a)))))
            || (c.name === 'gh' && ghArgs(c.args).args[0] === 'repo' && ['clone', 'fork'].includes(ghArgs(c.args).args[1])));
        for (const dir of places) {
            const reason = noMergeStepReason(cmd, commands, dir, scope, refused, head, line, remotesMoved);
            if (reason) return reason;
        }
    }
    return null;
}

/**
 * The repository a REST merge call (`repos/<owner>/<repo>/pulls/<n>/merge`, `…/merges`) in `text` merges into:
 * undefined when it makes none, 'unresolved' when any part is a variable, 'unplaced' when gh's {owner}/{repo}
 * must come from a checkout the guard can't place. gh fills {owner}/{repo} from GH_REPO, else from its checkout.
 */
function apiMergeTarget(
    text: string,
    ghRepo: string | undefined,
    dir: string | null,
    remotesOf: (dir: string) => Array<string | null>,
): Array<string | null> | 'unresolved' | 'unplaced' | undefined {
    const match = API_MERGE_RE.exec(text);
    if (!match) return undefined;
    if (/[$`]/.test(match[0])) return 'unresolved';
    if (!/\{owner\}|\{repo\}/.test(match[1])) return [match[1].toLowerCase()];
    if (ghRepo !== undefined && /[$`]/.test(ghRepo)) return 'unresolved';
    if (ghRepo === undefined && dir === null) return 'unplaced';
    const fills = ghRepo !== undefined ? [githubRepoOf(ghRepo)] : remotesOf(dir!);
    return fills.map(fill => {
        if (fill === null) return null;
        const [owner, repo] = fill.split('/');
        return match[1].replace('{owner}', owner).replace('{repo}', repo).toLowerCase();
    });
}

/** The directory a git push runs in from `dir`, after every `-C` and `--work-tree` before its subcommand; null when unknown. */
function gitPushDir(args: string[], dir: string | null): string | null {
    let at = dir;
    const sub = gitSubcommandIndex(args);
    for (let i = 0; i < sub; i++) {
        const value = args[i] === '-C' || args[i] === '--work-tree' ? args[++i]
            : args[i].startsWith('--work-tree=') ? args[i].slice('--work-tree='.length) : undefined;
        if (value === undefined) continue;
        if (at === null || /[$`]/.test(value)) return null;
        at = pathResolve(at, value);
    }
    return at;
}

const GH_MERGE_VALUE_FLAGS = new Set(['-b', '--body', '-F', '--body-file', '-t', '--subject', '--match-head-commit', '-A', '--author-email']);

/** The pull request a `gh pr merge` names (number, branch or URL), past its own options; undefined for the current branch's. */
function ghMergeSelector(args: string[]): string | undefined {
    for (let i = 0; i < args.length; i++) {
        if (GH_MERGE_VALUE_FLAGS.has(args[i])) i++;
        else if (!args[i].startsWith('-')) return args[i];
    }
    return undefined;
}

/** Why one step merges into, or pushes to a protected branch of, a listed repository when run in `dir`. */
function noMergeStepReason(
    cmd: ResolvedCommand,
    commands: ResolvedCommand[],
    dir: string | null,
    scope: MergeScope | 'unreadable',
    refused: (repo: string | null, what: string) => string | null,
    head: null | undefined,
    line: string,
    remotesMoved: boolean,
): string | null {
    const remotesOf = (d: string): Array<string | null> => remotesMoved ? [null] : checkoutRemoteRepos(d);
    // gh ignores a remote off GitHub, so a checkout is unread only when none of its remotes names a GitHub repository.
    const checked = (repos: Array<string | null>, what: string): string | null => {
        const known = repos.filter((r): r is string => r !== null);
        if (known.length === 0) return scope === 'unreadable' ? refused(null, what) : `${what}: the guard can't read which repository this checkout points at, so it is refused. Name it with -R <owner>/<repo>.`;
        return known.map(repo => refused(repo, what)).find(Boolean) ?? null;
    };
    const text = cmd.args.join(' ');
    const unresolved = (what: string) => `${what}: its repository is only known when the command runs, so it is refused. Name the repository literally.`;
    const unplaced = (what: string) => scope === 'unreadable' ? refused(null, what) : `${what} from a directory the guard can't place (a cd it can't follow), so it is refused. Run it from the checkout, or name the repository.`;
    const gh = cmd.name === 'gh' ? ghArgs(cmd.args) : null;
    // gh treats an empty GH_REPO as unset.
    const ghRepo = assignedValue('GH_REPO', cmd, commands) || undefined;
    if (gh && gh.args[0] === 'pr' && gh.args[1] === 'merge') {
        const selector = ghMergeSelector(gh.args.slice(2));
        const url = selector !== undefined && GITHUB_REPO_IN_TEXT_RE.test(selector) ? selector : undefined;
        const named = [gh.repo, url, ghRepo].filter((v): v is string => v !== undefined);
        if ([...named, selector ?? ''].some(v => /[$`]/.test(v))) return unresolved('Merging a pull request');
        if (named.length === 0 && dir === null) return unplaced('Merging a pull request');
        const reason = named.length
            ? named.map(githubRepoOf).map(r => refused(r, 'Merging a pull request')).find(Boolean) ?? null
            : checked(remotesOf(dir!), 'Merging a pull request');
        if (reason) return reason;
    }
    const apiClient = (cmd.name === 'gh' && cmd.args[0] === 'api') || HTTP_CLIENTS.has(cmd.name);
    const api = apiClient ? apiMergeTarget(text, ghRepo, dir, remotesOf) : undefined;
    if (api === 'unresolved') return unresolved('Merging through the API');
    // An endpoint written only into a variable (ENDPOINT=repos/…/merge; gh api "$ENDPOINT") is a merge the words don't show.
    if (api === undefined && apiClient && cmd.args.some(a => /[$`]/.test(a)) && /repos\/\S+?\/(?:pulls\/[^/\s]+\/merge|merges)\b/.test(line)) return unresolved('Merging through the API');
    if (api === 'unplaced') return unplaced('Merging through the API');
    const apiReason = api !== undefined ? checked(api, 'Merging through the API') : null;
    if (apiReason) return apiReason;
    if (((cmd.name === 'gh' && cmd.args[0] === 'api') || HTTP_CLIENTS.has(cmd.name)) && GRAPHQL_MERGE_RE.test(text)) {
        if (dir === null) return unplaced('Merging through the GraphQL API');
        const reason = checked(remotesOf(dir), 'Merging through the GraphQL API');
        if (reason) return reason;
    }
    if (/(?:^|\/)codex-review\.sh$/.test(cmd.name) && cmd.args[0] === 'merge') {
        const assigned = assignedValue('REPO', cmd, commands);
        if (assigned !== undefined && /[$`]/.test(assigned)) return unresolved('Merging a pull request');
        if (assigned === undefined && dir === null) return unplaced('Merging a pull request');
        const reason = assigned !== undefined ? refused(githubRepoOf(assigned), 'Merging a pull request') : checked(remotesOf(dir!), 'Merging a pull request');
        if (reason) return reason;
    }
    if (cmd.name === 'git' && cmd.args[gitSubcommandIndex(cmd.args)] === 'push') {
        const pushDir = gitPushDir(cmd.args, dir);
        const remote = gitRemoteArg(cmd.args);
        // A push to a URL off GitHub reaches no listed repository.
        if (remote && /^(?:[a-z+]+:\/\/|[^@\s]+@)/i.test(remote) && !/github\.com[/:]/i.test(remote)) return null;
        const repo = remote && (REPO_URL_RE.test(remote) || ORG_REPO_RE.test(remote))
            ? githubRepoOf(remote)
            : pushDir && !remotesMoved ? checkoutRemoteRepo(pushDir, remote ?? 'origin') : null;
        const branches = pushedBranches(cmd.args, pushDir, head);
        if (scope === 'unreadable') return refused(null, 'Pushing');
        const protectedHere = repo !== null ? scope.get(repo) : undefined;
        if (protectedHere && (branches === null || branches.some(b => protectedHere.has(b)))) {
            return refused(repo, `Pushing to ${branches === null ? 'every branch, or one the guard cannot read (after a branch switch, name it: git push origin <branch>)' : branches.join(', ')}`);
        }
        if (repo === null && branches === null) return unplaced('Pushing to every branch');
        if (repo === null && branches !== null) {
            const anywhere = [...scope.entries()].find(([, set]) => branches.some(b => set.has(b)));
            if (anywhere) return refused(anywhere[0], `Pushing to ${branches.join(', ')} from a checkout the guard can't place`);
        }
    }
    return null;
}

// ── Slack posts in a person's name ───────────────────────────────────────────
// A Slack Web API call made with a person's user token posts as that person. Which workgroups and OneCLI
// identities hold such a token, and must not post without that person's OK, is deployment data in an
// untracked `send-scope.local.json`, found like lab-scope.local.json:
//   {"slack": {"workgroups": ["<workgroup id>"], "onecliAgents": ["<onecli agent id>"]}}
// No file gates nothing. A file that can't be read or parsed gates every Slack post.

export const SEND_SCOPE_FILE_ENV = 'BOOTSTRAP_SEND_SCOPE_FILE';
const UNKNOWN_ONECLI_AGENT = '\0unknown';
const SEND_SCOPE_FILE = 'send-scope.local.json';
const SLACK_POST_METHODS = new Set([
    'chat.postMessage', 'chat.update', 'chat.scheduleMessage', 'chat.meMessage', 'chat.delete',
    'files.completeUploadExternal', 'files.upload', 'files.share',
]);
const SLACK_API_METHOD_RE = /slack\.com\/api\/([A-Za-z.]+)/g;
const HTTP_CLIENTS = new Set(['curl', 'wget', 'http', 'https', 'xh', 'xhs']);
const CURL_BODY_FLAGS = new Set(['--data', '--data-raw', '--data-binary', '--data-ascii', '--data-urlencode', '--json', '--form', '--form-string']);
/** Every curl option a readable post may use, short spellings mapped to their long names; true when it takes a value. */
const CURL_SHORT: Record<string, string> = {
    d: '--data', F: '--form', H: '--header', X: '--request', o: '--output', m: '--max-time', w: '--write-out',
    A: '--user-agent', u: '--user', b: '--cookie', e: '--referer', x: '--proxy',
    s: '--silent', S: '--show-error', f: '--fail', L: '--location', k: '--insecure', v: '--verbose', i: '--include',
    g: '--globoff', G: '--get', N: '--no-buffer',
};
const CURL_LONG: Record<string, boolean> = {
    '--data': true, '--data-raw': true, '--data-binary': true, '--data-ascii': true, '--data-urlencode': true, '--json': true,
    '--form': true, '--form-string': true, '--header': true, '--request': true, '--output': true, '--max-time': true,
    '--connect-timeout': true, '--retry': true, '--write-out': true, '--user-agent': true, '--user': true, '--url': true,
    '--cookie': true, '--referer': true, '--proxy': true,
    '--silent': false, '--show-error': false, '--fail': false, '--fail-with-body': false, '--location': false,
    '--insecure': false, '--verbose': false, '--include': false, '--globoff': false, '--get': false, '--no-buffer': false,
    '--compressed': false, '--http1.1': false, '--http2': false, '--no-progress-meter': false,
};

export interface SendScope {
    slack: { workgroups: string[]; onecliAgents: string[] };
}

export interface SlackPost {
    method: string;
    /** The message text, when the command states it literally and once; null otherwise. */
    text: string | null;
    /** The OneCLI identity named by an `onecli run --agent` wrapper, if any. */
    onecliAgent: string | null;
}

/** Parse a send-scope file's text. Null when anything about it is unusable. */
export function parseSendScope(text: string): SendScope | null {
    let raw: unknown;
    try {
        raw = JSON.parse(text);
    } catch {
        return null;
    }
    const slack = (raw as { slack?: unknown } | null)?.slack as { workgroups?: unknown; onecliAgents?: unknown } | undefined;
    const names = (v: unknown) => v === undefined ? [] : Array.isArray(v) && v.every(x => typeof x === 'string' && /^[A-Za-z0-9._-]{1,128}$/.test(x)) ? v as string[] : null;
    if (!slack || typeof slack !== 'object') return null;
    const workgroups = names(slack.workgroups);
    const onecliAgents = names(slack.onecliAgents);
    if (!workgroups || !onecliAgents) return null;
    return { slack: { workgroups, onecliAgents } };
}

/** The scope in force: null when no file exists, 'unreadable' when one exists and can't be used. */
function currentSendScope(): SendScope | null | 'unreadable' {
    const file = deploymentFilePath(SEND_SCOPE_FILE, SEND_SCOPE_FILE_ENV);
    if (!file || !existsSync(file)) return null;
    try {
        return parseSendScope(readFileSync(file, 'utf-8')) ?? 'unreadable';
    } catch {
        return 'unreadable';
    }
}

function literal(value: string): boolean {
    return !/[$`]/.test(value) && !value.startsWith('@');
}

const SLACK_TEXT_METHODS = new Set(['chat.postMessage', 'chat.update', 'chat.scheduleMessage', 'chat.meMessage']);
/** Fields that change where or how a message posts, never what it says. Any other field may carry content. */
const SLACK_ROUTING_FIELDS = new Set([
    'token', 'channel', 'ts', 'thread_ts', 'reply_broadcast', 'post_at', 'as_user', 'username', 'icon_emoji', 'icon_url',
    'mrkdwn', 'parse', 'link_names', 'unfurl_links', 'unfurl_media',
]);

type BodyField = { key: string; value: string | null };

/** The fields one body argument sends; null when they can't all be read from the command line. */
function bodyFields(flag: string, value: string): BodyField[] | null {
    if (!literal(value)) return null;
    if (flag === '--json' || value.trimStart().startsWith('{')) {
        try {
            const body = JSON.parse(value) as Record<string, unknown>;
            if (!body || typeof body !== 'object' || Array.isArray(body)) return null;
            return Object.entries(body).map(([key, v]) => ({ key, value: typeof v === 'string' ? v : null }));
        } catch {
            return null;
        }
    }
    if (flag === '--form' || flag === '--form-string') {
        const at = value.indexOf('=');
        if (at < 0) return null;
        const v = value.slice(at + 1);
        // curl reads `;type=`, `;filename=` and the like after a --form value, so a ';' may cut the text short, and a
        // value opening with '"' is read as a quoted string that ends at its closing quote.
        return [{ key: value.slice(0, at), value: flag !== '--form-string' && (/^[<@"]/.test(v) || v.includes(';')) ? null : v }];
    }
    if (flag === '--data-urlencode') {
        const at = value.indexOf('=');
        return at < 0 ? null : [{ key: value.slice(0, at), value: value.slice(at + 1) }];
    }
    const fields: BodyField[] = [];
    for (const pair of value.split('&')) {
        const at = pair.indexOf('=');
        if (at < 0) return null;
        try {
            fields.push({ key: decodeURIComponent(pair.slice(0, at)), value: decodeURIComponent(pair.slice(at + 1).replace(/\+/g, ' ')) });
        } catch {
            return null;
        }
    }
    return fields;
}

type CurlOption = { flag: string; value: string | undefined };

/**
 * A curl command line in one spelling: `--flag=value`, `-Fvalue` and clusters like `-sSd` become separate long
 * options. Null when it uses an option outside the known set, since an unknown one may add a request or a body.
 */
function curlOptions(args: string[]): { options: CurlOption[]; urls: string[] } | null {
    const options: CurlOption[] = [];
    const urls: string[] = [];
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === '--') {
            urls.push(...args.slice(i + 1));
            break;
        }
        if (arg.startsWith('--')) {
            const at = arg.indexOf('=');
            const flag = at < 0 ? arg : arg.slice(0, at);
            const takesValue = CURL_LONG[flag];
            if (takesValue === undefined) return null;
            const value = takesValue ? (at < 0 ? args[++i] : arg.slice(at + 1)) : undefined;
            if (takesValue && value === undefined) return null;
            if (flag === '--url') urls.push(value!);
            else options.push({ flag, value });
            continue;
        }
        if (!arg.startsWith('-') || arg === '-') {
            urls.push(arg);
            continue;
        }
        for (let c = 1; c < arg.length; c++) {
            const flag = CURL_SHORT[arg[c]];
            if (!flag) return null;
            if (!CURL_LONG[flag]) {
                options.push({ flag, value: undefined });
                continue;
            }
            const value = c + 1 < arg.length ? arg.slice(c + 1) : args[++i];
            if (value === undefined) return null;
            options.push({ flag, value });
            break;
        }
    }
    return { options, urls };
}

function slackPostIn(name: string, args: string[], onecliAgent: string | null): SlackPost | null {
    if (!HTTP_CLIENTS.has(name)) return null;
    const methods = args.flatMap(a => [...a.matchAll(SLACK_API_METHOD_RE)].map(m => m[1]));
    const method = methods.find(m => SLACK_POST_METHODS.has(m));
    if (!method) return null;
    const line = name === 'curl' ? curlOptions(args) : null;
    let readable = SLACK_TEXT_METHODS.has(method) && line !== null && line.urls.length === 1;
    const fields: BodyField[] = [];
    for (const { flag, value } of readable ? line!.options : []) {
        if (!CURL_BODY_FLAGS.has(flag)) continue;
        const parsed = bodyFields(flag, value!);
        if (parsed) fields.push(...parsed);
        else readable = false;
    }
    const url = readable ? line!.urls[0].split('#')[0] : '';
    const query = url.includes('?') ? url.slice(url.indexOf('?') + 1) : undefined;
    if (readable && query) {
        const parsed = bodyFields('--data', query);
        if (parsed) fields.push(...parsed);
        else readable = false;
    }
    const texts = fields.filter(f => f.key === 'text');
    readable &&= texts.length === 1 && fields.every(f => f.key === 'text' || SLACK_ROUTING_FIELDS.has(f.key));
    return { method, text: readable ? texts[0].value : null, onecliAgent };
}

/** A posting URL in the words of a command the guard doesn't read as a client (a wrapper, a shell): a post it can't read. */
function carriedPost(words: string[], onecliAgent: string | null): SlackPost | null {
    const method = words.flatMap(w => [...w.matchAll(SLACK_API_METHOD_RE)].map(m => m[1])).find(m => SLACK_POST_METHODS.has(m));
    return method ? { method, text: null, onecliAgent } : null;
}

/** Every Slack post a command makes, inside an `onecli run … --` wrapper too. */
export function slackPostsOf(command: string): SlackPost[] {
    let commands: ResolvedCommand[];
    try {
        commands = extractCommands(command);
    } catch {
        return /slack\.com\/api\/(?:chat|files)\./.test(command) ? [{ method: 'unknown', text: null, onecliAgent: null }] : [];
    }
    const posts: SlackPost[] = [];
    for (const cmd of commands) {
        const agent = cmd.onecliAgent === undefined ? null : /[$`]/.test(cmd.onecliAgent) ? UNKNOWN_ONECLI_AGENT : cmd.onecliAgent;
        const post = slackPostIn(cmd.name, cmd.args, agent) ?? carriedPost(cmd.args, agent);
        if (post) posts.push(post);
    }
    // A posting URL the commands never carry as a word (held in a variable assignment, say) is still a post the
    // guard can't read: under each OneCLI identity the line names that no read post carries, or under none.
    // A host or base URL held in a variable (`${SLACK_API}chat.postMessage`) leaves the method name beside it.
    const heldMethod = /slack\.com/.test(command)
        ? [...command.matchAll(/\b((?:chat|files)\.[A-Za-z]+)\b/g)].map(m => m[1]).find(m => SLACK_POST_METHODS.has(m))
        : undefined;
    const held = carriedPost([command], null) ?? (heldMethod ? { method: heldMethod, text: null, onecliAgent: null } : null);
    if (held) {
        const named = [...command.replace(/\\\n/g, ' ').matchAll(/\bonecli\s+run\b[^;&|]*?--agent[=\s]+([^\s;&|]+)/g)]
            .map(m => m[1].replace(/^(['"])(.*)\1$/, '$2'))
            .map(n => /[$`]/.test(n) ? UNKNOWN_ONECLI_AGENT : n);
        // A direct HTTP call whose URL a variable holds may be the post itself, in the session's own name.
        const direct = posts.length === 0 || commands.some(c => HTTP_CLIENTS.has(c.name) && c.onecliAgent === undefined && c.args.some(w => /[$`]/.test(w)));
        for (const agent of direct ? [null, ...named] : named) {
            if (!posts.some(p => p.onecliAgent === agent)) posts.push({ ...held, onecliAgent: agent });
        }
    }
    return posts;
}

/** True when the line is one command and nothing else, so what a send delivers can be all it does. */
export function soleCommand(command: string): boolean {
    try {
        const commands = extractCommands(command);
        return commands.length === 1 && commands[0].raw.trim() === command.trim();
    } catch {
        return false;
    }
}

/** The Slack posts in a command that need their sender's OK under the send scope in force. */
export function gatedSlackPosts(command: string, workgroupId: string | undefined = process.env.NANOCLAW_WORKGROUP_ID): SlackPost[] {
    if (!/slack\.com/.test(command)) return [];
    const posts = slackPostsOf(command);
    if (posts.length === 0) return [];
    const scope = currentSendScope();
    if (scope === null) return [];
    if (scope === 'unreadable') return posts;
    const inWorkgroup = workgroupId !== undefined && scope.slack.workgroups.includes(workgroupId);
    // An identity only known when the command runs may be any listed one.
    return posts.filter(p => p.onecliAgent === UNKNOWN_ONECLI_AGENT ? scope.slack.onecliAgents.length > 0 || inWorkgroup
        : p.onecliAgent !== null ? scope.slack.onecliAgents.includes(p.onecliAgent) : inWorkgroup);
}
